INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-2')::uuid,'PSR','Chapter 1: Structure & Appointments','Within what period should an appeal from an aggrieved Officer be handled and concluded?','["Within one month","Within six months","Within two years","Within three weeks"]'::jsonb,1,'Correct. Under PSR Chapter 11, Section 2, Rule 110201, an appeal from an aggrieved Officer shall be handled and concluded within six months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-3')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 110201 applies to which category of Officer?','["Only retired contractors","An aggrieved Officer","Only political appointees","Only members of the public"]'::jsonb,1,'Correct. Under PSR Rule 110201, the timing provision applies to an appeal from an aggrieved Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-4')::uuid,'PSR','Chapter 1: Structure & Appointments','Before proceeding to court, what should Officers do as much as possible under Rule 110201?','["Ignore internal service procedures","Exhaust all avenues provided in the Public Service Rules and Circulars for redress","Proceed directly to the media","Seek political intervention"]'::jsonb,1,'Correct. Under PSR Rule 110201(i), Officers should, as much as possible, exhaust all avenues provided in the Public Service Rules and Circulars for redress before proceeding to courts.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-5')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 110201 recognises Officers’ constitutional rights but still encourages what?','["Immediate resignation before complaint","Use of political pressure","Exhaustion of internal redress channels before court action","Refusal to submit petitions"]'::jsonb,2,'Correct. Under PSR Rule 110201(i), without prejudice to constitutional rights, Officers are expected as much as possible to exhaust PSR and Circular redress avenues before going to court.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-6')::uuid,'PSR','Chapter 1: Structure & Appointments','An Officer who wishes to proceed to court must obtain formal approval from whom?','["The Head of the Civil Service of the Federation","The Staff Union Chairman","The Officer’s colleague","The nearest police station"]'::jsonb,0,'Correct. Under PSR Rule 110201(ii), any Officer who wishes to proceed to court shall obtain formal approval from the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-7')::uuid,'PSR','Chapter 1: Structure & Appointments','What happens to an Officer who takes his employer to court without following the due process stated in Rule 110201?','["He is automatically promoted","He is placed on suspension pending determination of the case","He receives double salary","He is transferred abroad"]'::jsonb,1,'Correct. Under PSR Rule 110201(iii), an Officer who takes his employer to court without following the stated due process shall be placed on suspension pending determination of the case.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-8')::uuid,'PSR','Chapter 1: Structure & Appointments','The suspension under Rule 110201 for taking an employer to court without due process lasts until when?','["Until the case is determined","Until the Officer travels abroad","Until the Officer writes a newspaper article","Until the next promotion exercise"]'::jsonb,0,'Correct. Under PSR Rule 110201(iii), suspension applies pending the determination of the court case.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-9')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best reflects Rule 110201 on court action?','["Officers may disregard all internal remedies before going to court","Officers should exhaust internal remedies and obtain formal approval before proceeding to court","Officers must invite political leaders before going to court","Officers may proceed to court anonymously"]'::jsonb,1,'Correct. PSR Rule 110201 requires Officers to exhaust available redress avenues as much as possible and obtain formal approval from the Head of the Civil Service of the Federation before proceeding to court.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-10')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 110202 provides that appeals or petitions by Officers must be submitted how?','["Through social media only","In accordance with the rules set out in Chapter 11 Section 2","Directly to the press","Through private relatives only"]'::jsonb,1,'Correct. Under PSR Rule 110202, an appeal or petition by an Officer must be submitted in accordance with the rules set out in Chapter 11 Section 2.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-11')::uuid,'PSR','Chapter 1: Structure & Appointments','Can an ex-Officer submit an appeal or petition under Rule 110202?','["Yes, on matters relating to his conditions of employment as an Officer or his condition as a pensioner of Government","No, ex-Officers are never covered","Yes, but only for political appointments","Only if the ex-Officer is still on annual leave"]'::jsonb,0,'Correct. Under PSR Rule 110202, an ex-Officer may submit an appeal or petition on matters relating to his conditions of employment as an Officer or his condition as a pensioner of Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-12')::uuid,'PSR','Chapter 1: Structure & Appointments','Which matter may an ex-Officer petition on under Rule 110202?','["His condition as a pensioner of Government","His private business dispute only","A neighbour’s land case","A political party nomination"]'::jsonb,0,'Correct. PSR Rule 110202 covers petitions by an ex-Officer on matters relating to his condition as a pensioner of Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-13')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 110203, an Officer must not attempt to bring what kind of influence to support his individual claims?','["Political or other outside influence","Official records only","His staff number","Departmental comments"]'::jsonb,0,'Correct. Under PSR Rule 110203, an Officer must not attempt to bring political or other outside influence to support his individual claims.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-14')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 110203 refers to which earlier PSR rule on outside influence?','["Rule 100427","Rule 120101","Rule 130201","Rule 020101"]'::jsonb,0,'Correct. PSR Rule 110203 expressly states that, in line with Rule 100427, an Officer must not bring political or other outside influence to support individual claims.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-15')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer is dissatisfied, what is the proper first course under Rule 110203?','["Make representation to his immediate superior Officer or Permanent Secretary/Head of Extra-Ministerial Office","Write directly to a newspaper","Organise a public protest immediately","Seek traditional title intervention"]'::jsonb,0,'Correct. Under PSR Rule 110203, a dissatisfied Officer should first make representation to his immediate superior Officer or Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-16')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer’s representations are not successful, what may he do under Rule 110203?','["Submit a formal appeal or petition to the appropriate authority under Rule 110102","Refuse to report for duty","Alter official records secretly","Bring outside political pressure"]'::jsonb,0,'Correct. Under PSR Rule 110203, if representations are not successful, the Officer may submit a formal appeal or petition to the appropriate authority under Rule 110102.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-17')::uuid,'PSR','Chapter 1: Structure & Appointments','Which option is prohibited by Rule 110203?','["Submitting a formal appeal through proper authority","Bringing political or other outside influence to support an individual claim","Writing to an immediate superior Officer","Following Rule 110102"]'::jsonb,1,'Correct. PSR Rule 110203 prohibits an Officer from attempting to bring political or other outside influence to support individual claims.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-18')::uuid,'PSR','Chapter 1: Structure & Appointments','Through which channels must an appeal or petition be submitted under Rule 110204?','["Through the petitioner’s immediate superior Officer and the Permanent Secretary/Head of Extra-Ministerial Office","Directly to social media","Through a private consultant only","Through a political party secretariat"]'::jsonb,0,'Correct. Under PSR Rule 110204, an appeal or petition must be submitted through the proper departmental channels, namely the petitioner’s immediate superior Officer and the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-19')::uuid,'PSR','Chapter 1: Structure & Appointments','Who forwards the appeal or petition with comments and recommendations under Rule 110204?','["The Permanent Secretary/Head of Extra-Ministerial Office","The Officer’s neighbour","The press secretary of a political party","The Officer’s family member"]'::jsonb,0,'Correct. Under PSR Rule 110204, the Permanent Secretary/Head of Extra-Ministerial Office forwards the appeal or petition with comments and recommendations.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-20')::uuid,'PSR','Chapter 1: Structure & Appointments','The appeal or petition is forwarded to which authority under Rule 110204?','["The Chairman of the Federal Civil Service Commission or the Head of the Civil Service of the Federation","The Officer’s landlord","The Staff Union Treasurer","The local community leader"]'::jsonb,0,'Correct. Under PSR Rule 110204, the appeal or petition is forwarded to the Chairman of the Federal Civil Service Commission or the Head of the Civil Service of the Federation, in accordance with administrative instructions in force.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-21')::uuid,'PSR','Chapter 1: Structure & Appointments','Why is strict routing of an appeal or petition in the petitioner’s interest?','["So that the petition may be duly verified and reported on before it reaches its final destination","So that the petition can avoid official scrutiny","So that the petitioner can bypass the Ministry","So that the matter can be hidden from the proper authority"]'::jsonb,0,'Correct. Under PSR Rule 110204, strict observance of routing is in the petitioner’s interest because the petition will be duly verified and reported on before reaching its final destination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-22')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following best describes the proper departmental channel under Rule 110204?','["Immediate superior Officer, then Permanent Secretary/Head of Extra-Ministerial Office","Private lawyer, then newspaper editor","Family elder, then social media account","Political office holder, then campaign office"]'::jsonb,0,'Correct. PSR Rule 110204 states that an appeal or petition must pass through the petitioner’s immediate superior Officer and the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-23')::uuid,'PSR','Chapter 1: Structure & Appointments','How many copies of an appeal or petition must be submitted under Rule 110205?','["In duplicate","In six copies","In one verbal copy only","In ten copies"]'::jsonb,0,'Correct. Under PSR Rule 110205, an appeal or petition addressed to any of the proper channels must be submitted in duplicate.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-24')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 110205, may an advance copy be sent directly to the appropriate authority?','["Yes, with evidence that it has been submitted through the channel stated in Rule 110204","No, never under any circumstance","Yes, without using departmental channels","Only through a newspaper advertisement"]'::jsonb,0,'Correct. PSR Rule 110205 permits an advance copy to be sent directly to the appropriate authority, provided there is evidence that the petition has been submitted through the channel stated in Rule 110204.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-25')::uuid,'PSR','Chapter 1: Structure & Appointments','Where is one copy of the appeal or petition retained under Rule 110205?','["By the Permanent Secretary/Head of Extra-Ministerial Office","By the Officer’s neighbour","By a political party office","By the petitioner’s landlord"]'::jsonb,0,'Correct. Under PSR Rule 110205, one copy will be retained by the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-26')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement is correct under Rule 110205?','["The petition must be submitted in duplicate, and an advance copy may be sent direct with evidence of proper channel submission","The petition must be oral only","The petition must be submitted anonymously","The petition must be sent only to the media"]'::jsonb,0,'Correct. PSR Rule 110205 requires submission in duplicate and permits an advance copy to be sent directly only with evidence of submission through the proper Rule 110204 channel.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-27')::uuid,'PSR','Chapter 1: Structure & Appointments','What identity details must an appeal or petition bear under Rule 110206?','["Full name, staff number, signature and address of the petitioner","Only the petitioner’s nickname","Only the Ministry’s name","Only the petitioner’s grade level"]'::jsonb,0,'Correct. Under PSR Rule 110206, an appeal or petition must bear the full name, staff number, signature and address of the petitioner.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-28')::uuid,'PSR','Chapter 1: Structure & Appointments','If an appeal or petition is written by someone other than the Appellant or Petitioner, what must be included?','["The signature and address of the writer","The writer’s political party card","The writer’s family photograph","Only the writer’s phone brand"]'::jsonb,0,'Correct. Under PSR Rule 110206, when an appeal or petition is written by a person other than the Appellant/Petitioner, the signature and address of the writer must be included.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-29')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following would make a petition comply with Rule 110206?','["It bears the petitioner’s full name, staff number, signature and address","It bears only the Officer’s first name","It is anonymous","It contains no address or signature"]'::jsonb,0,'Correct. Under PSR Rule 110206, the identity of the petitioner must be clear through full name, staff number, signature and address.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-30')::uuid,'PSR','Chapter 1: Structure & Appointments','If a person signs and submits an appeal or petition on behalf of an illiterate person, what must the petition contain?','["A statement that he has been asked to write on behalf of the illiterate","A statement that the petition is anonymous","A newspaper publication notice","A promotion recommendation"]'::jsonb,0,'Correct. Under PSR Rule 110207, where a person submits an appeal or petition above his own signature on behalf of an illiterate person, the petition must state that he has been asked to write on behalf of the illiterate.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-31')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 110207 deals mainly with what situation?','["A petition submitted on behalf of an illiterate person","A petition sent by a foreign government","A petition submitted only by retired judges","A petition written by a contractor"]'::jsonb,0,'Correct. PSR Rule 110207 specifically governs a petition submitted above another person’s signature on behalf of an illiterate person.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-32')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best complies with Rule 110207?','["“I have been asked to write this petition on behalf of the illiterate petitioner.”","“This petition should remain unsigned.”","“This petition is submitted without the petitioner’s knowledge.”","“This petition has no author.”"]'::jsonb,0,'Correct. Under PSR Rule 110207, the petition must contain a statement that the writer has been asked to write on behalf of the illiterate person.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-33')::uuid,'PSR','Chapter 1: Structure & Appointments','Which appeal or petition will not be entertained under Rule 110208?','["One that does not comply with Rule 110102","One submitted through proper channel","One written legibly and respectfully","One introducing new relevant matter"]'::jsonb,0,'Correct. Under PSR Rule 110208, an appeal or petition will not be entertained if it does not comply with Rule 110102.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-34')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 110208, what happens to an appeal or petition dealing with a case in which legal action is pending in court?','["It will not be entertained","It will automatically be approved","It will be treated as promotion request","It will be forwarded to the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 110208, an appeal or petition will not be entertained if it deals with a case in which legal action is pending in a Court of Law.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-35')::uuid,'PSR','Chapter 1: Structure & Appointments','How does Rule 110208 treat an appeal or petition that is illegible or meaningless?','["It will not be entertained","It must be accepted automatically","It becomes a promotion document","It must be converted to annual leave"]'::jsonb,0,'Correct. Under PSR Rule 110208, an illegible or meaningless appeal or petition will not be entertained.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-36')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the effect of abusive, improper or foul language in an appeal or petition?','["The appeal or petition will not be entertained","The appeal will receive priority","The appeal will be treated as confidential success","The petition will be converted to a circular"]'::jsonb,0,'Correct. Under PSR Rule 110208, an appeal or petition worded in abusive, improper or foul language will not be entertained.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-37')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 110208, a repeated petition will not be entertained unless it does what?','["Introduces new relevant matter","Uses more abusive language","Avoids all signatures","Bypasses Rule 110102"]'::jsonb,0,'Correct. Under PSR Rule 110208, a petition that merely repeats the substance of a previous petition without introducing new relevant matter will not be entertained.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-38')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is NOT a valid reason for refusing to entertain an appeal or petition under Rule 110208?','["It is submitted through the proper channel and introduces new relevant matter","It is illegible or meaningless","It contains abusive, improper or foul language","It deals with a case pending in court"]'::jsonb,0,'Correct. PSR Rule 110208 lists grounds for not entertaining a petition, including non-compliance with Rule 110102, pending court action, illegibility, abusive language and repetition without new relevant matter. A properly routed petition introducing new relevant matter is not disqualified on that basis.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-39')::uuid,'PSR','Chapter 1: Structure & Appointments','An appeal or petition submitted more than six months after the decision complained of will not be entertained unless what happens?','["The delay is supported by valid reasons","The Officer sends it anonymously","The matter is posted on social media","The Officer refuses to work"]'::jsonb,0,'Correct. Under PSR Rule 110209, an appeal or petition submitted more than six months after the decision complained of was given will not be entertained unless the delay is supported by valid reasons.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-40')::uuid,'PSR','Chapter 1: Structure & Appointments','What time limit is relevant to delay under Rule 110209?','["More than six months after the decision complained of has been given","More than one day after employment","More than ten years before appointment","More than two hours after lunch"]'::jsonb,0,'Correct. Under PSR Rule 110209, delay becomes relevant where an appeal or petition is submitted more than six months after the decision complained of has been given.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-41')::uuid,'PSR','Chapter 1: Structure & Appointments','Which petition may still be entertained despite being submitted after six months?','["One with valid reasons supporting the delay","One with abusive language","One with no petitioner identity","One dealing with a case pending in court"]'::jsonb,0,'Correct. Under PSR Rule 110209, a petition submitted more than six months after the decision may still be considered if the delay is supported by valid reasons.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-42')::uuid,'PSR','Chapter 1: Structure & Appointments','How must an appeal or petition conclude under Rule 110210?','["By stating concisely the nature of the redress sought","By repeating insults against officials","By leaving the requested remedy unstated","By attaching unrelated personal stories"]'::jsonb,0,'Correct. Under PSR Rule 110210, an appeal or petition shall conclude by stating concisely the nature of the redress sought.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-43')::uuid,'PSR','Chapter 1: Structure & Appointments','If a petition exceeds two pages of foolscap, what must it include?','["A summary of the reasons adduced in support of the redress sought","A political recommendation letter","A list of unrelated complaints","A newspaper advert"]'::jsonb,0,'Correct. Under PSR Rule 110210, a petition exceeding two pages of foolscap must include a summary of the reasons adduced in support of the redress sought.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-44')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 110210 requires the redress sought to be stated in what manner?','["Concisely","Secretly","Verbally only","Through a third-party rumour"]'::jsonb,0,'Correct. Under PSR Rule 110210, an appeal or petition must conclude by stating concisely the nature of the redress sought.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-45')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 11, Section 2 of the PSR?','["It sets the rules for timing, application, court action, outside influence, routing, copies, identity, petitions for illiterate persons, disqualification, delay and conclusion of appeals/petitions","It deals only with annual leave","It deals only with burial expenses","It deals only with procurement thresholds"]'::jsonb,0,'Correct. PSR Chapter 11, Section 2, Rules 110201 to 110210 cover appeal/petition rules, including timing, application, court action, prohibition of outside influence, routing, number of copies, identity of petitioner, petitions written for illiterate persons, disqualifications, delay and conclusion of petitions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-46')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120101, what is leave?','["Unauthorized absence from office","Authorized absence of an Officer from duty for a specific period as provided in Chapter 12","A disciplinary punishment for absence","A period of suspension without pay"]'::jsonb,1,'Correct. Under PSR Chapter 12, Section 1, Rule 120101, “Leave” is the authorized absence of an Officer from duty for a specific period as provided for in Chapter 12.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-47')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best describes leave under the PSR?','["It must be authorized and must be for a specific period","It is always taken without approval","It applies only to dismissed Officers","It is the same as absence without leave"]'::jsonb,0,'Correct. Under PSR Rule 120101, leave is an authorized absence from duty for a specific period as provided in Chapter 12.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-48')::uuid,'PSR','Chapter 1: Structure & Appointments','What makes absence from duty qualify as leave under Rule 120101?','["It must be authorized under the leave provisions of Chapter 12","It must be longer than one year","It must be taken without informing the Ministry","It must be connected only to retirement"]'::jsonb,0,'Correct. PSR Rule 120101 defines leave as authorized absence of an Officer from duty for a specific period as provided in Chapter 12.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-49')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120102, what is a leave address?','["A place where an Officer could be reached during his leave period","The Officer’s former school address","The address of the Staff Union office","The address of the Officer’s bank"]'::jsonb,0,'Correct. Under PSR Chapter 12, Section 1, Rule 120102, “Leave Address” is a place where an Officer could be reached during his leave period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-50')::uuid,'PSR','Chapter 1: Structure & Appointments','Why is a leave address important under Rule 120102?','["It shows where the Officer may be reached during leave","It replaces the Officer’s duty post permanently","It automatically extends leave entitlement","It serves as a promotion document"]'::jsonb,0,'Correct. Under PSR Rule 120102, a leave address is the place where an Officer could be reached during his leave period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-51')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is the correct meaning of leave address?','["An address used only after retirement","A place where an Officer could be reached during leave","A secret address not disclosed to the Ministry","An address used only for salary payment"]'::jsonb,1,'Correct. PSR Rule 120102 defines “Leave Address” as a place where an Officer could be reached during his leave period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-52')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120103, what is earned leave?','["Leave due to an Officer in a year for service rendered to Government","Leave granted only to Officers under suspension","Leave taken without approval","Leave meant only for political appointees"]'::jsonb,0,'Correct. Under PSR Chapter 12, Section 1, Rule 120103, “Earned Leave” is the leave due to an Officer in a year for the service rendered to Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-53')::uuid,'PSR','Chapter 1: Structure & Appointments','Earned leave is linked to what under Rule 120103?','["Service rendered to Government","Private business activities","Disciplinary proceedings only","Length of residence abroad"]'::jsonb,0,'Correct. PSR Rule 120103 provides that earned leave is the leave due to an Officer in a year for service rendered to Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-54')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement is correct about earned leave?','["It is leave due to an Officer in a year for service rendered to Government","It is always granted before appointment","It is the same as dismissal","It applies only to Officers on interdiction"]'::jsonb,0,'Correct. Under PSR Rule 120103, earned leave means the leave due to an Officer in a year for service rendered to Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-55')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120104, what is leave earning service?','["A qualifying period of duty before Officers could be granted leave","A period of absence without approval","A punishment imposed for lateness","A period after dismissal from Service"]'::jsonb,0,'Correct. Under PSR Chapter 12, Section 1, Rule 120104, “Leave Earning Service” is a qualifying period of duty before Officers could be granted leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-56')::uuid,'PSR','Chapter 1: Structure & Appointments','Leave earning service refers to what kind of period?','["A qualifying period of duty","A period of retirement only","A disciplinary suspension period","A private vacation abroad"]'::jsonb,0,'Correct. PSR Rule 120104 defines “Leave Earning Service” as the qualifying period of duty before Officers could be granted leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-57')::uuid,'PSR','Chapter 1: Structure & Appointments','Before Officers could be granted leave, Rule 120104 refers to what requirement?','["Completion of a qualifying period of duty","Payment of a private fee","Approval by a Staff Union only","Completion of disciplinary punishment"]'::jsonb,0,'Correct. Under PSR Rule 120104, leave earning service is the qualifying period of duty before Officers could be granted leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-58')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120105, what is the date of resumption of duty?','["The date following the expiration of the leave","The date the Officer applied for leave","The date the Officer received salary","The first day of the leave period"]'::jsonb,0,'Correct. Under PSR Chapter 12, Section 1, Rule 120105, “The Date of Resumption of Duty” is the date following the expiration of the leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-59')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer’s leave expires today, what is his date of resumption under Rule 120105?','["The date following the expiration of the leave","The first day of the leave","The date leave was approved","The date salary is paid"]'::jsonb,0,'Correct. PSR Rule 120105 provides that the date of resumption of duty is the date following the expiration of the leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-60')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement correctly explains date of resumption of duty?','["It is the date immediately following the expiration of leave","It is the first day of the leave period","It is any date chosen by the Officer without approval","It is always 31st December"]'::jsonb,0,'Correct. Under PSR Rule 120105, the date of resumption of duty is the date following the expiration of the leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-61')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120106, what is a leave year?','["The period between 1st January and 31st December","The period between 1st July and 30th June","The period between appointment and confirmation","The period between retirement and pension payment"]'::jsonb,0,'Correct. Under PSR Chapter 12, Section 1, Rule 120106, “Leave Year” is the period between 1st January and 31st December.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-62')::uuid,'PSR','Chapter 1: Structure & Appointments','When does the leave year begin under Rule 120106?','["1st January","1st April","1st July","31st December"]'::jsonb,0,'Correct. Under PSR Rule 120106, the leave year is the period between 1st January and 31st December; therefore, it begins on 1st January.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-63')::uuid,'PSR','Chapter 1: Structure & Appointments','When does the leave year end under Rule 120106?','["31st December","30th June","1st January","31st March"]'::jsonb,0,'Correct. Under PSR Rule 120106, the leave year is the period between 1st January and 31st December; therefore, it ends on 31st December.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-64')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 12, Section 1 of the PSR?','["It gives general definitions for leave, leave address, earned leave, leave earning service, date of resumption of duty and leave year","It lists all disciplinary offences","It explains procurement thresholds only","It deals only with medical treatment abroad"]'::jsonb,0,'Correct. PSR Chapter 12, Section 1, Rules 120101 to 120106 provide the general definitions for leave administration, including leave, leave address, earned leave, leave earning service, date of resumption of duty and leave year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-65')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is listed as a type of leave in the Federal Public Service under Rule 120201?','["Acting Leave","Promotion Leave","Annual Leave","Disciplinary Leave"]'::jsonb,2,'Correct. Under PSR Chapter 12, Section 2, Rule 120201, Annual Leave is one of the types of leave recognized in the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-66')::uuid,'PSR','Chapter 1: Structure & Appointments','Which type of leave is expressly stated as abolished under Rule 120201?','["Deferred Leave","Sick Leave","Maternity Leave","Casual Leave"]'::jsonb,0,'Correct. Under PSR Rule 120201, Deferred Leave is listed as “Deferred Leave (Abolished).”') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-67')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is included among the types of leave listed in Rule 120201?','["Leave to take part in Trade Union Activities","Leave for private business expansion","Leave for political campaign management","Leave for unofficial travel"]'::jsonb,0,'Correct. Under PSR Rule 120201, Leave to take part in Trade Union Activities is listed as a type of leave in the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-68')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Annual Leave under Rule 120202?','["Absence from duty without approval","Absence from duty after dismissal","Absence from duty only for medical reasons","Absence of an Officer from duty for a specified period as authorized by a superior Officer"]'::jsonb,3,'Correct. Under PSR Rule 120202, Annual Leave is the absence of an Officer from duty for a period specified in Rule 120203 as may be authorized by a superior Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-69')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the annual leave entitlement for Officers on GL 07 and above?','["14 working days","30 working days","21 working days","7 working days"]'::jsonb,1,'Correct. Under PSR Rule 120203(a), Officers on GL 07 and above are entitled to 30 working days annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-70')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the annual leave entitlement for Officers on GL 04–06?','["30 working days","14 working days","21 working days","7 working days"]'::jsonb,2,'Correct. Under PSR Rule 120203(b), Officers on GL 04–06 are entitled to 21 working days annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-71')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the annual leave entitlement for Officers on GL 03 and below?','["14 working days","30 working days","21 working days","28 working days"]'::jsonb,0,'Correct. Under PSR Rule 120203(c), Officers on GL 03 and below are entitled to 14 working days annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-72')::uuid,'PSR','Chapter 1: Structure & Appointments','When does an Officer qualify for annual leave after the previous leave?','["After one month","After two years","Immediately after resumption","Not less than six months after the previous leave within a leave earning service year"]'::jsonb,3,'Correct. Under PSR Rule 120204, an Officer qualifies for annual leave not less than six months after the previous leave within a leave earning service year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-73')::uuid,'PSR','Chapter 1: Structure & Appointments','Who is responsible for drawing up the Annual Leave Roster?','["The Accountant-General","The Head of Department of Human Resource/Administration","The Staff Union Chairman","The Officer applying for leave"]'::jsonb,1,'Correct. Under PSR Rule 120205(a), the Head of Department of Human Resource/Administration is responsible for drawing up the Annual Leave Roster for all Officers in the Ministry or Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-74')::uuid,'PSR','Chapter 1: Structure & Appointments','Who approves the Leave Roster for the coming year and by what deadline?','["The Staff Union Chairman by 1st January","The Accountant-General by 30th June","The Permanent Secretary/Head of Extra-Ministerial Office not later than 31st December","The Officer’s immediate colleague by 31st March"]'::jsonb,2,'Correct. Under PSR Rule 120205(b), every Permanent Secretary/Head of Extra-Ministerial Office approves the Leave Roster for the coming year not later than 31st December.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-75')::uuid,'PSR','Chapter 1: Structure & Appointments','Normally, how may full annual leave be taken under Rule 120206?','["At one time or in not more than two installments","In unlimited installments","Only after retirement","Only during public holidays"]'::jsonb,0,'Correct. Under PSR Rule 120206, full leave will normally be taken at one time, but it may be taken in not more than two installments.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-76')::uuid,'PSR','Chapter 1: Structure & Appointments','What happens to annual leave not taken within the calendar year concerned?','["It is automatically converted to cash","It is accumulated indefinitely","It is transferred to the Officer’s spouse","It is forfeited"]'::jsonb,3,'Correct. Under PSR Rule 120206, any leave not taken within the calendar year concerned is forfeited, and no Officer is allowed to accumulate leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-77')::uuid,'PSR','Chapter 1: Structure & Appointments','What must an Officer do if he desires to spend annual leave abroad?','["Get approval from the Staff Union only","Proceed without informing anyone","Inform the Permanent Secretary/Head of Extra-Ministerial Office and provide address details","Report only after returning from leave"]'::jsonb,2,'Correct. Under PSR Rule 120207(a), an Officer who desires to spend annual leave abroad must inform the Permanent Secretary/Head of Extra-Ministerial Office before proceeding and provide details of his address.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-78')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer is required to undertake duty during vacation leave, how is that period treated?','["It is treated as unauthorized absence","It is leave-earning and not leave-consuming","It is treated as dismissal period","It is treated as casual leave"]'::jsonb,1,'Correct. Under PSR Rule 120207(b), where an Officer is required during vacation leave to undertake duty, the period of duty is leave-earning and not leave-consuming.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-79')::uuid,'PSR','Chapter 1: Structure & Appointments','What must an Officer furnish before proceeding on leave within or outside Nigeria?','["Intended destination or leave address","Promotion examination result","Pension clearance certificate","Letter from a private business partner"]'::jsonb,0,'Correct. Under PSR Rule 120208, an Officer spending leave within or outside Nigeria must furnish the Permanent Secretary/Head of Extra-Ministerial Office with his or her intended destination or leave address before proceeding on leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-80')::uuid,'PSR','Chapter 1: Structure & Appointments','When is an Officer required to resume duty after vacation leave?','["Two weeks after the leave expires","At any convenient time","Only after receiving another leave approval","On the date following the expiration of the authorized leave"]'::jsonb,3,'Correct. Under PSR Rule 120209, an Officer is required to resume duty after vacation leave on the date following the expiration of his authorized leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-81')::uuid,'PSR','Chapter 1: Structure & Appointments','Who may require an Officer to return to duty before the expiration of authorized leave?','["The Staff Union Chairman","The Permanent Secretary/Head of Extra-Ministerial Office","The Officer’s colleague","The Officer’s family member"]'::jsonb,1,'Correct. Under PSR Rule 120210, an Officer may be required to return to duty before the expiration of authorized leave by the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-82')::uuid,'PSR','Chapter 1: Structure & Appointments','When must the curtailed portion of leave be taken?','["Only after retirement","At any time within five years","Immediately and not later than 90 days after completion of the assignment","Never, because it is forfeited"]'::jsonb,2,'Correct. Under PSR Rule 120210, any portion of leave curtailed must be taken immediately and not later than ninety days after completion of the assignment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-83')::uuid,'PSR','Chapter 1: Structure & Appointments','What form must an Officer complete and submit on return from annual leave?','["Resumption of Duty Certificate Form L.10","Promotion Form Gen. 35","Disciplinary Query Form","Procurement Requisition Form"]'::jsonb,0,'Correct. Under PSR Rule 120211, every Officer must complete and submit a Resumption of Duty Certificate, Form L.10, on return from annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-84')::uuid,'PSR','Chapter 1: Structure & Appointments','Who endorses the Resumption of Duty Certificate before forwarding it?','["The Officer’s neighbour","The Staff Union Chairman","The Officer’s bank manager","The Permanent Secretary/Head of Extra-Ministerial Office"]'::jsonb,3,'Correct. Under PSR Rule 120211, the Permanent Secretary/Head of Extra-Ministerial Office endorses the Resumption of Duty Certificate and forwards it to OHCSF or the relevant pool office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-85')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Proportionate Leave or Pro-rata Leave?','["Leave taken without approval","Leave given only for disciplinary proceedings","Leave granted to a new or retiring Officer in proportion to the number of days put into Service","Leave granted only to political appointees"]'::jsonb,2,'Correct. Under PSR Rule 120212, Proportionate Leave or Pro-rata Leave is vacation granted to a new or retiring Officer in proportion to the number of days he has put into Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-86')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 120212, what happens to a period of service under 30 days for pro-rata leave calculation?','["It is not reckonable","It counts as a full year","It gives automatic 30 days leave","It is converted to salary"]'::jsonb,0,'Correct. Under PSR Rule 120212, any period of service under 30 days is not reckonable for calculation of proportionate leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-87')::uuid,'PSR','Chapter 1: Structure & Appointments','The computation of proportionate leave is based on what?','["Calendar months only","Saturdays and Sundays only","Working days","Public holidays only"]'::jsonb,2,'Correct. Under PSR Rule 120212, the computation of proportionate leave is based on working days.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-88')::uuid,'PSR','Chapter 1: Structure & Appointments','What type of leave will an Officer who joins the Federal Public Service during the course of the leave year normally receive?','["Proportionate Leave","Sabbatical Leave","Pre-retirement Leave","Leave of Absence"]'::jsonb,0,'Correct. Under PSR Rule 120213(a), an Officer who joins the Federal Public Service during the course of the leave year will not normally be granted annual leave but proportionate leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-89')::uuid,'PSR','Chapter 1: Structure & Appointments','Officers who attend courses of instruction or training over what period are entitled to proportionate leave for the period put in Service?','["Over one week","Over one month","Over two years","Over six months"]'::jsonb,3,'Correct. Under PSR Rule 120213(b), Officers who attend courses of instruction or training over a period of six months are entitled to proportionate leave for the period they put in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-90')::uuid,'PSR','Chapter 1: Structure & Appointments','Which retiring Officer is entitled to proportionate leave under Rule 120213?','["An Officer retiring within the period of Leave-Earning Service","An Officer dismissed for misconduct","An Officer absent without leave","An Officer who has abandoned duty"]'::jsonb,0,'Correct. Under PSR Rule 120213(c), an Officer who is retiring within the period of Leave-Earning Service is entitled to proportionate leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-91')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Casual Leave under Rule 120214?','["Absence for a short period not exceeding an aggregate of 7 working days within a leave year","Absence for five years without pay","Leave granted only after dismissal","Leave granted only for foreign study"]'::jsonb,0,'Correct. Under PSR Rule 120214, Casual Leave is absence from duty for a short period not exceeding an aggregate of 7 working days within a leave year as authorized by a superior Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-92')::uuid,'PSR','Chapter 1: Structure & Appointments','When shall Casual Leave only be granted?','["Before an Officer joins the Service","After an Officer has exhausted his annual leave","Only after retirement","Only during suspension"]'::jsonb,1,'Correct. Under PSR Rule 120214, Casual Leave shall only be granted after an Officer has exhausted his annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-93')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the maximum Casual Leave normally granted in any leave year?','["30 working days","21 working days","7 working days","14 working days"]'::jsonb,2,'Correct. Under PSR Rule 120215, a maximum of seven days Casual Leave shall be granted in any leave year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-94')::uuid,'PSR','Chapter 1: Structure & Appointments','Casual Leave in excess of seven days may be granted only by whom?','["The Officer’s colleague","The Staff Union Chairman","The Officer’s family","The Permanent Secretary/Head of Extra-Ministerial Office"]'::jsonb,3,'Correct. Under PSR Rule 120215, Casual Leave in excess of seven days in any leave year may be granted only by the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-95')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Sick Leave?','["Absence from duty on account of ill-health as authorized by a Healthcare Provider","Absence for political campaign","Absence for trade union election only","Absence for personal business"]'::jsonb,0,'Correct. Under PSR Rule 120216, Sick Leave is absence of an Officer from duty on account of ill-health as authorized by a Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-96')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Maternity Leave?','["Leave granted only to male Officers","Unauthorized absence due to family reasons","Authorized absence of a serving female Officer on account of pregnancy covering prenatal and postnatal periods","Leave granted only after retirement"]'::jsonb,2,'Correct. Under PSR Rule 120217, Maternity Leave is the authorized absence from duty of a serving female Officer granted by a superior Officer on account of pregnancy, covering prenatal and postnatal periods.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-97')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the maternity leave entitlement of a pregnant female staff under Rule 120218?','["30 working days","84 working days","112 working days","14 working days"]'::jsonb,2,'Correct. Under PSR Rule 120218(i), a pregnant female staff is entitled to 112 working days maternity leave at a stretch.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-98')::uuid,'PSR','Chapter 1: Structure & Appointments','When should maternity leave begin in relation to the Expected Date of Delivery?','["Not less than 28 working days from the Expected Date of Delivery","Only after delivery","One year before delivery","Only after annual leave is exhausted"]'::jsonb,0,'Correct. Under PSR Rule 120218(i), maternity leave begins not less than 28 working days from the Expected Date of Delivery.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-99')::uuid,'PSR','Chapter 1: Structure & Appointments','When must the medical certificate showing expected date of confinement be presented?','["After the child is one year old","Not less than two months before the expected date of confinement","Only after resumption from maternity leave","At retirement"]'::jsonb,1,'Correct. Under PSR Rule 120218(i), a medical certificate showing the expected date of confinement must be presented not less than two months before that date.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-100')::uuid,'PSR','Chapter 1: Structure & Appointments','How is annual leave treated in the year maternity leave is granted?','["It is paid separately in cash","It is not connected to maternity leave","It is transferred to the next year","It is regarded as part of the maternity leave"]'::jsonb,3,'Correct. Under PSR Rule 120218(i), the annual leave for that year is regarded as part of the maternity leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-101')::uuid,'PSR','Chapter 1: Structure & Appointments','Where a female Officer adopts a child under four months old, what maternity leave does she enjoy?','["14 working days","84 working days","112 working days","7 working days"]'::jsonb,1,'Correct. Under PSR Rule 120218(ii), where a female Officer adopts a child under four months old, she enjoys 84 working days maternity leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-102')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the duration of Paternity Leave under Rule 120219?','["112 working days","84 working days","14 working days","30 working days"]'::jsonb,2,'Correct. Under PSR Rule 120219, Paternity Leave is granted to a serving male Officer for a period of 14 working days shortly before or after delivery by his spouse.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-103')::uuid,'PSR','Chapter 1: Structure & Appointments','How often may Paternity Leave be granted and for how many children?','["Not more than once in two years for a maximum of four children","Every month for unlimited children","Once every year for ten children","Only once in a career for one child"]'::jsonb,0,'Correct. Under PSR Rule 120219, Paternity Leave shall not be more than once in two years and is limited to a maximum of four children.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-104')::uuid,'PSR','Chapter 1: Structure & Appointments','Where a male Officer’s family adopts a child under four months old, what leave may he enjoy?','["84 working days","30 working days","7 working days","14 working days"]'::jsonb,3,'Correct. Under PSR Rule 120219(i), where the family of a male Officer adopts a child under four months old, the male Officer enjoys 14 working days leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-105')::uuid,'PSR','Chapter 1: Structure & Appointments','What should accompany a request for Paternity Leave?','["A promotion letter only","Expected Date of Delivery report of the wife or evidence of approval of adoption","An annual leave roster only","A staff union recommendation only"]'::jsonb,1,'Correct. Under PSR Rule 120219(ii), a request for Paternity Leave must be accompanied by the Expected Date of Delivery report of the wife or evidence of approval of the adoption.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-106')::uuid,'PSR','Chapter 1: Structure & Appointments','What time-off is granted daily to a female Officer nursing a child?','["Thirty minutes","One hour","Two hours","Four hours"]'::jsonb,2,'Correct. Under PSR Rule 120220, any female Officer nursing a child shall be granted two hours off-duty every day.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-107')::uuid,'PSR','Chapter 1: Structure & Appointments','For how long may the two-hour nursing mother facility be granted?','["For three years","For one month only","For the whole career","Up to a maximum of six months from the date she resumes duty from maternity leave"]'::jsonb,3,'Correct. Under PSR Rule 120220, the two-hour daily off-duty facility is granted up to a maximum period of six months from the date the Officer resumes duty from maternity leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-108')::uuid,'PSR','Chapter 1: Structure & Appointments','When may an Officer be granted special leave for compulsory examination?','["For an examination required by the conditions of service of his appointment","For any private hobby examination","Only after dismissal","Only after retirement"]'::jsonb,0,'Correct. Under PSR Rule 120221, an Officer may be granted special leave to take an examination which he is required to pass by the conditions of service of his appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-109')::uuid,'PSR','Chapter 1: Structure & Appointments','Which condition applies to special leave with full pay for a non-compulsory examination?','["The Permanent Secretary/Head of Extra-Ministerial Office must certify that passing the examination is likely to enhance the Officer’s value to the Service","The Officer must be under suspension","The Officer must refuse to provide an examination timetable","The Officer must be on dismissal list"]'::jsonb,0,'Correct. Under PSR Rule 120222(a), special leave with full pay for a non-compulsory examination may be allowed where the Permanent Secretary/Head of Extra-Ministerial Office certifies that passing the examination is likely to enhance the Officer’s value to the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-110')::uuid,'PSR','Chapter 1: Structure & Appointments','Which evidence is required for non-compulsory examination leave under Rule 120222?','["Evidence of admission for the course and examination timetable","Evidence of political appointment","Evidence of retirement only","Evidence of dismissal"]'::jsonb,0,'Correct. Under PSR Rule 120222, evidence of admission for the course and evidence of a timetable for the examination are required for non-compulsory examination leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-111')::uuid,'PSR','Chapter 1: Structure & Appointments','Which Officers may proceed on Sabbatical Leave under Rule 120223?','["Officers on GL 15 or equivalent and above","All newly recruited Officers only","Only Officers on GL 03 and below","Only dismissed Officers"]'::jsonb,0,'Correct. Under PSR Rule 120223, Sabbatical Leave applies to an Officer on GL 15 or equivalent and above.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-112')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the purpose of Sabbatical Leave under Rule 120223?','["To punish Officers for misconduct","For research or established professional development linked to career progression","To avoid official duty permanently","For political campaign activities"]'::jsonb,1,'Correct. Under PSR Rule 120223, Sabbatical Leave is for research relevant to duties or an established professional development programme linked to career progression for improved service delivery.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-113')::uuid,'PSR','Chapter 1: Structure & Appointments','How long is Sabbatical Leave and how often may it be taken?','["Two weeks once every year","Six months once every two years","Twelve calendar months once in five years","Four years every time"]'::jsonb,2,'Correct. Under PSR Rule 120223, Sabbatical Leave is for twelve calendar months once in five years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-114')::uuid,'PSR','Chapter 1: Structure & Appointments','What evidence must an applicant for Sabbatical Leave tender?','["An annual leave roster only","A dismissal clearance","A promotion examination score","Evidence of acceptance from the receiving organization"]'::jsonb,3,'Correct. Under PSR Rule 120223, applicants for Sabbatical Leave must tender evidence of acceptance from the receiving organization.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-115')::uuid,'PSR','Chapter 1: Structure & Appointments','Which Officers are allowed to proceed on Sabbatical Leave?','["Officers on disciplinary action only","Unconfirmed Officers only","Confirmed Officers not under performance improvement plan or disciplinary action","Officers who have abandoned duty"]'::jsonb,2,'Correct. Under PSR Rule 120224(a), only confirmed Officers not under a performance improvement plan or disciplinary action are allowed to proceed on Sabbatical Leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-116')::uuid,'PSR','Chapter 1: Structure & Appointments','How far in advance should an Officer apply for Sabbatical Leave?','["Six months in advance","One day in advance","After returning from leave","At retirement"]'::jsonb,0,'Correct. Under PSR Rule 120224(a), the request for Sabbatical Leave must be made through written application to the Officer’s superior six months in advance.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-117')::uuid,'PSR','Chapter 1: Structure & Appointments','The Officer’s MDA must certify what before Sabbatical Leave is granted?','["That the Officer can be released without replacement or impairing the smooth flow of work","That the Officer must be dismissed first","That the Officer is no longer needed in Service","That the Officer will not return"]'::jsonb,1,'Correct. Under PSR Rule 120224(b), the MDA must certify that the staff member can be released to undertake Sabbatical Leave without replacement or impairing the smooth flow of work.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-118')::uuid,'PSR','Chapter 1: Structure & Appointments','To whom is a request for Sabbatical Leave forwarded for approval?','["The Staff Union","The Accountant-General","The Officer’s colleague","The Office of the Head of the Civil Service of the Federation"]'::jsonb,3,'Correct. Under PSR Rule 120224(c), the request for Sabbatical Leave, on the recommendation of the Permanent Secretary, is forwarded to OHCSF for approval.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-119')::uuid,'PSR','Chapter 1: Structure & Appointments','Is the period of Sabbatical Leave regarded as a break in Service?','["No, it is not regarded as a break in Service","Yes, it always breaks Service","Only if taken in Nigeria","Only if taken outside Nigeria"]'::jsonb,0,'Correct. Under PSR Rule 120224(c), the period of Sabbatical Leave is not regarded as a break in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-120')::uuid,'PSR','Chapter 1: Structure & Appointments','What must Officers on Sabbatical Leave do immediately after completion of the leave?','["Return to work and submit notification of return to duty","Proceed on indefinite absence","Accept political appointment without approval","Remain away from duty without explanation"]'::jsonb,0,'Correct. Under PSR Rule 120224(d), Officers on Sabbatical Leave must return to work immediately after completion and submit a notification of return to duty, except where an extension is granted.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-121')::uuid,'PSR','Chapter 1: Structure & Appointments','Failure to return immediately after Sabbatical Leave without extension is treated as what?','["Minor lateness","Serious misconduct","Casual leave","Annual leave"]'::jsonb,1,'Correct. Under PSR Rule 120224(d), failure to return immediately after Sabbatical Leave, except where an extension is granted, is construed as serious misconduct and attracts appropriate penalty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-122')::uuid,'PSR','Chapter 1: Structure & Appointments','What must Officers returning from Sabbatical Leave submit?','["A formal report on academic or administrative work accomplished","A private business plan only","A resignation letter only","A leave roster only"]'::jsonb,0,'Correct. Under PSR Rule 120224(e), all Officers returning from Sabbatical Leave must submit a formal report on academic or administrative work accomplished during the leave period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-123')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement is correct about promotion during Sabbatical Leave?','["The Officer is granted automatic notional promotion","The Officer cannot sit for any promotion interview","The Officer is dismissed from promotion exercises","The Officer is not granted notional promotion but may sit for promotion interviews or examinations at the nearest designated centre"]'::jsonb,3,'Correct. Under PSR Rule 120224(f), an Officer on Sabbatical Leave is not granted notional promotion but is eligible to sit for promotion interviews or examinations at the nearest designated centre.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-124')::uuid,'PSR','Chapter 1: Structure & Appointments','How long must an Officer work for Government after returning from Sabbatical Leave before exiting from Service?','["One year","One month","Two weeks","Five years"]'::jsonb,0,'Correct. Under PSR Rule 120224(g), upon return from Sabbatical Leave, the Officer must work for Government for one year before exiting from Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-125')::uuid,'PSR','Chapter 1: Structure & Appointments','Who handles approvals and questions of interpretation on Sabbatical Leave?','["The Officer’s family","The OHCSF","The Staff Union Treasurer","A private consultant"]'::jsonb,1,'Correct. Under PSR Rule 120224(h), all approvals and questions of interpretation on Sabbatical Leave are referred to the OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-126')::uuid,'PSR','Chapter 1: Structure & Appointments','What happens to an Officer’s emolument while on Sabbatical Leave?','["It is paid by the parent MDA within the period","It is permanently stopped","It is paid by a private host organization only","It is converted to pension"]'::jsonb,0,'Correct. Under PSR Rule 120224(i), an Officer on Sabbatical Leave continues to enjoy his emolument from the parent MDA within the period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-127')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Study Leave?','["Leave granted to a confirmed serving Officer to undertake an approved course of study within or outside the country","Leave granted only for burial ceremonies","Leave taken without approval","Leave granted only to dismissed Officers"]'::jsonb,0,'Correct. Under PSR Rule 120225, Study Leave is leave granted to a confirmed serving Officer to undertake an approved course of study within or outside the country.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-128')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is one of the three types of Study Leave?','["Leave for In-Service Training","Leave for personal shopping","Leave for political rallies","Leave for dismissal"]'::jsonb,0,'Correct. Under PSR Rule 120226, the three types of Study Leave are Leave for In-Service Training, Study Leave with Pay and Study Leave without Pay.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-129')::uuid,'PSR','Chapter 1: Structure & Appointments','What must the Permanent Secretary/Head of Extra-Ministerial Office certify before study leave is granted?','["Evidence of admission, duration of course, usefulness to the Service and relevance to the Officer’s profession","Evidence of dismissal only","Evidence of political appointment only","Evidence of pension payment only"]'::jsonb,0,'Correct. Under PSR Rule 120226, study leave requires certification of evidence of admission, course duration, that the course enhances performance and adds value to the Service, and that the course is relevant to the Officer’s profession.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-130')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the maximum duration of In-Service Training under Rule 120227?','["One month","Two years","Five years","Seven days"]'::jsonb,1,'Correct. Under PSR Rule 120227, Officers may be granted In-Service Training for a period not exceeding two years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-131')::uuid,'PSR','Chapter 1: Structure & Appointments','What benefits apply during In-Service Training under Rule 120227?','["No emoluments or allowances","Only transport fare","Normal emoluments, allowances and course fees","Only half salary"]'::jsonb,2,'Correct. Under PSR Rule 120227, Officers granted In-Service Training are entitled to normal emoluments, allowances and course fees.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-132')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the maximum normal duration of Study Leave with Pay?','["One month","Five years","Two years","Ten years"]'::jsonb,2,'Correct. Under PSR Rule 120228(a), Study Leave with Pay shall not exceed two years, although a one-year extension may be granted where there is acceptable justification.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-133')::uuid,'PSR','Chapter 1: Structure & Appointments','When may a one-year extension be granted for Study Leave with Pay?','["Whenever the Officer refuses to resume","Where there is acceptable justification","Only after dismissal","Only for casual leave"]'::jsonb,1,'Correct. Under PSR Rule 120228(a), a one-year extension may be granted for Study Leave with Pay where there is acceptable justification.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-134')::uuid,'PSR','Chapter 1: Structure & Appointments','What should happen where a course cannot be accommodated within three years including extension?','["It should be treated as casual leave","It should be converted to maternity leave","It should be ignored completely","It should be considered for Study Leave without Pay or part-time"]'::jsonb,3,'Correct. Under PSR Rule 120228(b), any course of study that cannot be accommodated within three years, inclusive of one-year extension, should be considered for Study Leave without Pay or part-time.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-135')::uuid,'PSR','Chapter 1: Structure & Appointments','When may Study Leave without Pay be granted?','["Where the proposed course is not contained in the MDA’s approved training proposals but is relevant to the Officer’s career prospects or self-development","Only where the Officer is dismissed","Only for annual leave abroad","Only for political office"]'::jsonb,0,'Correct. Under PSR Rule 120229, Study Leave without Pay may be granted where the course is not in the approved training proposals for the MDA but is relevant to the Officer’s career prospects or self-development.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-136')::uuid,'PSR','Chapter 1: Structure & Appointments','Are Officers on Study Leave without Pay entitled to normal emoluments and allowances?','["Yes, always","No, they are not entitled to normal emoluments and allowances","Only if they are on GL 03","Only during public holidays"]'::jsonb,1,'Correct. Under PSR Rule 120230(a), Officers on Study Leave without Pay are not entitled to normal emoluments and allowances.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-137')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the maximum duration of Study Leave without Pay in the first instance?','["One month","Two weeks","Four years","Ten years"]'::jsonb,2,'Correct. Under PSR Rule 120230(b), Study Leave without Pay shall not be more than four years in the first instance, after which the Officer may apply for a one-year extension if needed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-138')::uuid,'PSR','Chapter 1: Structure & Appointments','How is the period of Study Leave without Pay treated for Service continuity?','["It is treated as dismissal","It is treated as a break in Service","It is not regarded as a break in Service","It is treated as retirement"]'::jsonb,2,'Correct. Under PSR Rule 120230(c), the period of study shall not be regarded as a break in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-139')::uuid,'PSR','Chapter 1: Structure & Appointments','Who approves the release of an Officer on Study Leave?','["The Officer’s colleague","The Staff Union Chairman","The Officer’s private school","The Head of the Civil Service of the Federation on recommendation of the Permanent Secretary/Head of Extra-Ministerial Office"]'::jsonb,3,'Correct. Under PSR Rule 120231, release of any Officer on Study Leave is subject to approval of the Head of the Civil Service of the Federation on the recommendation of the Officer’s Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-140')::uuid,'PSR','Chapter 1: Structure & Appointments','What leave should Officers going on religious pilgrimages use?','["Part of their annual leave","Study leave without pay","Sabbatical leave","Pre-retirement leave"]'::jsonb,0,'Correct. Under PSR Rule 120232, Officers going on religious pilgrimages, other than officials assigned to cover such activities, should use part of their annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-141')::uuid,'PSR','Chapter 1: Structure & Appointments','For how long may special leave on compassionate ground be allowed?','["Up to two weeks","Up to two years","Up to six months","Up to five years"]'::jsonb,0,'Correct. Under PSR Rule 120233, an Officer may be allowed special leave from duty on full pay on compassionate ground for a period up to two weeks.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-142')::uuid,'PSR','Chapter 1: Structure & Appointments','Compassionate leave under Rule 120233 may be granted for burial of which persons?','["Spouse, child, parents or parents of spouse","Only colleagues","Only neighbours","Only retired contractors"]'::jsonb,0,'Correct. Under PSR Rule 120233, compassionate leave may be allowed for burial of spouse, child, parents or parents of spouse.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-143')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Leave of Absence under Rule 120234?','["Absence of an Officer from duty authorized on grounds of public policy","Absence without approval","Annual leave converted to salary","Leave granted only after dismissal"]'::jsonb,0,'Correct. Under PSR Rule 120234, Leave of Absence is absence of an Officer from duty authorized on grounds of public policy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-144')::uuid,'PSR','Chapter 1: Structure & Appointments','Who approves Leave of Absence?','["The Staff Union Chairman","The Accountant-General","The Head of the Civil Service of the Federation on recommendation of the Permanent Secretary/Head of Extra-Ministerial Office","The Officer’s neighbour"]'::jsonb,2,'Correct. Under PSR Rule 120234, Leave of Absence is approved by the Head of the Civil Service of the Federation on the recommendation of the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-145')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the pay status of Leave of Absence under Rule 120234?','["With double pay","With full annual leave allowance","With half salary","Without pay"]'::jsonb,3,'Correct. Under PSR Rule 120234, Leave of Absence shall be without pay.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-146')::uuid,'PSR','Chapter 1: Structure & Appointments','What must an Officer on Leave of Absence obtain before accepting paid employment?','["Express approval from the Office of the Head of the Civil Service of the Federation","A verbal approval from a colleague","Approval from a private company only","No approval is required"]'::jsonb,0,'Correct. Under PSR Rule 120235, an Officer on Leave of Absence shall not accept paid employment without previously obtaining express approval from the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-147')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is listed as a type of Leave of Absence under Rule 120236?','["Leave of Absence for Technical Aid Programmes","Leave for private trading","Leave for unauthorized travel","Leave for disciplinary avoidance"]'::jsonb,0,'Correct. Under PSR Rule 120236, Leave of Absence on grounds of public policy for Technical Aid Programmes is one of the listed types of Leave of Absence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-148')::uuid,'PSR','Chapter 1: Structure & Appointments','Leave of Absence to join a spouse on course of instruction abroad applies where the course duration is at least what period?','["Three months","Six months","Nine months","One month"]'::jsonb,2,'Correct. Under PSR Rule 120236(a), one type of Leave of Absence is to join a spouse on a course of instruction of not less than nine months’ duration abroad.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-149')::uuid,'PSR','Chapter 1: Structure & Appointments','Which appointments are not covered by Leave of Absence under Rule 120237?','["Secretary to Government of the Federation, Ministers, Secretary to State Government, Commissioners or any other political appointment","Study leave with pay","In-service training","Sabbatical leave"]'::jsonb,0,'Correct. Under PSR Rule 120237, Leave of Absence does not cover appointments such as SGF, Ministers, SSG, Commissioners or any other political appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-150')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the effect if an Officer accepts a political appointment listed under Rule 120237?','["He is deemed to have resigned from Service from the date of acceptance","He remains automatically on paid leave","He receives automatic promotion","He continues without approval"]'::jsonb,1,'Correct. Under PSR Rule 120237, an Officer who accepts such political appointment is deemed to have resigned from Service from the date of acceptance of the offer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-151')::uuid,'PSR','Chapter 1: Structure & Appointments','When is an Officer eligible for free passage to join a spouse abroad on course of instruction?','["Where the course is less than one month","Where the course is not less than nine months","Only after retirement","Only after dismissal"]'::jsonb,1,'Correct. Under PSR Rule 120238, an Officer who is also a public servant may join a spouse proceeding abroad on course of instruction and is eligible for free passage at Government expense where the course is not less than nine months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-152')::uuid,'PSR','Chapter 1: Structure & Appointments','On grounds of public policy, for how long may a spouse of a serving Officer be granted leave without pay to join the spouse on posting abroad?','["Not exceeding one month","Not exceeding two weeks","Not exceeding one year","Not exceeding five years"]'::jsonb,3,'Correct. Under PSR Rule 120239, the spouse of a serving Officer may be granted leave without pay for a period not exceeding five years to join the spouse on posting abroad.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-153')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the first-instance duration and possible extension for leave under Rule 120239?','["Four years in the first instance, subject to extension of not more than one year","One year in the first instance, subject to four years extension","Six months in the first instance, subject to ten years extension","Two weeks only"]'::jsonb,0,'Correct. Under PSR Rule 120239(d), the period a spouse can be on Leave of Absence is four years in the first instance and subject to an extension of not more than one year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-154')::uuid,'PSR','Chapter 1: Structure & Appointments','How is the period of leave under Rule 120239 treated for Service continuity?','["It is treated as dismissal","It shall not be regarded as a break in Service","It automatically ends the Officer’s career","It is treated as suspension"]'::jsonb,1,'Correct. Under PSR Rule 120239(b), such leave shall not be regarded as a break in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-155')::uuid,'PSR','Chapter 1: Structure & Appointments','Why are Officers selected for Technical Aid Corps Programme granted Leave of Absence?','["To preserve terminal benefits and ensure continuity of Service","To avoid all official responsibility","To convert them to political appointees","To remove them from the Service"]'::jsonb,0,'Correct. Under PSR Rule 120240, Officers selected for Technical Aid Corps Programme by the Ministry of Foreign Affairs are granted Leave of Absence on grounds of public policy to preserve terminal benefits and ensure continuity of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-156')::uuid,'PSR','Chapter 1: Structure & Appointments','What must Federal Public Service appointees who accept appointment as Special or Personal Assistants to political office holders do if they intend to return to the Service?','["Apply to the Head of the Civil Service of the Federation for Leave of Absence on grounds of public policy","Proceed without approval","Apply only to a political party","Resign permanently without option"]'::jsonb,0,'Correct. Under PSR Rule 120241, such appointees must apply to the Head of the Civil Service of the Federation for Leave of Absence on grounds of public policy if they intend to return to the Service at the end of the assignment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-157')::uuid,'PSR','Chapter 1: Structure & Appointments','Who must apply to the Head of the Civil Service of the Federation for Leave of Absence to join their spouses during tenure of office?','["Only retired Officers","Only contract staff","Spouses of the President, Vice President, Governors and Deputy Governors who are public servants","Only private contractors"]'::jsonb,2,'Correct. Under PSR Rule 120242, spouses of the President, Vice President, Governors and Deputy Governors who are public servants must apply to the Head of the Civil Service of the Federation for Leave of Absence on grounds of public policy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-158')::uuid,'PSR','Chapter 1: Structure & Appointments','How much notice must Officers give before the effective date of retirement?','["Three months","One week","One year","Five years"]'::jsonb,0,'Correct. Under PSR Rule 120243, Officers are required to give three months’ notice to retire from Service before the effective date of retirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-159')::uuid,'PSR','Chapter 1: Structure & Appointments','What should Officers do at the commencement of the three months before retirement?','["Proceed immediately on the mandatory one-month pre-retirement workshop or seminar","Proceed on casual leave","Report to a political office","Apply for paternity leave"]'::jsonb,0,'Correct. Under PSR Rule 120243, at the commencement of the three months, Officers should proceed immediately on the mandatory one-month pre-retirement workshop or seminar.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-160')::uuid,'PSR','Chapter 1: Structure & Appointments','What are retiring Officers expected to do during the remaining two months after the pre-retirement workshop?','["Put their records straight to facilitate speedy processing of retirement benefits","Proceed on foreign vacation only","Ignore retirement documentation","Commence disciplinary proceedings"]'::jsonb,0,'Correct. Under PSR Rule 120243, during the remaining two months, retiring Officers are expected to put their records straight to facilitate speedy processing of retirement benefits.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-161')::uuid,'PSR','Chapter 1: Structure & Appointments','When a Medical Board declares an Officer unfit to continue in Service, what leave is granted?','["Two months vacation leave prior to retirement","Six years study leave","Seven days casual leave","One year maternity leave"]'::jsonb,0,'Correct. Under PSR Rule 120244, when a Medical Board recommends that an Officer is medically unfit to continue in Service, he commences vacation leave prior to retirement for two months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-162')::uuid,'PSR','Chapter 1: Structure & Appointments','When does leave on permanent invalidation commence?','["On the day the Medical Board declares the Officer unfit to continue in Service","On the date of original appointment","One year after retirement","Only after annual leave roster is approved"]'::jsonb,0,'Correct. Under PSR Rule 120244, the two months leave commences on the day the Medical Board declares the Officer unfit to continue in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-163')::uuid,'PSR','Chapter 1: Structure & Appointments','How is an Officer treated if he fails without acceptable excuse to resume duty on the approved date after vacation leave?','["As being on study leave","As being promoted","As absent without leave and without pay","As being on maternity leave"]'::jsonb,2,'Correct. Under PSR Rule 120245, an Officer who fails without acceptable excuse to resume on the approved date after vacation leave is regarded as absent without leave and without pay.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-164')::uuid,'PSR','Chapter 1: Structure & Appointments','Can an Officer extend vacation leave beyond the date specified in his leave advice without consent?','["Yes, always","Only if a colleague agrees","No, not without the consent of the Permanent Secretary/Head of Extra-Ministerial Office","Yes, if he has casual leave"]'::jsonb,2,'Correct. Under PSR Rule 120245, no Officer shall extend vacation leave beyond the date specified in the leave advice without the consent of the Permanent Secretary/Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-165')::uuid,'PSR','Chapter 1: Structure & Appointments','Are dismissed Officers entitled to any form of leave?','["Yes, annual leave only","Yes, sick leave only","Yes, leave of absence only","No, they are not entitled to any form of leave"]'::jsonb,3,'Correct. Under PSR Rule 120246, Officers who are dismissed are not entitled to any form of leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-166')::uuid,'PSR','Chapter 1: Structure & Appointments','Annual vacation leave shall be based on what?','["Working days","Calendar months only","Saturdays only","Public holidays only"]'::jsonb,0,'Correct. Under PSR Rule 120247, annual vacation leave shall be based on working days.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-167')::uuid,'PSR','Chapter 1: Structure & Appointments','The period of any other leave such as casual, sick or maternity leave shall not include what?','["Working days","Saturdays, Sundays and Public Holidays","Normal office days","Approved duty days"]'::jsonb,1,'Correct. Under PSR Rule 120248, the period of any other leave such as casual leave, sick leave and maternity leave shall not be inclusive of Saturdays, Sundays and Public Holidays occurring therein.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-168')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 12, Section 2 of the PSR?','["It deals only with disciplinary procedure","It deals only with medical treatment abroad","It covers types of leave, entitlements, approval procedures, leave restrictions, study leave, leave of absence, pre-retirement leave, invalidation leave, overstaying leave and working-day computation","It deals only with procurement matters"]'::jsonb,2,'Correct. PSR Chapter 12, Section 2, Rules 120201 to 120248 cover the types of leave in the Federal Public Service, including annual leave, pro-rata leave, casual leave, sick leave, maternity leave, paternity leave, examination leave, sabbatical leave, study leave, compassionate leave, leave of absence, pre-retirement leave, invalidation leave, overstaying leave, dismissal and leave computation based on working days.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-169')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130101, what does Healthcare Provider mean?','["A Staff Union welfare officer","A duly appointed Healthcare Provider in accordance with the National Health Insurance Scheme","A private person chosen by the Officer without approval","A family member trained in first aid"]'::jsonb,1,'Correct. Under PSR Chapter 13, Section 1, Rule 130101, “Healthcare Provider” means a duly appointed Healthcare Provider in accordance with the National Health Insurance Scheme.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-170')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130101, what does Hospital mean?','["Any building where an Officer rests during illness","A medical facility run by a duly approved Healthcare Provider","Any private residence used for treatment","A pharmacy shop selected by an Officer"]'::jsonb,1,'Correct. Under PSR Rule 130101, “Hospital” means a medical facility run by a duly approved Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-171')::uuid,'PSR','Chapter 1: Structure & Appointments','Who is a Medical Officer under Rule 130101?','["A Medical Practitioner authorized to render healthcare services","A Staff Union official responsible for medical allowance","A private hospital cashier","A family member of the Officer"]'::jsonb,0,'Correct. Under PSR Rule 130101, a “Medical Officer” is a Medical Practitioner who is authorized to render healthcare services.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-172')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130101, who is a Private Practitioner?','["An approved Healthcare Provider under NHIS","Any registered Medical or Dental Practitioner outside the National Health Insurance Scheme","A Permanent Secretary who approves medical leave","A Medical Board appointed by Government"]'::jsonb,1,'Correct. Under PSR Rule 130101, “Private Practitioner” means any other registered Medical or Dental Practitioner outside the National Health Insurance Scheme.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-173')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is correctly matched under Rule 130101?','["Hospital means a medical facility run by a duly approved Healthcare Provider","Medical Officer means a Staff Union Chairman","Healthcare Provider means any family member of an Officer","Private Practitioner means a Permanent Secretary"]'::jsonb,0,'Correct. PSR Rule 130101 defines a Hospital as a medical facility run by a duly approved Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-174')::uuid,'PSR','Chapter 1: Structure & Appointments','What is required of every person appointed in any capacity under Rule 130102?','["To present himself for examination to a recognized Healthcare Provider","To proceed immediately on annual leave","To select any private practitioner without approval","To submit only a promotion form"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 1, Rule 130102, every person appointed in any capacity must present himself for examination to a recognized Healthcare Provider to determine fitness for Government service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-175')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the purpose of the compulsory medical examination on appointment?','["To determine whether the candidate is fit for Government service","To determine the Officer’s promotion seniority","To approve the Officer’s annual leave allowance","To decide the Officer’s pension after retirement"]'::jsonb,0,'Correct. Under PSR Rule 130102, the medical examination on appointment is to ascertain whether the candidate is fit for Government service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-176')::uuid,'PSR','Chapter 1: Structure & Appointments','What happens if a candidate is not finally passed as physically fit for Service?','["His appointment shall not be proceeded with","His appointment becomes automatic","His salary is doubled","His annual leave begins immediately"]'::jsonb,0,'Correct. Under PSR Rule 130102, if the candidate is not finally passed as physically fit for Service, his appointment shall not be proceeded with.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-177')::uuid,'PSR','Chapter 1: Structure & Appointments','How often must an Officer present himself for medical examination in Service?','["Every five years","Every month","Every ten years","Only after retirement"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 1, Rule 130103, an Officer shall present himself to a Healthcare Provider for examination every five years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-178')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the purpose of the five-year medical examination under Rule 130103?','["To certify that the Officer is sound in health and fit to continue in Service","To determine whether the Officer should be promoted automatically","To approve foreign travel for the Officer’s family","To replace the Officer’s annual performance report"]'::jsonb,0,'Correct. Under PSR Rule 130103, the five-year examination is to certify that the Officer is sound in health and fit to continue in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-179')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130103 is subject to Government policy on what issue?','["The right of individuals as it pertains to specific diseases from time to time","Only official vehicle allocation","Only disciplinary proceedings","Only procurement approval thresholds"]'::jsonb,0,'Correct. PSR Rule 130103 states that the five-year medical examination is without bias to Government policy on the right of individuals as it pertains to specific diseases from time to time.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-180')::uuid,'PSR','Chapter 1: Structure & Appointments','How must medical certificates, Medical Board reports, dental treatment records and confidential health reports be treated?','["Strictly confidential","Publicly displayed on notice boards","Released to all staff without restriction","Published in national newspapers"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 1, Rule 130104, medical certificates, Medical Board reports, dental treatment records, private practitioner reports and confidential health reports of an Officer shall be treated as strictly confidential.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-181')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following records is covered by the confidentiality rule in Rule 130104?','["Reports of Medical Boards","Weekly attendance register only","Promotion interview timetable only","Procurement bid documents only"]'::jsonb,0,'Correct. Under PSR Rule 130104, reports of Medical Boards are among the medical documents that must be treated as strictly confidential.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-182')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130104 permits an Officer’s health record to be kept where?','["In the Ministry of Health","At the Staff Union office only","In a newspaper archive","At the Officer’s private business office"]'::jsonb,0,'Correct. Under PSR Rule 130104, the confidentiality rule does not preclude the keeping of an Officer’s health record in the Ministry of Health.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-183')::uuid,'PSR','Chapter 1: Structure & Appointments','When an Officer is transferred to the Service of another Government, what may happen to his health record under Rule 130104?','["It may be transferred to the corresponding office","It must be destroyed immediately","It must be published for public information","It must be kept by the Staff Union only"]'::jsonb,0,'Correct. Under PSR Rule 130104, the health record of an Officer may be transferred to the corresponding office when the staff is transferred to the Service of another Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-184')::uuid,'PSR','Chapter 1: Structure & Appointments','Who may call upon an Officer to present himself to an approved Healthcare Provider or Medical Board for special medical tests?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Officer’s colleague","The Staff Union Treasurer","The Officer’s landlord"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 1, Rule 130105, the Permanent Secretary or Head of Extra-Ministerial Office may call upon an Officer to present himself to an approved Healthcare Provider or Medical Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-185')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the purpose of a special medical test under Rule 130105?','["To ascertain whether the Officer is physically and mentally capable of performing his duties or duties of a proposed transfer appointment","To determine the Officer’s political preference","To approve burial expenses","To replace disciplinary procedure"]'::jsonb,0,'Correct. Under PSR Rule 130105, the test is to ascertain whether the Officer is physically and mentally capable of performing the duties of his appointment or any appointment to which it is proposed to transfer him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-186')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130105 may apply where it is proposed to do what to an Officer?','["Transfer him to another appointment","Pay him burial expenses","Grant him pension automatically","Delete his medical records"]'::jsonb,0,'Correct. PSR Rule 130105 covers examination to determine whether an Officer is capable of performing the duties of his current appointment or any appointment to which it may be proposed to transfer him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-187')::uuid,'PSR','Chapter 1: Structure & Appointments','At the expiration of an Officer’s Leave of Absence, what is he required to do?','["Present himself for examination to an approved Healthcare Provider","Resume without any medical check under all circumstances","Proceed automatically on retirement","Submit only a transport claim"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 1, Rule 130106, at the expiration of Leave of Absence, the Officer must present himself for examination to an approved Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-188')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the purpose of the medical test after Leave of Absence?','["To obtain a report on the Officer’s continued physical and mental fitness to return to duty","To approve the Officer’s promotion examination","To determine the Officer’s housing allowance","To calculate burial expenses"]'::jsonb,0,'Correct. Under PSR Rule 130106, the examination after Leave of Absence is to obtain a report on the Officer’s continued physical and mental fitness to return to his duties.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-189')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130107, who pays examination fees for examinations under Rules 130105 and 130106, unless there is a special regulation or arrangement to the contrary?','["The relevant MDAs","The Officer’s neighbour","The Staff Union Chairman","The private practitioner only"]'::jsonb,0,'Correct. Under PSR Rule 130107(a), fees for examinations under the two preceding Rules shall, unless special regulations or arrangements provide otherwise, be paid by the relevant MDAs.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-190')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130107, the person appointed to conduct the examination may call whom into consultation?','["A specialist","A procurement officer","A newspaper editor","A transport contractor"]'::jsonb,0,'Correct. Under PSR Rule 130107(b), the person or persons appointed to conduct the examination may call a specialist into consultation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-191')::uuid,'PSR','Chapter 1: Structure & Appointments','Who pays the specialist’s fee where the specialist assists in rendering a report to Government?','["Public funds","The Officer’s landlord","The Staff Union only","The Officer’s family automatically"]'::jsonb,0,'Correct. Under PSR Rule 130107(b), any fee due to the specialist for assistance in rendering a report to Government shall be paid from public funds.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-192')::uuid,'PSR','Chapter 1: Structure & Appointments','To whom is the report of examination furnished under Rule 130107?','["The Government","The Officer’s neighbour","The Staff Union only","The press"]'::jsonb,0,'Correct. Under PSR Rule 130107(c), the report of the examination shall be furnished to the Government and communicated to the Officer concerned by the Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-193')::uuid,'PSR','Chapter 1: Structure & Appointments','Who communicates the examination report to the Officer concerned under Rule 130107?','["The Healthcare Provider","The Officer’s colleague","The Staff Union Treasurer","The airline company"]'::jsonb,0,'Correct. Under PSR Rule 130107(c), the report is communicated to the Officer concerned by the Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-194')::uuid,'PSR','Chapter 1: Structure & Appointments','When should the Officer be informed of Government’s decision after consideration of the medical report?','["At the earliest possible date","Only after retirement","Only after five years","Never, because it is secret"]'::jsonb,0,'Correct. Under PSR Rule 130107(d), the Officer shall be informed at the earliest possible date of the decision reached by Government after consideration of the report.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-195')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer is dissatisfied with Government’s decision after the medical report, what may he do?','["Make representation to that effect","Alter the medical report personally","Refuse all official communication","Publish the confidential medical report"]'::jsonb,0,'Correct. Under PSR Rule 130107(d), if the Officer is dissatisfied with Government’s decision, he is at liberty to make representation to that effect.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-196')::uuid,'PSR','Chapter 1: Structure & Appointments','Who decides whether further medical evidence should be called for after an Officer’s representation?','["The Government","The Officer’s neighbour","The Staff Union Chairman","The private hospital receptionist"]'::jsonb,0,'Correct. Under PSR Rule 130107(d), after an Officer’s representation, Government decides at its discretion whether any further medical evidence shall be called for.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-197')::uuid,'PSR','Chapter 1: Structure & Appointments','Who may grant an Officer leave to visit a Medical Specialist or Dentist?','["His Permanent Secretary or Head of Extra-Ministerial Office","His landlord","His colleague","His transport contractor"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 1, Rule 130108, an Officer may be granted leave by his Permanent Secretary or Head of Extra-Ministerial Office to visit a Medical Specialist or Dentist.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-198')::uuid,'PSR','Chapter 1: Structure & Appointments','Leave to visit a Medical Specialist or Dentist may be granted only if certified by whom?','["The Healthcare Provider","The Staff Union only","The Officer’s family friend","A newspaper editor"]'::jsonb,0,'Correct. Under PSR Rule 130108, leave to visit a Medical Specialist or Dentist may be granted only if the Healthcare Provider certifies the required medical grounds.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-199')::uuid,'PSR','Chapter 1: Structure & Appointments','What must the Healthcare Provider certify before leave to visit a Specialist or Dentist is granted?','["That he is unable to deal with the case himself and postponement will definitely affect the Officer’s health","That the Officer wants to travel for personal shopping","That the Officer has completed a promotion course","That the Officer is due for retirement automatically"]'::jsonb,0,'Correct. Under PSR Rule 130108, the Healthcare Provider must certify that he is unable to deal with the case himself and that postponing consultation will definitely affect the Officer’s health.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-200')::uuid,'PSR','Chapter 1: Structure & Appointments','For free transport purposes, how is an Officer treated when granted leave under Rule 130108 to visit a Medical Specialist or Dentist?','["As travelling on duty","As absent without leave","As retired from Service","As dismissed from Service"]'::jsonb,0,'Correct. Under PSR Rule 130108, an Officer granted leave to visit a Medical Specialist or Dentist is treated, for free transport facilities, as travelling on duty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-201')::uuid,'PSR','Chapter 1: Structure & Appointments','Which benefit is excluded when an Officer is granted leave under Rule 130108?','["Travelling allowance","Free transport facilities","Medical consultation leave","Official recognition of the journey"]'::jsonb,0,'Correct. Under PSR Rule 130108, the Officer is treated as travelling on duty for free transport facilities, but not for travelling allowance.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-202')::uuid,'PSR','Chapter 1: Structure & Appointments','If no medical certificate is given for visiting a Medical Specialist or Dentist, what may the Officer apply for?','["Casual leave under Rule 120214","Automatic study leave","Retirement leave under Rule 120244","Dismissal clearance"]'::jsonb,0,'Correct. Under PSR Rule 130108, if no medical certificate is given, the Officer may apply for casual leave under Rule 120214.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-203')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 13, Section 1 of the PSR?','["It covers definitions, medical examination on appointment, five-year examination, confidentiality of medical documents, special medical tests, examination after leave of absence, examination procedure and leave to visit a Specialist or Dentist","It deals only with burial expenses","It deals only with procurement approvals","It deals only with disciplinary dismissal"]'::jsonb,0,'Correct. PSR Chapter 13, Section 1, Rules 130101 to 130108 cover general medical and dental procedure provisions, including definitions, compulsory medical examinations, confidentiality of medical records, special tests, post-leave medical tests, examination procedure and leave to visit a Medical Specialist or Dentist.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-204')::uuid,'PSR','Chapter 1: Structure & Appointments','What must an Officer do if he is ill and unable to report for duty?','["Wait until he resumes before explaining","Notify his Ministry or Agency in writing or by any other means of communication","Ask another Officer to sign the attendance register for him","Proceed on annual leave automatically"]'::jsonb,1,'Correct. Under PSR Chapter 13, Section 3, Rule 130301, an Officer who is ill and unable to report for duty must notify his Ministry or Agency in writing or by any other means of communication.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-205')::uuid,'PSR','Chapter 1: Structure & Appointments','Which document may support prolonged absence from duty on the ground of illness?','["Promotion letter","Excuse Duty Certificate","Annual Performance Evaluation Report","Posting instruction"]'::jsonb,1,'Correct. Under PSR Rule 130301, prolonged absence from duty on the ground of illness should be supported by documents such as an Excuse Duty Certificate.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-206')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is listed under Rule 130301 as a document supporting prolonged illness-related absence?','["Light Duty Certificate","Certificate of seniority","Letter of commendation","Retirement clearance"]'::jsonb,0,'Correct. Under PSR Rule 130301, a Light Duty Certificate is one of the documents that may support prolonged absence from duty on the ground of illness.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-207')::uuid,'PSR','Chapter 1: Structure & Appointments','A Medical Certificate of Treatment used to support prolonged illness-related absence must be authorized by whom?','["The Officer’s friend","An approved Healthcare Provider","The Staff Union Chairman","A private travel agent"]'::jsonb,1,'Correct. Under PSR Rule 130301, a Medical Certificate of Treatment supporting prolonged absence must be duly authorized by an approved Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-208')::uuid,'PSR','Chapter 1: Structure & Appointments','An Officer receiving medical treatment within or outside the location of his duty post must report to his employer within what period?','["7 days","48 hours","30 days","3 months"]'::jsonb,1,'Correct. Under PSR Rule 130302, an Officer receiving medical treatment within or outside the location of his duty post must report to his employer within 48 hours.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-209')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130302 applies to an Officer receiving medical treatment in which location?','["Only outside Nigeria","Only inside his duty post","Within or outside the location of his duty post","Only in a private hospital"]'::jsonb,2,'Correct. Under PSR Rule 130302, the duty to report within 48 hours applies whether the Officer is receiving treatment within or outside the location of his duty post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-210')::uuid,'PSR','Chapter 1: Structure & Appointments','When an Officer presents himself to an authorized Healthcare Provider for medical examination, what should the Healthcare Provider do?','["Examine and treat him","Refer him to the Staff Union immediately","Reject him unless he is on annual leave","Declare him absent without leave automatically"]'::jsonb,0,'Correct. Under PSR Rule 130303, when an Officer presents himself to a duly authorized Healthcare Provider for medical examination, the Provider shall examine and treat him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-211')::uuid,'PSR','Chapter 1: Structure & Appointments','If necessary, what may the Healthcare Provider give an Officer after medical examination under Rule 130303?','["Any of the certificates listed in Rule 130301","A promotion letter","A posting letter","A pension clearance form"]'::jsonb,0,'Correct. Under PSR Rule 130303, the Healthcare Provider may, where necessary, give the Officer any of the certificates listed in Rule 130301.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-212')::uuid,'PSR','Chapter 1: Structure & Appointments','Where an Officer is admitted as an in-patient after examination, what certificate should the Healthcare Provider issue?','["Medical Certificate of Treatment","Annual Leave Certificate","Disciplinary Clearance Certificate","Promotion Eligibility Certificate"]'::jsonb,0,'Correct. Under PSR Rule 130303, if the Officer is admitted as an in-patient, the Healthcare Provider shall issue a Medical Certificate of Treatment to the Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-213')::uuid,'PSR','Chapter 1: Structure & Appointments','Who should notify the Healthcare Provider when an Officer is too ill to present himself for medical examination?','["His Next of Kin","The nearest driver","The Staff Union Treasurer","The Officer’s neighbour only"]'::jsonb,0,'Correct. Under PSR Rule 130304, where an Officer is so ill that he is physically unable to present himself for medical examination, his Next of Kin shall notify the Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-214')::uuid,'PSR','Chapter 1: Structure & Appointments','Where an Officer is too ill to attend medical examination, what may the Healthcare Provider do?','["Ignore the case until the Officer resumes duty","Arrange for the Officer to be brought to hospital or visit him for examination and treatment","Automatically stop his salary","Issue a dismissal letter"]'::jsonb,1,'Correct. Under PSR Rule 130304, the Healthcare Provider may arrange for the Officer to be brought to hospital for examination and treatment or visit the Officer to examine and treat him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-215')::uuid,'PSR','Chapter 1: Structure & Appointments','If examination under Rule 130304 results in the Officer being admitted as an in-patient, who must be informed?','["The Officer’s Ministry or Extra-Ministerial Office","The Officer’s landlord only","The Staff Union only","The nearest police station"]'::jsonb,0,'Correct. Under PSR Rule 130304, if the Officer is admitted to hospital as an in-patient, the Healthcare Provider will inform the Officer’s Ministry or Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-216')::uuid,'PSR','Chapter 1: Structure & Appointments','When an Officer forwards a private practitioner’s report to a Healthcare Provider, what should the Healthcare Provider do before issuing a certificate?','["Consult with the private practitioner","Delete the report immediately","Refer the matter to the Accountant-General","Ask the Officer to resign"]'::jsonb,0,'Correct. Under PSR Rule 130305, where an Officer forwards a sickness report from a private practitioner, the Healthcare Provider will, after due consultation with the private practitioner, issue the appropriate certificate.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-217')::uuid,'PSR','Chapter 1: Structure & Appointments','Without examining the patient, what is the maximum period of excuse or light duty on the first certificate issued under Rule 130305?','["One month","Three days","Seven days","Three months"]'::jsonb,1,'Correct. Under PSR Rule 130305, the period of excuse or light duty entered on the first certificate shall not exceed three days unless the Healthcare Provider has examined the patient.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-218')::uuid,'PSR','Chapter 1: Structure & Appointments','If the Healthcare Provider has examined the patient, the first certificate under Rule 130305 may cover up to what period?','["Seven days","Twelve months","Six months","Thirty days"]'::jsonb,0,'Correct. Under PSR Rule 130305, where the Healthcare Provider has examined the patient, the first certificate may be for up to seven days.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-219')::uuid,'PSR','Chapter 1: Structure & Appointments','Each extension of excuse or light duty under Rule 130305 must not exceed what period?','["Seven days","One year","Six months","Thirty days"]'::jsonb,0,'Correct. Under PSR Rule 130305, each period of extension shall not exceed seven days.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-220')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130305, not more than what total period of sick leave may be allowed on extensions?','["One week","One year","Three months","Five years"]'::jsonb,2,'Correct. Under PSR Rule 130305, not more than a total of three months sick leave may be allowed on such extensions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-221')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer is still not fit for duty after three months sick leave under Rule 130305, what should happen?','["He should be examined by a Medical Board","He should automatically be promoted","He should be posted abroad","He should be granted study leave"]'::jsonb,0,'Correct. Under PSR Rule 130305, if the Officer is still not fit for duty after three months sick leave, he shall be examined by a Medical Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-222')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130305 also applies to an Officer admitted to a Specialist Hospital on whose recommendation?','["The Staff Union","The Healthcare Provider","The Officer’s driver","The Officer’s neighbour"]'::jsonb,1,'Correct. Under PSR Rule 130305, the rule also applies to an Officer admitted to a Specialist Hospital on the recommendation of a Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-223')::uuid,'PSR','Chapter 1: Structure & Appointments','When must a Healthcare Provider report to the Officer’s Ministry or Extra-Ministerial Office under Rule 130306?','["When an Officer is admitted and when he is discharged from a Hospital","Only when the Officer is promoted","Only when the Officer retires","Only during annual leave"]'::jsonb,0,'Correct. Under PSR Rule 130306, the Healthcare Provider shall report to the Officer’s Ministry or Extra-Ministerial Office when the Officer is admitted and when he is discharged from a Hospital.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-224')::uuid,'PSR','Chapter 1: Structure & Appointments','What should a Healthcare Provider report if an Officer refuses or neglects medical advice?','["The circumstances to the Officer’s Ministry or Extra-Ministerial Office","The matter only to the Officer’s family","Nothing, because it is private","Only the Officer’s promotion status"]'::jsonb,0,'Correct. Under PSR Rule 130306, the Healthcare Provider shall report where an Officer refuses to carry out or is neglecting to carry out medical advice.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-225')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130306, what must a Healthcare Provider do if he believes an Officer is feigning ill-health?','["Report the circumstances to the Officer’s Ministry or Extra-Ministerial Office","Grant automatic retirement","Approve annual leave immediately","Pay the Officer’s salary personally"]'::jsonb,0,'Correct. Under PSR Rule 130306, where in the opinion of the Healthcare Provider an Officer is feigning ill-health, the circumstances shall be reported to the Officer’s Ministry or Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-226')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer is required to appear before a Medical Board, what must he do?','["Present himself at the instructed place and time","Choose whether to attend after retirement","Ignore the instruction if he has a private doctor","Send another person to appear for him"]'::jsonb,0,'Correct. Under PSR Rule 130307, an Officer required to be examined by a Medical Board must present himself for examination at the place and time instructed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-227')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the effect of a Medical Board’s recommendation under Rule 130307?','["It supersedes any medical advice already given by a Healthcare Provider","It has no effect on prior medical advice","It is only advisory to the Officer’s friend","It automatically grants promotion"]'::jsonb,0,'Correct. Under PSR Rule 130307, the Officer must comply with the Medical Board’s recommendations, which supersede any medical advice already given by a Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-228')::uuid,'PSR','Chapter 1: Structure & Appointments','An Officer who fails to comply with Rule 130307 may be treated as what?','["Absent without leave","Automatically retired","Promoted on medical grounds","On vacation leave"]'::jsonb,0,'Correct. Under PSR Rule 130307, an Officer who fails to comply may render himself liable to be treated as having been absent without leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-229')::uuid,'PSR','Chapter 1: Structure & Appointments','Who arranges for the responsibilities described in Rules 130309 to 130313 to be assigned to appropriate Officers?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Officer’s colleague","The Staff Union Chairman","The private practitioner"]'::jsonb,0,'Correct. Under PSR Rule 130308, the Permanent Secretary or Head of Extra-Ministerial Office arranges for the responsibilities in Rules 130309 to 130313 to appropriate Officers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-230')::uuid,'PSR','Chapter 1: Structure & Appointments','What records must Human Resource Management or Administration maintain under Rule 130309?','["Only the Officers’ examination scores","Up-to-date residential addresses, telephone numbers and next-of-kin contact details","Only promotion interview questions","Only pension payment slips"]'::jsonb,1,'Correct. Under PSR Rule 130309, Human Resource Management/Administration must maintain up-to-date records of residential addresses, telephone numbers and contact details of next of kin of Officers and staff.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-231')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer’s absence from duty is not explained within 24 hours, what should be done?','["Enquiry should be made at his recorded address to ascertain the cause of absence","His promotion should be approved immediately","His annual leave should automatically begin","No action should be taken"]'::jsonb,0,'Correct. Under PSR Rule 130310, if an Officer’s absence is not explained within 24 hours, enquiry shall be made at his recorded address to ascertain the cause of absence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-232')::uuid,'PSR','Chapter 1: Structure & Appointments','Where an Officer is so ill that he cannot present himself for medical examination, who reports the circumstances and whereabouts to the nearest Healthcare Provider?','["His Ministry or Extra-Ministerial Office","The Staff Union only","His private business partner","The transport officer only"]'::jsonb,0,'Correct. Under PSR Rule 130311, where an Officer is too ill to present himself for medical examination, the circumstances of his whereabouts should be reported by his Ministry or Extra-Ministerial Office to the nearest Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-233')::uuid,'PSR','Chapter 1: Structure & Appointments','When an Officer reports that he is prevented from performing his duties, what should he be given?','["A note requesting the Healthcare Provider to examine and treat him","A dismissal letter","A posting instruction","A promotion form"]'::jsonb,0,'Correct. Under PSR Rule 130312, the Officer should be instructed or authorized as explained in Rule 130305 and provided with a note requesting the Healthcare Provider to examine and treat him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-234')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130312 applies unless which rule applies?','["Rule 130311","Rule 130101","Rule 130209","Rule 120201"]'::jsonb,0,'Correct. Under PSR Rule 130312, the instruction to staff reporting sick applies unless Rule 130311 applies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-235')::uuid,'PSR','Chapter 1: Structure & Appointments','Who initiates action when it is desirable to appoint a Medical Board?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Officer’s landlord","The Staff Union Treasurer","The private hospital receptionist"]'::jsonb,0,'Correct. Under PSR Rule 130313, when it is desirable to appoint a Medical Board, the Permanent Secretary or Head of Extra-Ministerial Office is responsible for initiating action.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-236')::uuid,'PSR','Chapter 1: Structure & Appointments','When an Officer presents himself to a Healthcare Provider for examination, what must the Healthcare Provider do?','["Examine and treat him and give the appropriate certificate or inform the Ministry if admitted as an in-patient","Immediately grant annual leave","Refer the matter to the police without examination","Declare the Officer dismissed"]'::jsonb,0,'Correct. Under PSR Rule 130314, when an Officer presents himself to a Healthcare Provider, the Provider shall examine and treat him and give the appropriate certificate, or inform the Ministry/Extra-Ministerial Office if he is admitted as an in-patient.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-237')::uuid,'PSR','Chapter 1: Structure & Appointments','An Officer absent from duty on the ground of ill-health may be regarded as absent on sick leave if what condition is met?','["The absence is covered by proper authority","The Officer has pending promotion","The Officer is close to retirement","The Officer has not informed anyone"]'::jsonb,0,'Correct. Under PSR Rule 130315, an Officer not on leave of absence who is absent from duty on grounds of ill-health will be regarded as absent on sick leave if the absence is covered by proper authority.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-238')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130315 applies to an Officer who is not on what type of leave?','["Leave of absence","Annual leave only","Maternity leave only","Casual leave only"]'::jsonb,0,'Correct. Under PSR Rule 130315, the rule applies to an Officer not being on leave of absence who is absent from duty on the ground of ill-health.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-239')::uuid,'PSR','Chapter 1: Structure & Appointments','An Officer on vacation leave who cannot resume duty at the end of authorized leave due to certified ill-health may be granted what?','["Sick leave at the expiration of his annual leave","Automatic promotion","Study leave with pay","Dismissal without inquiry"]'::jsonb,0,'Correct. Under PSR Rule 130316, an Officer on vacation leave who is unable to resume duty at the expiration of authorized leave by reason of ill-health duly certified by an approved Healthcare Provider may be granted sick leave at the expiration of his annual leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-240')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130316, the Officer’s ill-health must be certified by whom?','["An approved Healthcare Provider","A colleague","A Staff Union official","A private travel agent"]'::jsonb,0,'Correct. Under PSR Rule 130316, the inability to resume duty after vacation leave must be duly certified by an approved Healthcare Provider before sick leave may be granted.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-241')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the maximum aggregate sick leave allowed to an Officer during any period of twelve months?','["Three months","Twelve months","Seven days","Five years"]'::jsonb,0,'Correct. Under PSR Rule 130317(i), the maximum aggregate sick leave allowed to an Officer during any period of twelve months is three months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-242')::uuid,'PSR','Chapter 1: Structure & Appointments','If an Officer has been absent on grounds of ill-health for more than three months within twelve calendar months, what should happen?','["He should appear before a Medical Board","He should be paid overtime automatically","He should be transferred abroad","He should be promoted immediately"]'::jsonb,0,'Correct. Under PSR Rule 130317(i), an Officer absent on grounds of ill-health for an aggregate period exceeding three months within twelve calendar months should appear before a Medical Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-243')::uuid,'PSR','Chapter 1: Structure & Appointments','Why should an Officer who exceeds three months aggregate sick leave within twelve months appear before a Medical Board?','["To ascertain whether he should be invalided from Service","To approve his promotion interview","To process his duty tour allowance","To assign him official vehicle only"]'::jsonb,0,'Correct. Under PSR Rule 130317(i), the Medical Board is to ascertain whether the Officer should be invalided from Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-244')::uuid,'PSR','Chapter 1: Structure & Appointments','An Officer incapacitated by injury sustained in the course of official duties is entitled to what?','["Full emolument until discharged from sick leave or permanently invalided","Half salary for one week only","No salary until retirement","Only transport allowance"]'::jsonb,0,'Correct. Under PSR Rule 130317(ii), an Officer incapacitated by injury sustained in the course of official duties is entitled to draw full emolument until discharged from sick leave or permanently invalided.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-245')::uuid,'PSR','Chapter 1: Structure & Appointments','What happens when a Medical Board or Healthcare Provider recommends that an Officer be permanently invalided?','["He shall forthwith commence vacation leave prior to retirement","He shall automatically receive promotion","He shall begin study leave","He shall continue work without change"]'::jsonb,0,'Correct. Under PSR Rule 130318, an Officer recommended by a Medical Board or Healthcare Provider to be permanently invalided shall forthwith commence vacation leave prior to retirement in accordance with Rule 120244.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-246')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130318 refers permanent invalidation to which leave rule?','["Rule 120244","Rule 130101","Rule 140101","Rule 100301"]'::jsonb,0,'Correct. Under PSR Rule 130318, vacation leave prior to retirement on permanent invalidation is to be in accordance with Rule 120244.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-247')::uuid,'PSR','Chapter 1: Structure & Appointments','Sick leave for a hospitalized Officer may be allowed on the certificate of an approved Healthcare Provider for what period in the first instance?','["Up to three months","Only 24 hours","Seven years","One working day"]'::jsonb,0,'Correct. Under PSR Rule 130319, sick leave for a period up to three months in the first instance may be allowed on the certificate of an approved Healthcare Provider to an Officer who is hospitalized.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-248')::uuid,'PSR','Chapter 1: Structure & Appointments','If a hospitalized Officer remains hospitalized after the first three months, who must arrange for Medical Board examination?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Staff Union Chairman","The Officer’s neighbour","The Accountant-General only"]'::jsonb,0,'Correct. Under PSR Rule 130319, if the Officer is still hospitalized after three months, his Permanent Secretary or Head of Extra-Ministerial Office must arrange for him to be examined by a Medical Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-249')::uuid,'PSR','Chapter 1: Structure & Appointments','Why is a Medical Board examination arranged under Rule 130319 after three months hospitalization?','["To ascertain whether the Officer should be invalided from Service or allowed further paid sick leave","To approve annual leave allowance","To determine promotion seniority","To issue a posting letter"]'::jsonb,0,'Correct. Under PSR Rule 130319, the Medical Board examines the Officer to ascertain whether he should be invalided from Service or allowed further paid sick leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-250')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 13, Section 3 of the PSR?','["It regulates absence from duty due to illness, notification, medical certificates, Medical Boards, Ministry responsibilities, Healthcare Provider duties and sick leave rules","It deals only with overseas estacode","It deals only with procurement procedure","It deals only with disciplinary dismissal"]'::jsonb,0,'Correct. PSR Chapter 13, Section 3, Rules 130301 to 130319 cover absence from duty on account of illness, including notice to employer, duty to report, medical certification, Medical Boards, Ministry responsibilities, Healthcare Provider responsibilities and sick leave rules.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-251')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130401, when will Government repatriate the corpse of a Nigerian Officer who dies abroad?','["When the Officer dies abroad while on official duty tour or course of instruction and the deceased’s family requests repatriation","When the Officer dies abroad during a private holiday only","Whenever any Nigerian citizen dies abroad","Only when the Officer’s colleague requests it"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 4, Rule 130401, Government shall repatriate, at the request of the deceased’s family, the corpse of a Nigerian Officer who dies abroad while on official duty tour or course of instruction.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-252')::uuid,'PSR','Chapter 1: Structure & Appointments','Who must request repatriation before Government repatriates the corpse under Rule 130401?','["The deceased’s family","The Staff Union","The airline company","The Officer’s landlord"]'::jsonb,0,'Correct. Under PSR Rule 130401, Government repatriates the corpse at the request of the deceased’s family.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-253')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130401 applies to the corpse of which Officer?','["A Nigerian Officer who dies abroad while on official duty tour or course of instruction","Any retired Officer living abroad permanently","Any Officer who travels abroad privately without approval","Any Officer’s distant relation abroad"]'::jsonb,0,'Correct. Under PSR Rule 130401, the rule applies to a Nigerian Officer who dies abroad while on official duty tour or course of instruction.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-254')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130401, Government may also repatriate the corpse of the spouse of an Officer if what condition is met?','["The spouse was duly authorized to accompany the Officer on the duty tour or course of instruction","The spouse travelled abroad privately without approval","The spouse was visiting another country for personal business","The spouse was not connected with the official duty tour"]'::jsonb,0,'Correct. Under PSR Rule 130401, Government may repatriate the corpse of the spouse of an Officer who was duly authorized to accompany him on the duty tour or course of instruction.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-255')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is part of Government’s responsibility under Rule 130401?','["Preparation of the body, including embalming","Payment of unlimited family travel allowance","Purchase of luxury personal effects for the deceased","Automatic promotion of the deceased Officer"]'::jsonb,0,'Correct. Under PSR Rule 130401(i), Government’s responsibility includes preparation of the body, specifically embalming.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-256')::uuid,'PSR','Chapter 1: Structure & Appointments','What type of coffin or casket may Government purchase under Rule 130401?','["A reasonably priced coffin or casket, including inner zinc and wooden coffin as stipulated by Airline Regulations","Any luxury casket chosen without limit by the family","Only a plastic coffin chosen by the airline","No coffin or casket at all"]'::jsonb,0,'Correct. Under PSR Rule 130401(ii), Government’s responsibility includes purchase of a reasonably priced coffin or casket, including inner zinc and wooden coffin as stipulated by Airline Regulations.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-257')::uuid,'PSR','Chapter 1: Structure & Appointments','The coffin or casket under Rule 130401 must comply with what requirement?','["Airline Regulations","Staff Union Constitution","Procurement examination timetable","Promotion interview rules"]'::jsonb,0,'Correct. Under PSR Rule 130401(ii), the inner zinc and wooden coffin must be as stipulated by Airline Regulations.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-258')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130401, transportation of the corpse is to which destination?','["The Officer’s home town at reasonable cost","Any foreign hotel selected by the family","The Officer’s last overseas shopping location","The airport only, without onward movement"]'::jsonb,0,'Correct. Under PSR Rule 130401(iii), Government’s responsibility includes transportation of the corpse to the Officer’s home town at reasonable cost.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-259')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the limit of Government’s responsibility for obituary publication under Rule 130401?','["Cost not exceeding one full page advert in one National Newspaper at prevailing rates","Unlimited adverts in all newspapers","Only a radio announcement without cost limit","No obituary publication under any circumstance"]'::jsonb,0,'Correct. Under PSR Rule 130401(iv), Government’s responsibility includes payment of the cost not exceeding one full page advert in one National Newspaper for publication of the obituary at prevailing rates.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-260')::uuid,'PSR','Chapter 1: Structure & Appointments','The obituary payment under Rule 130401 is made to whom?','["The family of the deceased","The airline company only","The Staff Union chairman","The deceased Officer’s driver"]'::jsonb,0,'Correct. Under PSR Rule 130401(iv), payment for the obituary publication is made to the family of the deceased.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-261')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following is NOT listed as Government’s responsibility under Rule 130401?','["Unlimited payment for all family ceremonies","Preparation of the body","Reasonably priced coffin or casket","Transportation of the corpse to the Officer’s home town"]'::jsonb,0,'Correct. PSR Rule 130401 limits Government’s responsibility to preparation of the body, reasonably priced coffin or casket, transportation of the corpse to the Officer’s home town, and limited obituary publication cost. It does not provide unlimited payment for family ceremonies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-262')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best reflects the limitation in Rule 130401?','["Government’s responsibility is limited to the specific items listed in the Rule","Government pays every cost connected with the burial without limit","The deceased’s family has no role in requesting repatriation","The rule applies only to private overseas trips"]'::jsonb,0,'Correct. Under PSR Rule 130401, Government’s responsibility is expressly limited to the listed items: embalming, coffin or casket, transportation to home town, and limited obituary publication cost.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-263')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 130402, what happens when a pensionable Officer dies in Service?','["Government pays 100 per cent of the Officer’s total annual emolument to the family as burial expenses","Government pays only one month basic salary","Government pays only transport fare to the family","Government pays no burial expenses"]'::jsonb,0,'Correct. Under PSR Chapter 13, Section 4, Rule 130402, when a pensionable Officer dies in Service, Government’s responsibility is limited to payment of 100 per cent of the Officer’s total annual emolument to the family as burial expenses.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-264')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 130402 applies to which category of Officer?','["A pensionable Officer who dies in Service","A temporary visitor to an MDA","A dismissed Officer living abroad","An Officer’s private contractor"]'::jsonb,0,'Correct. Under PSR Rule 130402, the rule applies when a pensionable Officer dies in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-265')::uuid,'PSR','Chapter 1: Structure & Appointments','What percentage of the deceased pensionable Officer’s total annual emolument is payable as burial expenses under Rule 130402?','["100 per cent","25 per cent","50 per cent","10 per cent"]'::jsonb,0,'Correct. Under PSR Rule 130402, Government pays 100 per cent of the Officer’s total annual emolument to the family as burial expenses.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-266')::uuid,'PSR','Chapter 1: Structure & Appointments','To whom is the burial expense payment made under Rule 130402?','["The family of the deceased Officer","The Officer’s bank manager personally","The Staff Union only","The Officer’s driver"]'::jsonb,0,'Correct. Under PSR Rule 130402, the payment of 100 per cent of the Officer’s total annual emolument is made to the family as burial expenses.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-267')::uuid,'PSR','Chapter 1: Structure & Appointments','Which phrase correctly describes Government’s responsibility under Rule 130402?','["Limited to payment of 100 per cent of the Officer’s total annual emolument to the family as burial expenses","Unlimited payment of all burial and social ceremony expenses","Payment of only the Officer’s last monthly salary","Payment only where the Officer dies outside Nigeria"]'::jsonb,0,'Correct. Under PSR Rule 130402, Government’s responsibility is limited to payment of 100 per cent of the pensionable Officer’s total annual emolument to the family as burial expenses.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-268')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 13, Section 4 of the PSR?','["It deals with burial expenses, including repatriation of a serving Officer or authorized spouse who dies overseas and burial expense payment for a pensionable Officer who dies in Service","It deals with medical check-up approval only","It deals with disciplinary procedure for misconduct","It deals with annual leave computation only"]'::jsonb,0,'Correct. PSR Chapter 13, Section 4, Rules 130401 and 130402 cover burial expenses: repatriation of a serving Officer or duly authorized spouse who dies overseas, and payment of burial expenses for a pensionable Officer who dies in Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-269')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010101, who must strictly enforce the provisions of the Public Service Rules?','["The Staff Union only","The National Assembly only","All Ministries, Extra-Ministerial Offices and Agencies","Only private contractors"]'::jsonb,2,'Correct. Under PSR Chapter 1, Rule 010101, the provisions of the Public Service Rules shall be strictly enforced by all Ministries, Extra-Ministerial Offices and Agencies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-270')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010101, to whom do the Public Service Rules generally apply?','["Only Officers on GL. 17","Only retired Officers","Only contract staff","All Officers in the Public Service"]'::jsonb,3,'Correct. Under PSR Rule 010101, the Public Service Rules apply to all Officers in the Public Service, subject to the stated exception.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-271')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the main exception to the general application of the PSR under Rule 010101?','["Where the PSR conflicts with specific terms approved by the Federal Government and written into the contract of employment or letter of appointment","Where an Officer dislikes the rule","Where a Staff Union gives contrary instruction","Where a colleague gives informal advice"]'::jsonb,0,'Correct. Under PSR Rule 010101, the Rules apply except where they conflict with specific terms approved by the Federal Government and written into the contract of employment or letter of appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-272')::uuid,'PSR','Chapter 1: Structure & Appointments','For specific employment terms to override the PSR under Rule 010101, what must have happened?','["They must be verbally approved by a colleague","They must be approved by the Federal Government and written into the contract or letter of appointment","They must be announced on social media","They must be approved by the Officer personally"]'::jsonb,1,'Correct. PSR Rule 010101 recognizes only specific terms approved by the Federal Government and written into the contract of employment or letter of appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-273')::uuid,'PSR','Chapter 1: Structure & Appointments','Which of the following offices is specifically listed under Rule 010101?','["Private company director","Community youth leader","Staff Union treasurer","The President"]'::jsonb,3,'Correct. Under PSR Rule 010101, the President is one of the listed offices whose appointment derives from the Constitution.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-274')::uuid,'PSR','Chapter 1: Structure & Appointments','Which National Assembly offices are listed under Rule 010101?','["President of the Senate and Members, and Speaker of the House of Representatives and Members","Only committee clerks","Only legislative aides","Only State House of Assembly members"]'::jsonb,0,'Correct. Under PSR Rule 010101, the listed offices include the President of the Senate and Members, and the Speaker of the House of Representatives and Members.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-275')::uuid,'PSR','Chapter 1: Structure & Appointments','Which judicial office is listed under Rule 010101?','["Private arbitrator","Magistrate of a private tribunal","Chief Justice of Nigeria","Local court clerk"]'::jsonb,2,'Correct. Under PSR Rule 010101, the Chief Justice of Nigeria is among the listed constitutional offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-276')::uuid,'PSR','Chapter 1: Structure & Appointments','Which Federal Capital Territory judicial offices are listed under Rule 010101?','["Chief Judge and Judges of the High Court of the Federal Capital Territory, Grand Khadis and Khadis, and President and Judges of the Customary Court of Appeal","Only private mediators","Only court registrars","Only local government officials"]'::jsonb,0,'Correct. PSR Rule 010101 lists the Chief Judge and Judges of the FCT High Court, Grand Khadis and Khadis of the FCT Sharia Court of Appeal, and President and Judges of the FCT Customary Court of Appeal.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-277')::uuid,'PSR','Chapter 1: Structure & Appointments','Which executive office is listed under Rule 010101?','["Secretary to the Government of the Federation","Private company secretary","Local club secretary","Personal assistant in a private office"]'::jsonb,0,'Correct. Under PSR Rule 010101, the Secretary to the Government of the Federation is one of the listed offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-278')::uuid,'PSR','Chapter 1: Structure & Appointments','Which group is listed under Rule 010101?','["Casual workers only","Junior staff only","Private-sector consultants only","Members of the Federal Executive Council"]'::jsonb,3,'Correct. Under PSR Rule 010101, Members of the Federal Executive Council are among the listed offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-279')::uuid,'PSR','Chapter 1: Structure & Appointments','Which body is listed under Rule 010101?','["Federal Civil Service Commission","Private employment agency","Staff recreation club","Market association"]'::jsonb,0,'Correct. Under PSR Rule 010101, the Federal Civil Service Commission is one of the listed statutory bodies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-280')::uuid,'PSR','Chapter 1: Structure & Appointments','Which pair of bodies is listed under Rule 010101?','["Code of Conduct Bureau and Code of Conduct Tribunal","Private business bureau and trade tribunal","Staff club and welfare committee","Local market board and sports council"]'::jsonb,0,'Correct. Under PSR Rule 010101, both the Code of Conduct Bureau and the Code of Conduct Tribunal are listed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-281')::uuid,'PSR','Chapter 1: Structure & Appointments','Which electoral or population body is listed under Rule 010101?','["Private polling association","Independent National Electoral Commission and National Population Commission","Staff Union electoral panel","Local community development association"]'::jsonb,1,'Correct. Under PSR Rule 010101, the Independent National Electoral Commission and the National Population Commission are listed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-282')::uuid,'PSR','Chapter 1: Structure & Appointments','Which commission is listed under Rule 010101?','["Police Service Commission","Private security company","Neighbourhood watch committee","Staff cooperative society"]'::jsonb,0,'Correct. Under PSR Rule 010101, the Police Service Commission is one of the listed statutory bodies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-283')::uuid,'PSR','Chapter 1: Structure & Appointments','Which revenue-related body is listed under Rule 010101?','["Staff Revenue Club","Private Tax Forum","Revenue Mobilization, Allocation and Fiscal Commission","Union Dues Committee"]'::jsonb,2,'Correct. Under PSR Rule 010101, the Revenue Mobilization, Allocation and Fiscal Commission is among the listed statutory bodies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-284')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010102, the PSR applies only to what extent?','["To the extent that it is convenient to individual Officers","To the extent that Staff Unions approve","To the extent that private employers accept","To the extent that it is not inconsistent with the Constitution of the Federal Republic of Nigeria"]'::jsonb,3,'Correct. Under PSR Rule 010102, the Rules apply only to the extent that they are not inconsistent with the Constitution of the Federal Republic of Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-285')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 010102 links the application of the PSR to which higher legal authority?','["The Constitution of the Federal Republic of Nigeria","An Officer’s personal preference","A private employment handbook","A staff club constitution"]'::jsonb,0,'Correct. Under PSR Rule 010102, the PSR applies only where it is not inconsistent with the Constitution of the Federal Republic of Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-286')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010102, the PSR must not be inconsistent with the Constitution in relation to what?','["Only office furniture","Only transport arrangements","Conditions of Service and any other applicable law","Only staff recreation"]'::jsonb,2,'Correct. PSR Rule 010102 states that the Rules apply only where not inconsistent with the Constitution in relation to Conditions of Service and any other applicable law.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-287')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010103, what is the duty of every Officer?','["To ignore circulars unless promoted","To acquaint himself with the Public Service Rules and other extant regulations and Circulars","To rely only on verbal instructions","To study only private-sector rules"]'::jsonb,1,'Correct. Under PSR Rule 010103, every Officer has a duty to acquaint himself with the Public Service Rules and other extant regulations and Circulars.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-288')::uuid,'PSR','Chapter 1: Structure & Appointments','Which materials must every Officer acquaint himself with under Rule 010103?','["Public Service Rules, extant regulations and Circulars","Only newspaper reports","Only union notices","Only personal appointment letters"]'::jsonb,0,'Correct. PSR Rule 010103 requires every Officer to acquaint himself with the Public Service Rules and other extant regulations and Circulars.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-289')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010104, where are special meanings for particular chapters or sections quoted?','["Only at the end of the PSR","Only in the Constitution","At the beginning of such chapters or sections","Only in circulars issued after retirement"]'::jsonb,2,'Correct. Under PSR Rule 010104, special meanings of words and terms for particular chapters or sections are quoted at the beginning of such chapters or sections.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-290')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 010104 deals mainly with what?','["Annual leave entitlement","Special definitions for particular chapters and sections","Promotion examination pass mark only","Medical treatment abroad"]'::jsonb,1,'Correct. PSR Rule 010104 deals with special meanings of words and terms used for particular chapters and sections.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-291')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, general definitions apply except where what applies?','["The Officer disagrees with the definition","A Staff Union gives a different meaning","The context or special definitions for particular chapters indicate otherwise","The definition is difficult"]'::jsonb,2,'Correct. Under PSR Rule 010105, general definitions apply except where otherwise indicated by the context or special definitions for particular chapters.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-292')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, who is an Accredited Representative of the Federal Republic of Nigeria?','["A private business agent","A Staff Union officer","A retired Officer only","The Diplomatic or Consular Representative of Nigeria within the area"]'::jsonb,3,'Correct. Under PSR Rule 010105, an Accredited Representative of the Federal Republic of Nigeria means the Diplomatic or Consular Representative of Nigeria within the area.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-293')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, what is the Civil Service of the Federation?','["Service of the Federation in civil capacity as staff of the Office of the President, Vice President, Ministry and Extra-Ministerial Offices assigned responsibility for Government business","Only private-sector service","Only local government service","Only military service"]'::jsonb,0,'Correct. Under PSR Rule 010105, Civil Service of the Federation refers to service in civil capacity in the Office of the President, Vice President, Ministries and Extra-Ministerial Offices assigned responsibility for Government business.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-294')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, the Civil Service of the Federation is described as a body or organ with what feature?','["Temporary existence only","Continuity of existence","Private ownership","No legal relevance"]'::jsonb,1,'Correct. Under PSR Rule 010105, the Civil Service of the Federation is a body or organ which enjoys continuity of existence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-295')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Classified Correspondence under Rule 010105?','["Any casual office note","Correspondence written by private persons only","Correspondence graded Restricted, Confidential, Secret or Top Secret","Only circulars on leave"]'::jsonb,2,'Correct. Under PSR Rule 010105, Classified Correspondence means correspondence graded Restricted, Confidential, Secret or Top Secret.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-296')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, what is Cut-off Mark?','["The score set by the Federal Civil Service Commission to determine eligible candidates for promotion among those who pass the examination as determined by declared vacancies","A salary grade level","A leave entitlement","A pension contribution rate"]'::jsonb,0,'Correct. Under PSR Rule 010105, Cut-off Mark is the examination score set by the Federal Civil Service Commission to determine eligible candidates for promotion among those who pass the examination as determined by declared vacancies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-297')::uuid,'PSR','Chapter 1: Structure & Appointments','What is an Established Post under Rule 010105?','["A private company position","A Staff Union post","A temporary social role","A post provided for under the Personnel Emoluments sub-head of the Estimates"]'::jsonb,3,'Correct. Under PSR Rule 010105, an Established Post means a post provided for under the Personnel Emoluments sub-head of the Estimates.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-298')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, who is an Expatriate Officer?','["Staff who ranks as such for pension purposes in accordance with the Pension Reform Act 2004 as amended","Any Nigerian Officer","Any Officer on annual leave","Any Officer on GL. 06"]'::jsonb,0,'Correct. Under PSR Rule 010105, Expatriate Officer means staff who ranks as such for pension purposes in accordance with the Pension Reform Act 2004 as amended.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-299')::uuid,'PSR','Chapter 1: Structure & Appointments','What does Gazette mean under Rule 010105?','["A private newsletter","The Federal Republic of Nigeria Official Gazette","A Staff Union bulletin","An MDA notice board"]'::jsonb,1,'Correct. Under PSR Rule 010105, Gazette means the Federal Republic of Nigeria Official Gazette.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-300')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Interdiction under Rule 010105?','["Automatic promotion","Final dismissal from Service","Temporary removal of an Officer from normal duties when disciplinary proceedings for dismissal are being undertaken or about to be undertaken","Annual leave without pay"]'::jsonb,2,'Correct. Under PSR Rule 010105, Interdiction is the temporary removal of an Officer from normal duties when disciplinary proceedings for dismissal are being undertaken or about to be undertaken.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-301')::uuid,'PSR','Chapter 1: Structure & Appointments','During interdiction under Rule 010105, what salary position applies?','["The Officer is placed on half salary","The Officer earns double salary","The Officer earns no salary","The Officer receives only transport allowance"]'::jsonb,0,'Correct. Under PSR Rule 010105, an interdicted Officer is placed on half salary pending the determination of the case.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-302')::uuid,'PSR','Chapter 1: Structure & Appointments','Who is a Junior Officer under Rule 010105?','["A pensionable Officer on GL. 06 and below and their equivalent","Any Officer on GL. 17","Only a contract Officer","Only a Permanent Secretary"]'::jsonb,0,'Correct. Under PSR Rule 010105, Junior Officer means a pensionable Officer on GL. 06 and below and their equivalent.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-303')::uuid,'PSR','Chapter 1: Structure & Appointments','What are Junior Posts under Rule 010105?','["Posts attracting emoluments on Grade Level 06 and below and their equivalent in Ministries or Extra-Ministerial Offices","Posts on GL. 15 and above","Only political appointments","Only foreign mission posts"]'::jsonb,0,'Correct. Under PSR Rule 010105, Junior Posts are posts in Ministries or Extra-Ministerial Offices attracting emoluments on Grade Level 06 and below and their equivalent.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-304')::uuid,'PSR','Chapter 1: Structure & Appointments','What does Monthly-Rated mean under Rule 010105?','["Employment on monthly rates of pay","Daily paid casual work only","Annual contract without pay","Performance rating once a month"]'::jsonb,0,'Correct. Under PSR Rule 010105, Monthly-Rated means employment on monthly rates of pay.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-305')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Nigerian Home Place under Rule 010105?','["A private residence abroad","Any place selected by a Staff Union","The place in Nigeria accepted in writing by Government as the place to which a staff would naturally wish to return when spending leave in Nigeria","A temporary office address"]'::jsonb,2,'Correct. Under PSR Rule 010105, Nigerian Home Place means the place in Nigeria accepted in writing by Government as the place to which a staff would naturally wish to return when spending leave in Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-306')::uuid,'PSR','Chapter 1: Structure & Appointments','Who is a Nigerian Officer under Rule 010105?','["An Officer other than an expatriate","A foreign consultant only","A private contractor","An Officer outside the Public Service"]'::jsonb,0,'Correct. Under PSR Rule 010105, Nigerian Officer means an Officer other than an expatriate.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-307')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, what does Officer mean when used without qualification?','["Only a Permanent Secretary","Only a trainee","Staff in an established post, either on pensionable or contract term","Any private-sector worker"]'::jsonb,2,'Correct. Under PSR Rule 010105, Officer, when used without qualification, means staff in an established post either on pensionable or contract term.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-308')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Pass Mark under Rule 010105?','["The score below which a candidate is considered to have failed promotion examination","A leave entitlement","A salary increment date","A pension contribution rate"]'::jsonb,0,'Correct. Under PSR Rule 010105, Pass Mark means the score below which a candidate is considered to have failed promotion examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-309')::uuid,'PSR','Chapter 1: Structure & Appointments','What percentage is stated as the current Pass Mark under Rule 010105?','["40 percent","50 percent","55 percent","60 percent"]'::jsonb,3,'Correct. Under PSR Rule 010105, the Pass Mark currently stated is 60 percent.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-310')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010105, who is a Permanent Secretary?','["An Officer in charge of day-to-day administration in the Ministry or Extra-Ministerial Office who also doubles as Accounting Officer and Chief Policy Adviser to the Minister","Only a Staff Union officer","Only a private consultant","Only a junior post holder"]'::jsonb,0,'Correct. Under PSR Rule 010105, Permanent Secretary means the Officer in charge of day-to-day administration in the Ministry or Extra-Ministerial Office and also the Accounting Officer and Chief Policy Adviser to the Minister.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-311')::uuid,'PSR','Chapter 1: Structure & Appointments','From whom are Permanent Secretaries appointed under Rule 010105?','["Private contractors","Serving Directors in the Federal Civil Service","Only junior staff","Staff Union executives"]'::jsonb,1,'Correct. Under PSR Rule 010105, Permanent Secretaries are appointed from among serving Directors in the Federal Civil Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-312')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Public Service of the Federation under Rule 010105?','["Service of the Federation in any capacity in respect of the Government of the Federation as defined in Part 4 Section 318 of the 1999 Constitution as amended","Only private employment","Only State Government service","Only military service"]'::jsonb,0,'Correct. Under PSR Rule 010105, Public Service of the Federation means service of the Federation in any capacity in respect of the Government of the Federation as defined in Part 4 Section 318 of the 1999 Constitution as amended.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-313')::uuid,'PSR','Chapter 1: Structure & Appointments','What do the Public Service Rules consist of under Rule 010105?','["Only disciplinary punishments","Only financial vouchers","Only pension forms","Policies and guidelines defining the employment relationship between Public Servants and Government, and spelling out Conditions of Service and Human Resources Management procedures"]'::jsonb,3,'Correct. Under PSR Rule 010105, Public Service Rules consist of policies and guidelines defining the employment relationship between Public Servants and Government and spelling out Conditions of Service and Human Resources Management procedures.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-314')::uuid,'PSR','Chapter 1: Structure & Appointments','What is the Schemes of Service under Rule 010105?','["A reference document specifying duties of each post, method of entry, qualification requirements and prerequisites for advancement within and beyond cadres","A private payroll document","A medical treatment form","An annual leave roster"]'::jsonb,0,'Correct. Under PSR Rule 010105, Schemes of Service is a reference document specifying duties of each post, method of entry, qualification requirements and prerequisites for advancement within and beyond cadres.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-315')::uuid,'PSR','Chapter 1: Structure & Appointments','What are Senior Posts under Rule 010105?','["Posts attracting emoluments on GL. 03 and below","Posts attracting emoluments on Grade Level GL. 07 and above and other fixed-emolument posts of equivalent Grade Levels in Ministries or Extra-Ministerial Offices","Only contract positions","Only trainee posts"]'::jsonb,1,'Correct. Under PSR Rule 010105, Senior Posts are posts attracting emoluments on Grade Level GL. 07 and above and other posts attracting fixed emoluments of equivalent Grade Levels in Ministries or Extra-Ministerial Offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-316')::uuid,'PSR','Chapter 1: Structure & Appointments','Who is the Spouse of an Officer under Rule 010105?','["A casual office assistant","A colleague in the same MDA","A wife or husband married under the Marriage Act, Customary Law or Islamic Law","A friend nominated for benefits"]'::jsonb,2,'Correct. Under PSR Rule 010105, Spouse of an Officer means a wife or husband married under the Marriage Act, Customary Law or Islamic Law.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-317')::uuid,'PSR','Chapter 1: Structure & Appointments','What does Staff mean under Rule 010105?','["A person employed by the Federal Government","A private consultant only","A retired person only","A union volunteer only"]'::jsonb,0,'Correct. Under PSR Rule 010105, Staff means a person employed by the Federal Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-318')::uuid,'PSR','Chapter 1: Structure & Appointments','What is Suspension under Rule 010105?','["Annual leave from duty","A posting to another MDA","Promotion deferment","Removal of an Officer from performing the duties of his office where a prima facie case of a serious nature has been established"]'::jsonb,3,'Correct. Under PSR Rule 010105, Suspension means removal of an Officer from performing the duties of his office where a prima facie case of a serious nature has been established against him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-319')::uuid,'PSR','Chapter 1: Structure & Appointments','During suspension under Rule 010105, what salary position applies?','["The Officer earns no salary","The Officer earns half salary","The Officer earns double salary","The Officer receives only travel allowance"]'::jsonb,0,'Correct. Under PSR Rule 010105, during suspension, the Officer earns no salary.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-320')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement correctly distinguishes interdiction from suspension under Rule 010105?','["Interdiction and suspension both always carry full salary","Interdiction carries half salary pending determination, while suspension carries no salary","Interdiction applies only to leave, while suspension applies only to promotion","Suspension is the same as annual leave"]'::jsonb,1,'Correct. Under PSR Rule 010105, interdiction places the Officer on half salary pending determination, while suspension means removal from duties during which the Officer earns no salary.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-321')::uuid,'PSR','Chapter 1: Structure & Appointments','Who is a Trainee under Rule 010105?','["A person appointed to a training post in any grade, including a pupil","A dismissed Officer","A retired Permanent Secretary","A private business owner"]'::jsonb,0,'Correct. Under PSR Rule 010105, Trainee means a person appointed to a training post in any grade and includes pupil.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-322')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010106, how may the Federal Government amend provisions of the PSR during its lifespan?','["By informal office rumour","By Staff Union election","By private instruction only","By issuing an appropriate Circular"]'::jsonb,3,'Correct. Under PSR Rule 010106, the Federal Government may amend provisions of the PSR by issuing an appropriate Circular during the lifespan of the PSR.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-323')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 010106 deals mainly with what subject?','["Extant Circulars","Annual leave","Medical treatment","Acting appointment"]'::jsonb,0,'Correct. PSR Rule 010106 deals with extant Circulars and states that the Federal Government may amend provisions by issuing appropriate Circulars.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-324')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010107, how should masculine references to Officer and Staff be understood?','["They apply only to male Officers","They apply equally to both genders","They apply only to senior Officers","They apply only to retired Officers"]'::jsonb,1,'Correct. Under PSR Rule 010107, although the terms Officer and Staff are referred to in the masculine gender, the provisions apply equally to both genders.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-325')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 010107 mainly addresses what issue?','["Promotion","Medical examination","Gender interpretation","Retirement age"]'::jsonb,2,'Correct. PSR Rule 010107 deals with gender interpretation and confirms that provisions apply equally to both genders.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-326')::uuid,'PSR','Chapter 1: Structure & Appointments','Under Rule 010108, what must form part of the inventory of items in all offices of the Public Service?','["A copy of the Public Service Rules","A private newspaper","A personal diary","A staff club form"]'::jsonb,0,'Correct. Under PSR Rule 010108, a copy of the Public Service Rules shall form part of the inventory of items in all offices of the Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-327')::uuid,'PSR','Chapter 1: Structure & Appointments','Rule 010108 requires a copy of the PSR to be kept where?','["Only in private homes","Only with retired Officers","In all offices of the Public Service","Only at Staff Union offices"]'::jsonb,2,'Correct. Under PSR Rule 010108, a copy of the Public Service Rules shall form part of the inventory of items in all offices of the Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-328')::uuid,'PSR','Chapter 1: Structure & Appointments','Which statement best summarises Chapter 1 of the PSR?','["It deals only with annual leave","It deals only with medical treatment","It deals only with promotion examination","It introduces the application of the PSR, constitutional conformity, responsibility of Officers, definitions, extant Circulars, gender interpretation and inventory requirement"]'::jsonb,3,'Correct. PSR Chapter 1, Rules 010101 to 010108 cover application, conformity with the Constitution, responsibility of Officers, special and general definitions, extant Circulars, gender interpretation and inventory requirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-329')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021001, which Officers must participate in the Contributory Pension Scheme?','["Only contract Officers","All pensionable Officers","Only Officers on probation","Only political appointees"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 10, Rule 021001, all pensionable Officers shall participate in the Contributory Pension Scheme.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-330')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The Contributory Pension Scheme under Rule 021001 is provided for in which law?','["Public Procurement Act, 2007","Freedom of Information Act, 2011","Employees Compensation Act, 2010","Pension Reform Act, 2014"]'::jsonb,3,'Correct. Under PSR Rule 021001, participation in the Contributory Pension Scheme is as provided for in the Pension Reform Act, 2014.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-331')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021001 mainly deals with what subject?','["Payment of retirement benefit","Disciplinary procedure","Acting appointment","Burial expenses"]'::jsonb,0,'Correct. PSR Rule 021001 deals with payment of retirement benefit through participation of all pensionable Officers in the Contributory Pension Scheme.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-332')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 021001?','["Only retired Officers participate in the Contributory Pension Scheme","Only junior Officers participate in the Contributory Pension Scheme","All pensionable Officers participate in the Contributory Pension Scheme as provided by the Pension Reform Act, 2014","Contract Officers must be promoted through the Contributory Pension Scheme"]'::jsonb,2,'Correct. Under PSR Rule 021001, all pensionable Officers shall participate in the Contributory Pension Scheme as provided for in the Pension Reform Act, 2014.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-333')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021002, who forwards up-to-date record of service and required documents to PENCOM?','["The Staff Union","The retiring Officer’s family","The Federal Civil Service Commission","Departmental Pension Officers"]'::jsonb,3,'Correct. Under PSR Rule 021002, Departmental Pension Officers are required to forward up-to-date record of service and the listed documents to the Pension Commission, PENCOM.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-334')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021002 requires records and documents to be forwarded to which body?','["The Pension Commission, PENCOM","The National Assembly","The Staff Union Secretariat","The Medical Board"]'::jsonb,0,'Correct. Under PSR Rule 021002, Departmental Pension Officers forward the records and documents to the Pension Commission, PENCOM.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-335')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Why are Departmental Pension Officers required to forward the documents listed in Rule 021002?','["To delay retirement benefit processing","To replace promotion examinations","To ensure Officers receive their retirement benefits promptly","To approve annual leave"]'::jsonb,2,'Correct. Under PSR Rule 021002, the documents are forwarded to PENCOM in order to ensure that Officers receive their retirement benefits promptly.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-336')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which document is required under Rule 021002(a)?','["Original and photocopy of Gazetted publication of Letter of First Appointment","Annual leave roster only","Medical check-up report only","Staff Union membership card"]'::jsonb,0,'Correct. Under PSR Rule 021002(a), the original and photocopy of the Gazetted publication of Letter of First Appointment are required for pension payment processing.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-337')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021002(b), which document is required where applicable?','["Casual leave approval","Promotion examination result","Private business registration certificate","Original and photocopy of Transfer and Acceptance of Service"]'::jsonb,3,'Correct. Under PSR Rule 021002(b), the original and photocopy of Transfer and Acceptance of Service are required where applicable.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-338')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which proof of age is listed under Rule 021002(c)?','["Staff identity card only","Original and photocopy of Birth Certificate or sworn Declaration of Age","Annual leave certificate only","Letter from a colleague"]'::jsonb,1,'Correct. Under PSR Rule 021002(c), the original and photocopy of Birth Certificate or sworn Declaration of Age are required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-339')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021002(d), which promotion-related documents are required where applicable?','["Original and photocopy of last four Promotion Letters","Only first promotion letter","Only current posting letter","Only promotion interview invitation"]'::jsonb,0,'Correct. Under PSR Rule 021002(d), the original and photocopy of the last four Promotion Letters are required where applicable.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-340')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must the Letter of Introduction from the MDA signify under Rule 021002(e)?','["Only the Officer’s leave address","Only the Officer’s next of kin","Retirement and first appointment dates, grade level and step as at the years of last four promotions, and current grade level and step","Only the Officer’s union membership"]'::jsonb,2,'Correct. Under PSR Rule 021002(e), the Letter of Introduction from the MDA must signify retirement and first appointment dates, grade level and step as at the years of the last four promotions, and the current grade level and step.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-341')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which identity document is required under Rule 021002(f)?','["Official vehicle allocation letter","Medical appointment card","Leave roster","Original and photocopy of staff identity card"]'::jsonb,3,'Correct. Under PSR Rule 021002(f), the original and photocopy of the staff identity card are required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-342')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which service record is required under Rule 021002(g)?','["Authenticated past Record of Service","Private school testimonial only","Family history record only","Annual leave address"]'::jsonb,0,'Correct. Under PSR Rule 021002(g), an authenticated past Record of Service is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-343')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021002(h), which payroll-related evidence is required?','["Evidence of union dues","Evidence of IPPIS registration and current pay slip","Evidence of medical treatment abroad","Evidence of casual leave"]'::jsonb,1,'Correct. Under PSR Rule 021002(h), evidence of IPPIS registration and current pay slip is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-344')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which document is required for voluntary retirees only under Rule 021002(i)?','["Original and photocopy of Acceptance of Voluntary Retirement Letter","Original and photocopy of marriage certificate","Original and photocopy of annual leave roster","Original and photocopy of disciplinary query"]'::jsonb,0,'Correct. Under PSR Rule 021002(i), the original and photocopy of Acceptance of Voluntary Retirement Letter are required for voluntary retirees only.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-345')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021002(j), evidence of registration with Pension Fund Administrators must indicate what?','["Annual Leave Number","Staff Union Code","Medical Board Number","RSA Pension Identification Number, PIN"]'::jsonb,3,'Correct. Under PSR Rule 021002(j), evidence of registration with Pension Fund Administrators must indicate the RSA Pension Identification Number, PIN.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-346')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which national identity evidence is required under Rule 021002(k)?','["Evidence of National Identification Number, NIN","Evidence of foreign visa","Evidence of Staff Union election","Evidence of medical referral"]'::jsonb,0,'Correct. Under PSR Rule 021002(k), evidence of National Identification Number, NIN, is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-347')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which banking identity evidence is required under Rule 021002(l)?','["Evidence of salary advance","Evidence of loan request","Evidence of Bank Verification Number, BVN","Evidence of transport grant"]'::jsonb,2,'Correct. Under PSR Rule 021002(l), evidence of Bank Verification Number, BVN, is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-348')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which attestation is required under Rule 021002(m)?','["Staff Union Chairman’s Attestation","Pension Desk Officer’s Attestation","Medical Officer’s Attestation","Private Employer’s Attestation"]'::jsonb,1,'Correct. Under PSR Rule 021002(m), Pension Desk Officer’s Attestation is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-349')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which photograph requirement is listed under Rule 021002(n)?','["One recent coloured passport","Two black-and-white group photographs","One family photograph","One office photograph"]'::jsonb,0,'Correct. Under PSR Rule 021002(n), one recent coloured passport is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-350')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which document is required for deceased Officers under Rule 021002(o)?','["Annual leave approval","Medical check-up certificate","Staff Union clearance","Stamped Death Certificate"]'::jsonb,3,'Correct. Under PSR Rule 021002(o), a stamped Death Certificate is required for deceased Officers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-351')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021002(p), the Certificate of Non-indebtedness relates to which obligations?','["Federal Government Staff Housing Loans Board and any MDA Staff Multipurpose Cooperative Society","Only annual leave allowance","Only promotion examination fees","Only private family debts"]'::jsonb,0,'Correct. Under PSR Rule 021002(p), the Certificate of Non-indebtedness relates to the Federal Government Staff Housing Loans Board and any MDA Staff Multipurpose Cooperative Society.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-352')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who issues the Certificate of Non-indebtedness mentioned in Rule 021002(p)?','["The Officer’s family","The Office of the Head of the Civil Service of the Federation, OHCSF","The Staff Union","The private bank"]'::jsonb,1,'Correct. Under PSR Rule 021002(p), the Certificate of Non-indebtedness is to be issued by the Office of the Head of the Civil Service of the Federation, OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-353')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which option correctly lists examples of documents required for pension payment under Rule 021002?','["Gazetted publication of Letter of First Appointment, proof of age, last four Promotion Letters where applicable, IPPIS evidence, RSA PIN, NIN and BVN","Only annual leave forms and union dues receipt","Only medical check-up report and posting letter","Only certificate of service and casual leave form"]'::jsonb,0,'Correct. PSR Rule 021002 lists several documents for pension payment processing, including first appointment gazette, proof of age, promotion letters where applicable, IPPIS evidence, RSA PIN, NIN and BVN.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-354')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021003, are Departmental files and other documents not expressly mentioned in Rule 021002 still a condition for processing retirement benefits?','["Yes, they remain compulsory in every case","Yes, but only after five years","No, they shall no longer be a condition","No, because retirement benefits are never processed"]'::jsonb,2,'Correct. Under PSR Rule 021003, forwarding Departmental files and other documents not expressly mentioned in Rule 021002 shall no longer be a condition for processing retirement benefits.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-355')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021003, retirement benefits shall be paid to the Officer within what period?','["Within one month of retirement","Within one year of retirement","Within five years of retirement","Only after the Officer requests it"]'::jsonb,0,'Correct. Under PSR Rule 021003, retirement benefits shall be paid to the Officer within one month of retirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-356')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 021003?','["All Departmental files must always be forwarded before retirement benefits can be processed","Retirement benefits should be paid only after ten years","Documents not mentioned in Rule 021002 are no longer a condition, and retirement benefits are to be paid within one month of retirement","Only Staff Union documents are required for retirement benefits"]'::jsonb,2,'Correct. Under PSR Rule 021003, Departmental files and other documents not expressly mentioned in Rule 021002 are no longer a condition for processing retirement benefits, and benefits shall be paid within one month of retirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-357')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021003 mainly addresses what issue?','["Processing of retirement benefits","Recruitment examinations","Posting of Officers","Acting appointment"]'::jsonb,0,'Correct. PSR Rule 021003 deals with processing of retirement benefits and removes unlisted Departmental files or documents as a condition for processing.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-358')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021004, Officers who exit the Service shall access what contribution?','["Annual leave contribution","Staff Union contribution","National Housing Fund, NHF, contribution","Medical insurance contribution"]'::jsonb,2,'Correct. Under PSR Rule 021004, Officers who exit the Service shall access their National Housing Fund, NHF, contributions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-359')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Within what period should Officers who exit the Service access their NHF contributions under Rule 021004?','["Within one year of retirement","Within one month of retirement","Within five years of retirement","Only after receiving promotion"]'::jsonb,1,'Correct. Under PSR Rule 021004, Officers who exit the Service shall access their National Housing Fund contributions within one month of retirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-360')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021004 is specifically concerned with access to which fund?','["The National Housing Fund","The Staff Union Fund","The Medical Treatment Fund","The Training Fund"]'::jsonb,0,'Correct. PSR Rule 021004 specifically provides for accessing contributions to the National Housing Fund, NHF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-361')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 021004?','["Officers who exit the Service shall access their NHF contributions within one month of retirement","Officers must wait ten years to access NHF contributions","NHF contributions are forfeited after retirement","NHF contributions are replaced by annual leave allowance"]'::jsonb,0,'Correct. Under PSR Rule 021004, Officers who exit the Service shall access their National Housing Fund contributions within one month of retirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-362')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 10 of the PSR?','["It deals only with acting appointment","It regulates only promotion examinations","It deals only with certificate of service","It covers mandatory participation in the Contributory Pension Scheme, requirements for pension payment, processing of retirement benefits and access to NHF contributions"]'::jsonb,3,'Correct. PSR Chapter 2, Section 10, Rules 021001 to 021004 cover mandatory contribution to pension scheme, pension payment requirements, processing of retirement benefits and access to National Housing Fund contributions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-363')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021101, which Officers shall be issued a Certificate of Service on leaving the Service?','["Only Officers on pensionable appointments","Only Officers on GL. 07 and above","All Officers, including those of non-pensionable appointments","Only Officers who retire as Permanent Secretaries"]'::jsonb,2,'Correct. Under PSR Chapter 2, Section 11, Rule 021101, all Officers, including those of non-pensionable appointments, shall be issued a Certificate of Service on leaving the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-364')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When is a Certificate of Service issued under Rule 021101?','["On leaving the Service","Only at first appointment","Only during promotion interview","Only when an Officer is transferred"]'::jsonb,0,'Correct. Under PSR Rule 021101, the Certificate of Service is issued to an Officer on leaving the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-365')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What happens to the Official Identity Card of an Officer leaving the Service under Rule 021101?','["It is retained permanently by the Officer","It is retrieved and replaced with a retiree Identity Card","It is converted into a promotion card","It is sent to the Staff Union"]'::jsonb,1,'Correct. Under PSR Rule 021101, the Official Identity Card shall be retrieved and replaced with a retiree Identity Card.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-366')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who issues the retiree Identity Card mentioned in Rule 021101?','["The Federal Civil Service Commission","The Staff Union","The Office of the Head of the Civil Service of the Federation","The Officer’s former Department"]'::jsonb,2,'Correct. Under PSR Rule 021101, the retiree Identity Card is issued by the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-367')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 021101?','["Only pensionable Officers receive Certificate of Service","All Officers leaving the Service receive Certificate of Service, and their Official Identity Card is retrieved and replaced with retiree Identity Card","Only Officers who resign receive Certificate of Service","The Official Identity Card is never retrieved"]'::jsonb,1,'Correct. PSR Rule 021101 provides that all Officers, including non-pensionable appointees, shall receive Certificate of Service on leaving the Service, while the Official Identity Card is retrieved and replaced with a retiree Identity Card issued by OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-368')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Does Rule 021101 exclude non-pensionable appointees from receiving Certificate of Service?','["Yes, non-pensionable appointees are excluded","No, non-pensionable appointees are expressly included","Yes, only confirmed pensionable Officers are included","Yes, only Officers on GL. 17 are included"]'::jsonb,1,'Correct. Under PSR Rule 021101, all Officers, including those of non-pensionable appointments, shall be issued Certificate of Service on leaving the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-369')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021102, Certificate of Service for Officers holding senior posts on GL. 07 and above requires whose countersignature?','["The Permanent Secretary of the retiring Officer and the Permanent Secretary, Federal Civil Service Commission","The Staff Union Chairman and the Officer’s Director","The Accountant-General and Auditor-General","The Officer’s supervisor only"]'::jsonb,0,'Correct. Under PSR Rule 021102, Certificate of Service for Officers on GL. 07 and above requires the countersignature of the Permanent Secretary of the retiring Officer and the Permanent Secretary, Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-370')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For Certificate of Service purposes, Officers on GL. 07 and above are treated as what category?','["Junior post holders","Senior post holders","Contractors only","Non-staff visitors"]'::jsonb,1,'Correct. Under PSR Rule 021102, Officers holding senior posts are those on GL. 07 and above for the purpose of Certificate of Service countersignature.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-371')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021102, Certificate of Service for Officers holding junior posts on GL. 06 and below requires countersignature by whom?','["The Officer’s family head and Staff Union Chairman","The Permanent Secretary of the retiring Officer and the Permanent Secretary, Career Management Office","The Accountant-General and Minister of Finance","The Director of Finance only"]'::jsonb,1,'Correct. Under PSR Rule 021102, Certificate of Service for Officers on GL. 06 and below requires the countersignature of the Permanent Secretary of the retiring Officer and the Permanent Secretary, Career Management Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-372')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which office countersigns Certificate of Service for senior post holders together with the Permanent Secretary of the retiring Officer?','["Career Management Office","Federal Civil Service Commission","National Pension Commission","Staff Union Secretariat"]'::jsonb,1,'Correct. Under PSR Rule 021102, the Permanent Secretary, Federal Civil Service Commission countersigns Certificates of Service for Officers on GL. 07 and above together with the Permanent Secretary of the retiring Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-373')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which office countersigns Certificate of Service for junior post holders together with the Permanent Secretary of the retiring Officer?','["Career Management Office","Federal Civil Service Commission","National Pension Commission","Office of the Accountant-General"]'::jsonb,0,'Correct. Under PSR Rule 021102, the Permanent Secretary, Career Management Office countersigns Certificates of Service for Officers on GL. 06 and below together with the Permanent Secretary of the retiring Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-374')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021102, Officers holding junior posts are those on which grade levels?','["GL. 15 to GL. 17 only","GL. 07 and above","GL. 06 and below","Permanent Secretary level only"]'::jsonb,2,'Correct. Under PSR Rule 021102, Certificates of Service for Officers holding junior posts apply to Officers on GL. 06 and below.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-375')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly distinguishes the countersignature authority under Rule 021102?','["GL. 07 and above require FCSC countersignature, while GL. 06 and below require Career Management Office countersignature","GL. 07 and above require Staff Union countersignature, while GL. 06 and below require family countersignature","All Officers require only the Accountant-General’s countersignature","No Certificate of Service requires countersignature"]'::jsonb,0,'Correct. Under PSR Rule 021102, senior post holders on GL. 07 and above require countersignature by the Permanent Secretary, Federal Civil Service Commission, while junior post holders on GL. 06 and below require countersignature by the Permanent Secretary, Career Management Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-376')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the main purpose of issuing a Certificate of Service under Rule 021103?','["To serve as a reference covering the holder’s Public Service when seeking other employment","To serve as a promotion letter","To replace the Officer’s pension documents","To act as a medical fitness certificate"]'::jsonb,0,'Correct. Under PSR Rule 021103, the main purpose of issuing a Certificate of Service is that it may be used as a reference covering the holder’s Public Service when seeking other employment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-377')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When seeking other employment, what document may an ex-Officer use as reference under Rule 021103?','["Certificate of Service","Annual leave roster","Medical treatment form","Posting instruction"]'::jsonb,0,'Correct. Under PSR Rule 021103, the Certificate of Service may be used as a reference when the holder is seeking other employment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-378')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The Certificate of Service under Rule 021103 covers what aspect of the holder’s career?','["The holder’s Public Service","The holder’s private business","The holder’s family record","The holder’s political activities"]'::jsonb,0,'Correct. Under PSR Rule 021103, the Certificate of Service is a reference covering the holder’s Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-379')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects the objective of Certificate of Service under Rule 021103?','["It is issued mainly to support future employment reference based on the holder’s Public Service","It is issued mainly as a disciplinary query","It is issued mainly as a leave approval letter","It is issued mainly as a pension payment voucher"]'::jsonb,0,'Correct. Under PSR Rule 021103, the Certificate of Service may be used as a reference covering the holder’s Public Service when seeking other employment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-380')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021104, in how many copies shall the Certificate of Service be rendered?','["One copy","Two copies","Triplicate","Five copies"]'::jsonb,2,'Correct. Under PSR Rule 021104, the Certificate of Service shall be rendered in triplicate on the approved forms.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-381')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form is used for Certificate of Service for Officers on GL. 07 and above?','["Form Gen. 58","Form Gen. 58A","Form L.10","Form FC. 2"]'::jsonb,0,'Correct. Under PSR Rule 021104, Certificate of Service for Officers on GL. 07 and above is rendered on Form Gen. 58.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-382')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form is used for Certificate of Service for Officers on GL. 06 and below?','["Form Gen. 60","Form L.10","Form Gen. 58A","Form FC. 2"]'::jsonb,2,'Correct. Under PSR Rule 021104, Certificate of Service for Officers on GL. 06 and below is rendered on Form Gen. 58A.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-383')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The approved Certificate of Service forms under Rule 021104 are used for which categories of Officers?','["Only Permanent Secretaries","Officers on GL. 07 and above, and Officers on GL. 06 and below","Only Officers on contract appointment","Only Officers on probation"]'::jsonb,1,'Correct. Under PSR Rule 021104, the approved forms apply to Officers on GL. 07 and above and Officers on GL. 06 and below.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-384')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly matches the approved forms under Rule 021104?','["GL. 07 and above use Form Gen. 58, while GL. 06 and below use Form Gen. 58A","GL. 07 and above use Form L.10, while GL. 06 and below use Form FC. 2","All Officers use only Form Gen. 60","Only retired Permanent Secretaries use Certificate of Service forms"]'::jsonb,0,'Correct. Under PSR Rule 021104, Certificate of Service is rendered in triplicate on Form Gen. 58 for Officers on GL. 07 and above, and Form Gen. 58A for Officers on GL. 06 and below.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-385')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021105, when should action to complete the issue of Certificate of Service be taken?','["In time for the Certificate to be handed to the recipient before he proceeds on leave prior to leaving the Service","Only after the Officer has left the Service for five years","Only after pension is fully paid","Only during the next promotion exercise"]'::jsonb,0,'Correct. Under PSR Rule 021105, action to complete the issue of Certificate of Service should be taken in time for the Certificate to be handed to the recipient before he proceeds on leave prior to leaving the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-386')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What should not form part of the Certificate of Service under Rule 021105?','["Adverse comment","The Officer’s name","The approved form","The service reference"]'::jsonb,0,'Correct. Under PSR Rule 021105, adverse comment should not form part of the Certificate of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-387')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If there is an issue other than the Certificate of Service, how should it be handled under Rule 021105?','["It should be inserted as adverse comment in the Certificate","It should be treated differently from the Certificate of Service","It should be ignored forever","It should be published on the Certificate"]'::jsonb,1,'Correct. Under PSR Rule 021105, any other issue other than the Certificate of Service ought to be treated differently.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-388')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Before an Officer leaves the Service, what must have happened if there is another issue requiring punishment under Rule 021105?','["The Officer must have been punished following due process","The Officer must automatically be denied Certificate of Service","The Officer’s Certificate must contain adverse comment","The Officer’s retiree identity card must be withheld permanently"]'::jsonb,0,'Correct. Under PSR Rule 021105, any other issue must be treated separately, and the Officer must have been punished before leaving the Service, following due process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-389')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects the timing rule in Rule 021105?','["The Certificate of Service should be completed before the recipient proceeds on leave prior to leaving the Service","The Certificate of Service should only be issued ten years after retirement","The Certificate of Service should be completed only after court action","The Certificate of Service should be issued only after the Officer requests it"]'::jsonb,0,'Correct. Under PSR Rule 021105, action should be taken in time for the Certificate to be handed to the recipient before he proceeds on leave prior to leaving the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-390')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects the treatment of adverse comments under Rule 021105?','["Adverse comments may freely be inserted in the Certificate of Service","Adverse comments should not form part of Certificate of Service","Adverse comments must replace the approved form","Adverse comments are required for all retirees"]'::jsonb,1,'Correct. Under PSR Rule 021105, adverse comment should not form part of the Certificate of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-391')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 11 of the PSR?','["It regulates Certificate of Service, including who receives it, retiree identity card replacement, countersignature authority, objective, approved forms, timing, and exclusion of adverse comments","It deals only with pension contribution","It deals only with acting appointment","It deals only with promotion examination"]'::jsonb,0,'Correct. PSR Chapter 2, Section 11, Rules 021101 to 021105 cover Certificate of Service, including application to all Officers leaving Service, retrieval and replacement of Official Identity Card, countersignature authority, objective, approved forms, timing of issuance, and exclusion of adverse comments.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-392')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021201, the term of engagement of a person on non-pensionable appointment is expressed as what?','["A permanent term until retirement","“X” years commencing from the date of assumption of duty","A probationary period of two years only","A term ending on the date of interview"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 12, Rule 021201, the term of engagement of the person engaged is “X” years commencing from the date of assumption of duty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-393')::uuid,'PSR','Chapter 2: Appointments & Career Progression','From what date does the term of engagement commence under Rule 021201?','["The date of first promotion","The date of medical examination","The date of publication in a newspaper","The date of assumption of duty"]'::jsonb,3,'Correct. Under PSR Rule 021201, the term of engagement commences from the date of assumption of duty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-394')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021201 deals mainly with which issue?','["Term of engagement","Dismissal for misconduct","Severance allowance","Travelling allowance"]'::jsonb,0,'Correct. PSR Rule 021201 deals with the term of engagement for non-pensionable appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-395')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021202, when is the term of engagement deemed completed?','["On the date of appointment letter","When any leave granted in respect of the tour of service expires","On the date of first salary payment","Immediately after three months of service"]'::jsonb,1,'Correct. Under PSR Rule 021202, the term of engagement is deemed completed on the date any leave granted in respect of that tour of service expires.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-396')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which leave is relevant to completion of term under Rule 021202?','["Leave granted in respect of the tour of service","Casual leave taken before appointment","Leave taken by another Officer","Leave refused by Government"]'::jsonb,0,'Correct. Under PSR Rule 021202, completion of the term is tied to the expiry of leave granted in respect of the tour of service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-397')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 021202?','["The term ends only when the Officer resigns","The term is completed when leave granted for the tour of service expires","The term ends only after retirement at age 60","The term ends when the Staff Union approves it"]'::jsonb,1,'Correct. Under PSR Rule 021202, the term of engagement is deemed completed when any leave granted in respect of the tour of service expires.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-398')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021203, the duties of the person engaged include what?','["Only duties personally chosen by the person engaged","Only political activities","The usual duties of the office and any other duties Government may call upon him to perform","Only duties outside Government service"]'::jsonb,2,'Correct. Under PSR Rule 021203, the duties include the usual duties of the office to which the person is appointed and any other duties Government may call upon him to perform.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-399')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who may call upon the person engaged to perform other duties under Rule 021203?','["The Staff Union","The Government","The person’s family","A private employer"]'::jsonb,1,'Correct. Under PSR Rule 021203, Government may call upon the person engaged to perform other duties.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-400')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021203 is mainly concerned with what?','["Duties of the person engaged","Severance allowance","Medical fitness certificate","Termination notice"]'::jsonb,0,'Correct. PSR Rule 021203 provides for the duties of the person engaged under a non-pensionable appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-401')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021204, may the person engaged be directly or indirectly engaged in another service or business?','["Yes, without restriction","Yes, if the business is profitable","No, he shall not be engaged in or concerned with any other service or business","Yes, if he informs a colleague"]'::jsonb,2,'Correct. Under PSR Rule 021204, the person engaged shall not, directly or indirectly, be engaged in or concerned with any other service or business whatsoever.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-402')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 021204 say about receiving commission or profits?','["The person engaged may receive commission freely","The person engaged may receive profits from any business","The person engaged may receive commission only from suppliers","The person engaged shall not receive commission or profits of any kind"]'::jsonb,3,'Correct. Under PSR Rule 021204, the person engaged shall not receive commission or profits of any kind.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-403')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021204, to what must the person engaged devote his whole time and attention?','["Private business","The Service of the Government","Staff Union elections","Personal commercial ventures"]'::jsonb,1,'Correct. Under PSR Rule 021204, the person engaged must devote the whole of his time and attention to the Service of the Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-404')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which rules must the person engaged conform to under Rule 021204?','["Public Service Rules of the Government","Private company rules only","Family rules only","Staff club rules"]'::jsonb,0,'Correct. Under PSR Rule 021204, the person engaged shall conform to the Public Service Rules of the Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-405')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Rule 021204?','["The person engaged may run any business while in Government service","The person engaged must avoid other service or business, must not receive commissions or profits, must devote full attention to Government service and must conform to the PSR","The person engaged is exempt from the PSR","The person engaged may divide official time with private employment"]'::jsonb,1,'Correct. PSR Rule 021204 requires the person engaged to avoid other service or business, avoid commissions or profits, devote full time to Government service and conform to the Public Service Rules.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-406')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021205, the term “emolument” includes what where payable under the agreement?','["Contract addition","Severance allowance only","Medical certificate fee","Transport refund"]'::jsonb,0,'Correct. Under PSR Rule 021205, “emolument” includes contract addition where this is payable under the agreement, except in Rule 021206.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-407')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021205 states that the definition of “emolument” applies except in which rule?','["Rule 021201","Rule 021206","Rule 021212","Rule 021214"]'::jsonb,1,'Correct. Under PSR Rule 021205, the term “emolument” includes contract addition where payable, except in Rule 021206.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-408')::uuid,'PSR','Chapter 2: Appointments & Career Progression','From what date are increments of emoluments calculated under Rule 021205?','["From the first day of the month in which the person engaged takes up appointment","From the last day of the leave year","From the date of retirement","From the date of dismissal"]'::jsonb,0,'Correct. Under PSR Rule 021205(i), increments of emoluments, if any, are calculated from the first day of the month in which the person engaged takes up appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-409')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021205, increments of emoluments shall not be granted unless what has been satisfactory?','["Private business income","Efficiency, conduct and diligence","Annual leave address","Staff Union membership"]'::jsonb,1,'Correct. Under PSR Rule 021205(ii), increments shall not be granted unless the efficiency, conduct and diligence of the person engaged have been satisfactory during the preceding year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-410')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The satisfactory efficiency, conduct and diligence required for increments under Rule 021205 must relate to what period?','["The year preceding the engagement","The first week of appointment","The period after dismissal","Only the retirement month"]'::jsonb,0,'Correct. Under PSR Rule 021205(ii), increments depend on satisfactory efficiency, conduct and diligence during the year preceding the engagement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-411')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021205, an increment shall not be withheld except on whose decision or recommendation?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Staff Union Chairman","The person engaged personally","A private employer"]'::jsonb,0,'Correct. Under PSR Rule 021205(ii), an increment shall not be withheld except on the decision or recommendation of the Permanent Secretary or Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-412')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021206, when travelling on duty away from duty post, the person engaged is subject to what?','["Only his personal travel plan","Such regulations on transport and travelling allowances as Government may decide","Private travel agency rules only","Unlimited travelling allowance"]'::jsonb,1,'Correct. Under PSR Rule 021206, when travelling on duty away from duty post, the person engaged is subject to Government regulations on transport and travelling allowances.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-413')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021206 deals mainly with which subject?','["Travelling allowances","Dismissal","Severance allowance","Further employment"]'::jsonb,0,'Correct. PSR Rule 021206 deals with transport and travelling allowance provisions when the person engaged travels on duty away from duty post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-414')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who decides the applicable regulations on transport and travelling allowances under Rule 021206?','["The Government","The Staff Union","The person engaged alone","The family of the person engaged"]'::jsonb,0,'Correct. Under PSR Rule 021206, the applicable regulations are those the Government may decide.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-415')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021207, Government pays salary due where the person engaged resigns because of what?','["Ill-health not caused by his own negligence","Private business loss","Refusal to obey orders","Desire to relocate without approval"]'::jsonb,0,'Correct. Under PSR Rule 021207, where the person engaged is compelled by ill-health not caused by his own negligence to resign, Government pays salary due up to the relevant date.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-416')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021207, who may certify that the person engaged is incapable of rendering further efficient service?','["A duly qualified Healthcare Provider employed by the Government","A private friend","A Staff Union official","A market association chairman"]'::jsonb,0,'Correct. Under PSR Rule 021207, incapacity by infirmity of mind or body must be certified by a duly qualified Healthcare Provider employed by the Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-417')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The incapacity mentioned in Rule 021207 may arise from what?','["Infirmity of mind or body","Failure to attend a social event","Refusal to take annual leave","Delay in promotion"]'::jsonb,0,'Correct. Under PSR Rule 021207, the relevant incapacity may arise from infirmity of mind or body rendering further efficient service impossible.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-418')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where Rule 021207 applies, salary is payable up to which date?','["The date of such resignation or the date the certificate is issued","The date of first appointment only","The date of interview","The date of union election"]'::jsonb,0,'Correct. Under PSR Rule 021207, Government pays such salary as may be due up to the date of resignation or the date on which the certificate was issued.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-419')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which condition would prevent reliance on ill-health under Rule 021207?','["Ill-health caused by the person’s own negligence","Ill-health certified by Government Healthcare Provider","Infirmity of mind or body","Compelled resignation on health grounds"]'::jsonb,0,'Correct. Under PSR Rule 021207, the ill-health must not be caused by the person engaged through his own negligence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-420')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021208, what is conclusive evidence on whether resignation was compelled by ill-health?','["A certificate of Medical Fitness duly signed by a qualified Government Healthcare Provider","A private letter from a colleague","A newspaper report","A Staff Union note"]'::jsonb,0,'Correct. Under PSR Rule 021208, a certificate of Medical Fitness duly signed by a qualified Healthcare Provider employed by the Government is conclusive evidence on whether resignation was compelled by ill-health.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-421')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who must sign the certificate of Medical Fitness under Rule 021208?','["A qualified Healthcare Provider employed by the Government","The person engaged personally","A private business partner","The Staff Union Chairman"]'::jsonb,0,'Correct. Under PSR Rule 021208, the certificate must be signed by a qualified Healthcare Provider employed by the Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-422')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021208 is used to determine what question?','["Whether the person engaged was compelled to resign by reason of ill-health","Whether the person engaged is due for promotion","Whether the person engaged should receive transport allowance","Whether the person engaged may join another business"]'::jsonb,0,'Correct. Under PSR Rule 021208, the certificate is conclusive evidence on whether the person engaged was compelled to resign by reason of ill-health.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-423')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021209, Government may dismiss the person engaged if he does what?','["Neglects or refuses to perform duties or comply with any order","Takes approved leave","Receives salary due","Completes his tour satisfactorily"]'::jsonb,0,'Correct. Under PSR Rule 021209, Government may dismiss the person engaged if he neglects or refuses to perform duties or comply with any order.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-424')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which exception is recognized under Rule 021209 where the person is unable to perform duties?','["Ill-health not caused by his own negligence","Private business pressure","Family request","Desire for promotion"]'::jsonb,0,'Correct. Under PSR Rule 021209, inability to perform duties may be excused only where it is due to ill-health not caused by the person’s own negligence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-425')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021209, disclosure of Government affairs to whom may lead to dismissal?','["An unauthorized person","A Permanent Secretary","An authorized Government officer","A duly authorized superior"]'::jsonb,0,'Correct. Under PSR Rule 021209, disclosure of information in respect of Government affairs to any unauthorized person may lead to dismissal.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-426')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021209, what happens to rights and privileges accrued under the agreement upon dismissal?','["They cease","They are doubled","They are converted into pension","They are transferred to the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 021209, upon dismissal, all rights and privileges accrued to the person engaged by the agreement shall cease.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-427')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Rule 021209?','["Government may dismiss the person engaged for neglect, refusal of duty, failure to comply with orders, unauthorized disclosure or misconduct, and accrued rights and privileges cease","Government cannot dismiss a non-pensionable appointee","Government may dismiss only after retirement","Accrued rights continue after dismissal"]'::jsonb,0,'Correct. PSR Rule 021209 allows dismissal for neglect, refusal of duty, failure to comply with orders, unauthorized disclosure or misconduct, and provides that accrued rights and privileges under the agreement cease upon dismissal.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-428')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021210, Government may terminate the engagement by giving what notice?','["Three months’ notice in writing","One week’s verbal notice","One year’s public notice","Six months’ notice by newspaper"]'::jsonb,0,'Correct. Under PSR Rule 021210(i), Government may terminate the engagement by giving three months’ notice in writing.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-429')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Instead of giving three months’ notice, what may Government pay under Rule 021210?','["One month’s salary in lieu of notice","Six months’ salary as bonus","Severance allowance only","Transport allowance only"]'::jsonb,0,'Correct. Under PSR Rule 021210(i), Government may terminate by giving three months’ notice in writing or by paying one month’s salary in lieu of notice.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-430')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After what period of service may the person engaged terminate his engagement under Rule 021210?','["After expiration of three months of service","After one week of service","Only after thirty-five years","Only after becoming pensionable"]'::jsonb,0,'Correct. Under PSR Rule 021210(ii), the person engaged may terminate his engagement at any time after the expiration of three months of service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-431')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How may the person engaged terminate his engagement after three months of service under Rule 021210?','["By giving Government three months’ notice in writing or paying Government one month’s salary in lieu of notice","By sending a verbal message to a colleague","By refusing duty without notice","By applying for promotion"]'::jsonb,0,'Correct. Under PSR Rule 021210(ii), the person engaged may terminate by giving Government three months’ notice in writing or paying Government one month’s salary in lieu of notice.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-432')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects termination under Rule 021210?','["Both Government and the person engaged have notice or salary-in-lieu options under the rule","Only the Staff Union may terminate the engagement","The person engaged can terminate only after retirement","Government must always give one year’s notice"]'::jsonb,0,'Correct. Under PSR Rule 021210, Government may terminate by three months’ written notice or one month’s salary in lieu, and the person engaged may also terminate after three months’ service by three months’ written notice or one month’s salary in lieu.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-433')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021211, pecuniary damage may arise from disregarding or failing to comply with what?','["Any order, standing order or departmental instruction","Private family advice","Staff club rules","Personal preference"]'::jsonb,0,'Correct. Under PSR Rule 021211, pecuniary damage may arise from disregarding or failing to comply with any order, standing order or departmental instruction, or from neglect of duty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-434')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021211, pecuniary damage may also arise from what on the part of the person engaged?','["Neglect of duty","Completion of tour of service","Satisfactory conduct","Approved leave"]'::jsonb,0,'Correct. Under PSR Rule 021211, pecuniary damage arising from neglect of duty may make the person engaged liable to salary deduction.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-435')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What may be deducted under Rule 021211 to make good pecuniary damage?','["Salary of the person engaged","Annual leave balance","Promotion score","Medical certificate"]'::jsonb,0,'Correct. Under PSR Rule 021211, the person engaged may be liable to a deduction from salary to make good the damage or part of it.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-436')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who fixes the amount to be deducted for pecuniary damage under Rule 021211?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Staff Union Chairman","The person engaged alone","The private employer"]'::jsonb,0,'Correct. Under PSR Rule 021211, the amount to be deducted is fixed by the Permanent Secretary or Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-437')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021212, when must the person engaged give written notice if he desires to remain in Government employment?','["Four months before the date of expiration of the agreement","One week after expiration","Only after dismissal","At any time after retirement"]'::jsonb,0,'Correct. Under PSR Rule 021212, four months before the expiration of the agreement, the person engaged must give written notice to Government stating his desire to remain in employment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-438')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The written notice under Rule 021212 states what?','["The desire to remain in Government employment","The desire to receive dismissal","The desire to avoid the PSR","The desire to disclose Government information"]'::jsonb,0,'Correct. Under PSR Rule 021212, the written notice must state the person’s desire to remain in Government employment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-439')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After receiving the notice under Rule 021212, what does Government decide?','["Whether it will offer further employment","Whether to grant maternity leave only","Whether to abolish the PSR","Whether to promote the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 021212, Government decides whether it will offer the person engaged further employment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-440')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If Government decides in favour of further employment under Rule 021212, re-engagement shall be on what basis?','["Such terms and for such period as may be mutually agreed","Automatic permanent pensionable appointment","Unlimited tenure without terms","The same terms without negotiation"]'::jsonb,0,'Correct. Under PSR Rule 021212, if Government decides in favour, re-engagement is on such terms and for such period as may be mutually agreed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-441')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021213, when is the person engaged eligible for severance allowance?','["On satisfactory completion of a tour of service","On dismissal for misconduct","On refusal to perform duties","On unauthorized disclosure of Government information"]'::jsonb,0,'Correct. Under PSR Rule 021213, the person engaged is eligible for severance allowance on satisfactory completion of a tour of service, subject to the stated conditions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-442')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the severance allowance rate under Rule 021213?','["15 percent of basic salary","50 percent of total emoluments","One month’s transport allowance","100 percent of annual salary"]'::jsonb,0,'Correct. Under PSR Rule 021213, severance allowance is payable at the rate of 15 percent of basic salary.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-443')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021213, severance allowance is not payable if the engagement is terminated under which rule?','["Rule 021210","Rule 021201","Rule 021208","Rule 021214"]'::jsonb,0,'Correct. Under PSR Rule 021213, severance allowance is payable only if the engagement is not terminated as under Rule 021210.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-444')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which further condition affects eligibility for severance allowance under Rule 021213?','["The person engaged must not be in receipt of, or eligible for, any other retiring benefits","The person engaged must be a Staff Union officer","The person engaged must have refused all duties","The person engaged must have disclosed Government information"]'::jsonb,0,'Correct. Under PSR Rule 021213, severance allowance is payable only if the person engaged is not in receipt of, nor eligible for, any other retiring benefits.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-445')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises Rule 021213?','["Severance allowance is 15 percent of basic salary on satisfactory completion of tour, provided the engagement was not terminated under Rule 021210 and no other retiring benefit is received or receivable","Severance allowance is automatic after dismissal","Severance allowance is paid only to pensionable Officers","Severance allowance is always 100 percent of salary"]'::jsonb,0,'Correct. PSR Rule 021213 provides for severance allowance at 15 percent of basic salary on satisfactory completion of a tour of service, provided the engagement was not terminated under Rule 021210 and the person is not receiving or eligible for other retiring benefits.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-446')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021214, is leave of absence a legal right included in the contract?','["Yes, it is an automatic legal right","No, it is not a legal right included in the contract","Yes, but only for senior Officers","Yes, but only after dismissal"]'::jsonb,1,'Correct. Under PSR Rule 021214, leave of absence is not a legal right included in the contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-447')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021214, leave may be granted after which event?','["After a tour of service","After misconduct","After unauthorized disclosure","After refusal to obey orders"]'::jsonb,0,'Correct. Under PSR Rule 021214, leave may be granted after a tour of service, subject to the applicable rules and exigencies of the Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-448')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 021214, leave may also be granted if the person engaged is declared what before completing the tour?','["Invalid","Promoted","Transferred","Dismissed"]'::jsonb,0,'Correct. Under PSR Rule 021214, leave may be granted if the person engaged is declared invalid before completing the tour.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-449')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 021214 also allows leave where the engagement is terminated by reason of ill-health in accordance with which rule?','["Rule 021207","Rule 021209","Rule 021211","Rule 021212"]'::jsonb,0,'Correct. Under PSR Rule 021214, leave may be granted where the engagement is terminated by reason of ill-health in accordance with Rule 021207.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-450')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where leave is granted under Rule 021214, the applicable rules are those for whom?','["Nigerian Officers of a similar grade level","Private-sector employees only","Staff Union officials only","Retired Permanent Secretaries only"]'::jsonb,0,'Correct. Under PSR Rule 021214, leave may be granted under rules applicable to Nigerian Officers of a similar grade level.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-451')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Leave under Rule 021214 is granted subject to what?','["Exigencies of the Public Service","Private business convenience","Automatic contract right","Staff Union election timetable"]'::jsonb,0,'Correct. Under PSR Rule 021214, leave may be granted so far as exigencies of the Public Service permit.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-452')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 12 of the PSR?','["It regulates the schedule for non-pensionable appointment, including term, duties, PSR conformity, emoluments, travel, ill-health, dismissal, termination, liability, further employment, severance allowance and leave","It deals only with promotion examinations","It deals only with mandatory pension contribution","It deals only with Certificate of Service"]'::jsonb,0,'Correct. PSR Chapter 2, Section 12, Rules 021201 to 021214 regulate the schedule for non-pensionable appointment, covering term of engagement, completion of term, duties, conformity to PSR, emoluments, travelling allowances, ill-health, medical fitness certificate, dismissal, termination, liability for damage, further employment, severance allowance and leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-453')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020101, appointments to offices in the Federal Civil Service are made on whose authority?','["The Office of the Accountant-General of the Federation","The Federal Civil Service Commission","The Staff Union","The National Assembly Service Commission"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 1, Rule 020101, appointments to offices in the Federal Civil Service are made on the authority of the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-454')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following is one mode of making appointments under Rule 020101?','["By letter written under the direction of the Federal Civil Service Commission","By verbal instruction from a colleague","By social media announcement only","By personal approval of the applicant"]'::jsonb,0,'Correct. Under PSR Rule 020101, appointments may be made by letter written under the direction of the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-455')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Apart from appointment by letter, how else may appointment be made under Rule 020101?','["By informal oral promise only","By newspaper rumour","By formal agreement between the Officer and the Federal Government or its appointed agents","By automatic self-appointment"]'::jsonb,2,'Correct. Under PSR Rule 020101, appointments may also be made by formal agreement between the Officer and the Federal Government or its appointed agents.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-456')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Subject to Rules 020205, 020206 and 020207, who may appoint eligible candidates to delegated posts?','["Permanent Secretaries or Heads of Extra-Ministerial Offices","The Staff Union Chairman","The Officer’s immediate colleague","The National Pension Commission"]'::jsonb,0,'Correct. Under PSR Rule 020101, Permanent Secretaries and Heads of Extra-Ministerial Offices are authorized to appoint eligible candidates to posts where the powers of appointment have been delegated to them, subject to Rules 020205, 020206 and 020207.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-457')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020102, the Federal Civil Service Commission makes appointments to posts graded within which range?','["GL. 01–06 only","GL. 07–17","GL. 18 only","All political appointments"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 1, Rule 020102, the Federal Civil Service Commission makes appointments to posts graded GL. 07–17.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-458')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Appointments by the Federal Civil Service Commission under Rule 020102 are made when?','["Only when there are available vacancies and the need arises","Only after retirement","Only when a Staff Union requests it","Only during annual leave"]'::jsonb,0,'Correct. Under PSR Rule 020102, appointments to GL. 07–17 are made as the need arises into available vacancies after advertisement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-459')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where must vacancies be advertised under Rule 020102?','["In three national newspapers and the Commission’s website","In one private notice board only","Only by word of mouth","Only through internal WhatsApp groups"]'::jsonb,0,'Correct. Under PSR Rule 020102, advertisement shall be in three national newspapers and on the Federal Civil Service Commission’s website.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-460')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the deadline for submission of applications after placement of advertisement under Rule 020102?','["Two weeks","Six weeks","One year","Three days"]'::jsonb,1,'Correct. Under PSR Rule 020102, the deadline for submission of applications from interested candidates is six weeks from the date of placement of the advertisement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-461')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020102, each Ministry or Extra-Ministerial Office selects candidates from what source?','["The pool of successful candidates at the Civil Service Examination","Unverified private lists only","Political party membership registers","Family nominations"]'::jsonb,0,'Correct. Under PSR Rule 020102, each Ministry or Extra-Ministerial Office selects from the pool of successful candidates at the Civil Service Examination prescribed in Rule 020102(iv).') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-462')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who participates in the appropriate Committees of each Ministry under Rule 020102?','["Representatives of the Federal Civil Service Commission and the Head of the Civil Service of the Federation","Only retired Officers","Only the Staff Union Chairman","Only private consultants"]'::jsonb,0,'Correct. Under PSR Rule 020102, the process is handled by the appropriate Committees of each Ministry with representatives of the Federal Civil Service Commission and the Head of the Civil Service of the Federation at the meetings.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-463')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What examination is established under Rule 020102 for posts graded GL. 07–10?','["Annual competitive Public/Civil Service Entry Examination","Annual medical examination only","Promotion interview for retired Officers only","Private aptitude test by a contractor"]'::jsonb,0,'Correct. Under PSR Rule 020102(iv), there shall be an annual competitive Public/Civil Service Entry Examination for posts graded GL. 07–10.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-464')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The annual competitive Public/Civil Service Entry Examination under Rule 020102 is for whom?','["New entrants and serving Officers wishing to transfer from other Scheduled Services","Only retired Officers","Only Officers on GL. 01","Only political appointees"]'::jsonb,0,'Correct. Under PSR Rule 020102(iv), the examination is for new entrants and serving Officers wishing to transfer from other Scheduled Services.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-465')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who conducts the annual competitive Public/Civil Service Entry Examination under Rule 020102?','["The Federal Civil Service Commission in conjunction with OHCSF, ASCON and PSIN","The Staff Union alone","The Federal Ministry of Finance alone","Private companies only"]'::jsonb,0,'Correct. Under PSR Rule 020102(iv), the examination is conducted by the Federal Civil Service Commission in conjunction with the Office of the Head of the Civil Service of the Federation, ASCON and PSIN.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-466')::uuid,'PSR','Chapter 2: Appointments & Career Progression','To qualify for the examination under Rule 020102, candidates must possess what?','["Qualifications in relevant disciplines as provided in the approved Schemes of Service","A political endorsement only","A private recommendation from relatives","No qualification at all"]'::jsonb,0,'Correct. Under PSR Rule 020102(v), candidates must possess the qualifications in relevant disciplines as provided in the approved Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-467')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who makes the final recommendation under Rule 020102 after the examination process?','["The line Ministries or Extra-Ministerial Offices","The Officer’s family","The Staff Union","The newspaper that carried the advert"]'::jsonb,0,'Correct. Under PSR Rule 020102(v), final recommendation is made by the line Ministries or Extra-Ministerial Offices in line with their requirements.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-468')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020103, who appoints Junior Staff on GL. 06 and below?','["Each Ministry or Extra-Ministerial Office","The Federal Ministry of Foreign Affairs only","The Staff Union","The Accountant-General personally"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 1, Rule 020103, each Ministry or Extra-Ministerial Office appoints Junior Staff on GL. 06 and below.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-469')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which committee handles appointment of Junior Staff under Rule 020103?','["Junior Staff Committee","Senior Staff Committee only","Performance Appraisal Committee","Medical Board"]'::jsonb,0,'Correct. Under PSR Rule 020103, appointment of Junior Staff on GL. 06 and below is handled by the Junior Staff Committee of each Ministry or Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-470')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020103, appointments in Federal Ministries or Extra-Ministerial Offices located in States/Zones shall be from whom?','["Residents of those States/Zones who possess the prescribed qualifications","Only persons from the Federal Capital Territory","Only retired Officers","Only foreign applicants"]'::jsonb,0,'Correct. Under PSR Rule 020103, appointments in Federal Ministries or Extra-Ministerial Offices located in States/Zones shall be from residents of those States/Zones who possess the qualifications prescribed in the approved Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-471')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The qualifications required for State/Zone appointments under Rule 020103 must be those prescribed where?','["In the approved Schemes of Service","In a private family record","In a newspaper opinion article","In a political manifesto"]'::jsonb,0,'Correct. Under PSR Rule 020103, residents of the relevant States/Zones must possess the qualifications prescribed in the approved Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-472')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the incremental date of an Officer appointed or promoted to a post in the Federal Public Service?','["1st January of every year","31st December of every year","The Officer’s birthday","The date of annual leave"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 1, Rule 020104, the incremental date of an Officer appointed or promoted to a post in the Federal Public Service is 1st January of every year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-473')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Before enjoying increment under Rule 020104, how long must an Officer have spent on the grade?','["At least six months","At least one week","At least ten years","At least one day"]'::jsonb,0,'Correct. Under PSR Rule 020104, an Officer must have spent at least six months on the grade before enjoying the increment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-474')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What additional condition is required before an Officer enjoys increment under Rule 020104?','["Good performance","Automatic seniority only","Political recommendation","Unpaid service"]'::jsonb,0,'Correct. Under PSR Rule 020104, an Officer must have spent at least six months on the grade with good performance before enjoying increment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-475')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020105, seniority in any Department is determined by what?','["Entry date or date of assumption of duty and/or date of present appointment","The Officer’s age only","The Officer’s leave address only","The Officer’s state of origin only"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 1, Rule 020105, seniority in any Department is determined by the entry date/date of assumption of duty certified by an authorized Officer and/or date of present appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-476')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The date used for seniority under Rule 020105 must be certified by whom?','["An authorized Officer","A private relative","A newspaper editor","A political party official"]'::jsonb,0,'Correct. Under PSR Rule 020105, the entry date or date of assumption of duty used to determine seniority must be certified by an authorized Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-477')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Seniority under Rule 020105 is reflected in what records?','["The appropriate register and career progression of the Officers","A personal diary only","A newspaper announcement","A private family register"]'::jsonb,0,'Correct. Under PSR Rule 020105, seniority is determined by the relevant dates as reflected in the appropriate register and career progression of the Officers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-478')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020106 provide about unpaid staff?','["The employment of unpaid Staff is prohibited","Unpaid Staff may be employed freely","Unpaid Staff are compulsory in all MDAs","Unpaid Staff must replace paid Officers"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 1, Rule 020106, the employment of unpaid Staff is prohibited.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-479')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020106?','["No unpaid Staff should be employed in the Federal Public Service","Unpaid Staff may be employed without records","Unpaid Staff may appoint themselves","Unpaid Staff may replace confirmed Officers"]'::jsonb,0,'Correct. PSR Rule 020106 prohibits the employment of unpaid Staff.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-480')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who must keep an up-to-date record of every Officer under their control?','["Permanent Secretaries or Heads of Extra-Ministerial Offices","The Officer’s neighbour","The Staff Union only","A private consultant"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 1, Rule 020107, Permanent Secretaries and Heads of Extra-Ministerial Offices shall keep an up-to-date record of every Officer under their control.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-481')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form is used for staff records under Rule 020107?','["Form Gen. 60","Form L.10 only","Form FC. 2 only","Form Gen. 69A only"]'::jsonb,0,'Correct. Under PSR Rule 020107, Staff Record Form Gen. 60 shall be used for personnel records.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-482')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Within what period must one copy of Form Gen. 60 be sent to the specified offices under Rule 020107?','["Within one month of the appointment","Within ten years of retirement","Within one week before retirement","Only after dismissal"]'::jsonb,0,'Correct. Under PSR Rule 020107, one copy of Form Gen. 60 must be sent to the specified offices within one month of the appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-483')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which office is among those to receive a copy of Form Gen. 60 under Rule 020107?','["National Record Centre in the Office of the Head of the Civil Service of the Federation","The Staff Union Secretariat","The Officer’s landlord","The local newspaper office"]'::jsonb,0,'Correct. Under PSR Rule 020107, one copy of Form Gen. 60 must be sent to the National Record Centre in the Office of the Head of the Civil Service of the Federation, among other listed offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-484')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following offices is also listed to receive Form Gen. 60 under Rule 020107?','["The Office of the Accountant-General of the Federation","The Officer’s private bank only","The Staff Union welfare desk","The local community association"]'::jsonb,0,'Correct. Under PSR Rule 020107, Form Gen. 60 is to be sent to the Office of the Accountant-General of the Federation, among other specified offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-485')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Form Gen. 60 must be completed in what manner under Rule 020107?','["In ink","In pencil only","Verbally","By phone call only"]'::jsonb,0,'Correct. Under PSR Rule 020107, Form Gen. 60 shall be completed in ink.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-486')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020107 provide about date of birth recorded on appointment?','["It shall not be changed throughout the Officer’s career","It may be changed every year","It is irrelevant to the Officer’s record","It must be deleted after confirmation"]'::jsonb,0,'Correct. Under PSR Rule 020107(ii), the date of birth recorded on appointment by an Officer shall not be changed throughout the career of the Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-487')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the consequence of contravening the date of birth rule under Rule 020107?','["It is regarded as an act of serious misconduct","It attracts automatic promotion","It is treated as annual leave","It has no consequence"]'::jsonb,0,'Correct. Under PSR Rule 020107(ii), contravention of the rule on date of birth recorded on appointment is regarded as an act of serious misconduct.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-488')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 1 of the PSR?','["It covers general appointment authority, FCSC appointments, junior staff appointments, incremental date, seniority, prohibition of unpaid staff and personnel records","It deals only with medical treatment abroad","It deals only with burial expenses","It deals only with disciplinary dismissal"]'::jsonb,0,'Correct. PSR Chapter 2, Section 1, Rules 020101 to 020107 cover general appointment provisions, including authority for appointments, FCSC appointments, junior staff appointments, incremental date, seniority, prohibition of unpaid staff and personnel records.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-489')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020201, what does recruitment mean?','["Promotion of Officers already in the same Ministry","Transfer of Officers from State Public Service only","Filling of vacancies by direct appointment of persons not already in any Public Service of the Federal Republic of Nigeria","Posting of confirmed Officers within the same Department"]'::jsonb,2,'Correct. Under PSR Chapter 2, Section 2, Rule 020201, recruitment means filling vacancies by direct appointment of persons not already in any Public Service of the Federal Republic of Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-490')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which process is expressly excluded from the definition of recruitment under Rule 020201?','["Direct appointment of new entrants","Filling vacancies in the Federal Public Service","Transfer of Officers from other Public Service in the Federation to the Federal Public Service","Appointment of persons not already in Public Service"]'::jsonb,2,'Correct. Under PSR Rule 020201, recruitment excludes the transfer of Officers from other Public Service in the Federation to the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-491')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Recruitment under Rule 020201 applies to persons with what status?','["Persons not already in any Public Service of the Federal Republic of Nigeria","Only Officers already transferred from another Public Service","Only retired Officers","Only Officers already confirmed in the Federal Civil Service"]'::jsonb,0,'Correct. PSR Rule 020201 defines recruitment as direct appointment of persons not already in any Public Service of the Federal Republic of Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-492')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following is a category of appointment into the Federal Public Service under Rule 020202?','["Appointment as trainees or pupils","Appointment by private family nomination","Appointment through political campaign service","Appointment by informal verbal promise"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 2, Rule 020202, appointment into the Federal Public Service may be as trainees or pupils.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-493')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which appointment category under Rule 020202 relates to a pensionable post?','["Acting appointment only","Special appointment only","Appointment on probation in a pensionable post","Appointment by family recommendation"]'::jsonb,2,'Correct. PSR Rule 020202 lists appointment on probation in a pensionable post as one of the categories of appointment into the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-494')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following is listed as a type of appointment under Rule 020202?','["Non-pensionable contract","Private honorary service","Political campaign engagement","Unpaid informal attachment"]'::jsonb,0,'Correct. Under PSR Rule 020202, appointment into the Federal Public Service may be on non-pensionable contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-495')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which option correctly lists categories of appointment under Rule 020202?','["Trainee or pupil, probation in a pensionable post, non-pensionable contract, acting appointment and special appointment","Annual leave, maternity leave, sick leave and casual leave","Dismissal, suspension, warning and surcharge","Posting, deployment, secondment and retirement"]'::jsonb,0,'Correct. PSR Rule 020202 lists these categories of appointment: trainee or pupil, probation in a pensionable post, non-pensionable contract, acting appointment and special appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-496')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How should Ministries and Extra-Ministerial Offices treat appointments made by the FCSC to NYSC Presidential Merit Award winners?','["They may reject them because of vacancy constraints","They shall accept them because employment is automatic regardless of vacancy constraints","They must convert them to unpaid staff","They must wait until the next leave year"]'::jsonb,1,'Correct. Under PSR Rule 020202, Ministries and Extra-Ministerial Offices shall accept appointments made by the Federal Civil Service Commission to NYSC Presidential Merit Award winners whose employment is automatic regardless of vacancy constraints.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-497')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What percentage of all recruitments in the Service is reserved for persons with disability under Rule 020202?','["One percent","Ten percent","Five percent","Twenty percent"]'::jsonb,2,'Correct. Under PSR Rule 020202, five percent of all recruitments in the Service shall be reserved for persons with disability.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-498')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What should normally happen where posts prove difficult to fill from within the Service?','["They should normally be advertised","They should be abolished automatically","They should be filled only by relatives of serving Officers","They should be left vacant permanently"]'::jsonb,0,'Correct. Under PSR Rule 020203, where posts prove difficult to fill from within the Service, they shall normally be advertised.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-499')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020203 mainly addresses what situation?','["Posts difficult to fill from within the Service","Annual leave computation","Disciplinary dismissal","Burial expenses"]'::jsonb,0,'Correct. PSR Rule 020203 provides that posts which prove difficult to fill from within the Service shall normally be advertised.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-500')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When may a candidate be appointed as a trainee or pupil under Rule 020204?','["Where the candidate requires additional professional experience before being regarded as fully qualified for appointment","Where the candidate has already retired from Service","Where the candidate refuses to meet qualification requirements","Where the candidate is being disciplined"]'::jsonb,0,'Correct. Under PSR Rule 020204(a), a candidate may be appointed as trainee or pupil where he requires additional professional experience before he can be regarded as fully qualified for appointment to a specific post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-501')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the normal service period for a trainee or pupil under Rule 020204?','["Six months","Five years","Two years","Ten years"]'::jsonb,2,'Correct. Under PSR Rule 020204(a), a trainee or pupil is appointed for a normal service period of two years in the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-502')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Can the normal two-year trainee or pupil period be reduced?','["Yes, in special circumstances","No, it can never be reduced","Only if the Officer resigns","Only after dismissal"]'::jsonb,0,'Correct. Under PSR Rule 020204(a), the normal two-year trainee or pupil period may be reduced in special circumstances.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-503')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After completing the trainee period, what may happen to the pupil under Rule 020204?','["He may be appointed to the full grade on probation","He is automatically dismissed","He is immediately retired","He becomes a political appointee"]'::jsonb,0,'Correct. Under PSR Rule 020204(a), on completion of the trainee period, the pupil may be appointed to the full grade on probation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-504')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After appointment to full grade on probation, when is the former trainee eligible for confirmation?','["Only after fulfilling the conditions laid down in Rule 020302 where applicable","Immediately without any condition","Only after retirement","Only after refusing the prescribed examination"]'::jsonb,0,'Correct. Under PSR Rule 020204(a), the pupil appointed to the full grade on probation is not eligible for confirmation until he has fulfilled the conditions laid down in Rule 020302 where applicable.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-505')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How is a confirmed Officer advanced to a training grade for experience treated under Rule 020204?','["As if he had been seconded to the training grade","As dismissed from Service","As newly recruited without record","As absent without leave"]'::jsonb,0,'Correct. Under PSR Rule 020204(b), a confirmed Officer advanced to a training grade for necessary experience to qualify for substantive promotion to a senior post is treated as if he had been seconded thereto.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-506')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The secondment period for a confirmed Officer advanced to a training grade should not normally exceed what?','["The period laid down for the training","Five years after retirement","The Officer’s annual leave period","Thirty-five years of service"]'::jsonb,0,'Correct. Under PSR Rule 020204(b), the period of secondment will not normally exceed the period laid down for the training except with the special advice of the OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-507')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Whose special advice may allow the training-grade secondment period to exceed the normal training period?','["The Office of the Head of the Civil Service of the Federation","The Officer’s neighbour","The Staff Union Treasurer","The private employer"]'::jsonb,0,'Correct. Under PSR Rule 020204(b), extension beyond the normal training period may occur only with the special advice of the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-508')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Except where the FCSC decides otherwise, how are first appointments to pensionable establishment treated?','["They are treated as automatic retirement","They are treated as appointments on probation","They are treated as unpaid appointments","They are treated as disciplinary postings"]'::jsonb,1,'Correct. Under PSR Rule 020205, except where the Federal Civil Service Commission decides otherwise, all first appointments to pensionable establishment in posts other than trainee posts will be on probation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-509')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which first appointments are excluded from the probation rule in Rule 020205?','["Trainee posts","All senior posts","All confirmed posts","All medical posts"]'::jsonb,0,'Correct. Under PSR Rule 020205, first appointments to pensionable establishment other than trainee posts are on probation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-510')::uuid,'PSR','Chapter 2: Appointments & Career Progression','An Officer confirmed in a lower pensionable post and converted to a higher post is treated how under Rule 020205?','["He is not regarded as on probation in the higher post","He must start probation again automatically","He becomes unpaid staff","He is deemed to have resigned"]'::jsonb,0,'Correct. Under PSR Rule 020205, an Officer confirmed in a lower pensionable post is not regarded as on probation in a higher post to which he is converted.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-511')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the minimum age for eligibility for appointment into the Federal Public Service under Rule 020206?','["18 years","16 years","21 years","25 years"]'::jsonb,0,'Correct. Under PSR Rule 020206(a), every applicant for appointment into the Federal Public Service must not be less than 18 years of age.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-512')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the maximum age for eligibility for appointment into the Federal Public Service under Rule 020206?','["45 years","60 years","50 years","65 years"]'::jsonb,2,'Correct. Under PSR Rule 020206(a), every applicant must not be more than 50 years of age.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-513')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which qualification requirement is stated under Rule 020206?','["Minimum qualification specified in the Schemes of Service including computer proficiency or literacy","Only a verbal recommendation from a friend","Only political endorsement","No qualification is required"]'::jsonb,0,'Correct. Under PSR Rule 020206(b), an applicant must possess the minimum qualification specified in the Schemes of Service, including computer proficiency or literacy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-514')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What medical condition must an applicant satisfy under Rule 020206?','["He must be certified medically fit for Public Service by an authorized Healthcare Provider","He must avoid medical examination","He must provide only a private family note","He must submit only an annual leave form"]'::jsonb,0,'Correct. Under PSR Rule 020206(c), an applicant must be certified by an authorized Healthcare Provider as medically fit for Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-515')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What testimonial is required from an applicant under Rule 020206?','["Testimonial of good conduct from last employer or, if not previously employed, from the last school or college attended","Testimonial from a political campaign office only","Testimonial from a private travel agent","Testimonial from a market association only"]'::jsonb,0,'Correct. Under PSR Rule 020206(d), an applicant must possess a testimonial of good conduct from the last employer or, if not previously employed, from the last school or college attended.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-516')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020206, requisite qualifications must be as provided where?','["In the Schemes of Service","In a newspaper advert only","In a political manifesto","In an informal staff list"]'::jsonb,0,'Correct. Under PSR Rule 020206(e), an applicant must possess requisite qualifications as provided for in the Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-517')::uuid,'PSR','Chapter 2: Appointments & Career Progression','No Officer shall be appointed into the Federal Public Service without what under Rule 020206?','["Authorized establishment and recruitment waiver from the OHCSF","A leave roster only","A private medical bill","A staff union certificate"]'::jsonb,0,'Correct. Under PSR Rule 020206(f), no Officer shall be appointed into the Federal Public Service without authorized establishment and recruitment waiver from the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-518')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When is prior specific approval required before appointing a candidate under Rule 020207?','["If the candidate has been convicted of a criminal offence","If the candidate has never worked before","If the candidate has a leave address","If the candidate is below retirement age"]'::jsonb,0,'Correct. Under PSR Rule 020207(a)(i), no candidate shall be appointed without prior specific approval if the candidate has been convicted of a criminal offence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-519')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Prior specific approval is also required if a candidate was previously employed in Public Service and what happened?','["He was dismissed or called upon to resign or retire","He took annual leave","He attended training","He received a posting letter"]'::jsonb,0,'Correct. Under PSR Rule 020207(a)(ii), prior specific approval is required if the candidate was previously employed in Public Service and dismissed or called upon to resign or retire.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-520')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who gives prior specific approval under Rule 020207 for the Federal Public Service?','["The Federal Civil Service Commission","The Staff Union Chairman","The candidate’s former employer","The Officer’s colleague"]'::jsonb,0,'Correct. Under PSR Rule 020207(a), prior specific approval of the Federal Civil Service Commission is required in the listed cases.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-521')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who gives prior specific approval in the case of Parastatals under Rule 020207?','["Board or Council","The Staff Union","The Accountant-General only","The Officer’s family"]'::jsonb,0,'Correct. Under PSR Rule 020207(a), in the case of Parastatals, prior specific approval of the Board or Council is required in the listed cases.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-522')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Must prior specific approval be obtained even where appointment powers have been delegated?','["Yes, it must always be obtained irrespective of any delegation of the Commission’s powers","No, delegation removes the need for approval","Only if the Officer is on annual leave","Only if the candidate requests it"]'::jsonb,0,'Correct. Under PSR Rule 020207(a), such approval must always be obtained irrespective of any delegation of the Commission’s powers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-523')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Every applicant for Government employment must state whether he has done what?','["Been convicted of a criminal offence","Taken annual leave","Attended a staff meeting","Received a transport allowance"]'::jsonb,0,'Correct. Under PSR Rule 020207(b)(i), every applicant for employment by Government must state whether he has been convicted of a criminal offence.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-524')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020207, what employment information must every applicant state?','["All employment he has engaged in","Only his current salary","Only his leave address","Only his political preference"]'::jsonb,0,'Correct. Under PSR Rule 020207(b)(ii), every applicant must state all employment he has engaged in.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-525')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If an applicant has left any employment, what must he state under Rule 020207?','["Why he left the employment","Only the name of his neighbour","Only his preferred posting location","Nothing, because it is irrelevant"]'::jsonb,0,'Correct. Under PSR Rule 020207(b)(iii), every applicant must state, if he has left any employment, why he did so.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-526')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If an applicant is still in any employment, what must he state under Rule 020207?','["Whether he is under any obligation to remain in it","Whether he wants annual leave","Whether he has a new phone number","Whether he wants a promotion"]'::jsonb,0,'Correct. Under PSR Rule 020207(b)(iv), an applicant still in employment must state whether he is under any obligation to remain in it.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-527')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which financial declaration must every applicant make under Rule 020207?','["Whether he is free from financial embarrassment","Whether he wants a loan immediately","Whether he owns a private vehicle","Whether he has travelled abroad"]'::jsonb,0,'Correct. Under PSR Rule 020207(b)(v), every applicant for employment by Government must state whether he is free from financial embarrassment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-528')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form must applicants for senior posts complete under Rule 020208?','["Federal Civil Service Commission Application Form FC. 2","Resumption of Duty Certificate Form L.10","Staff Union Form 1","Medical Treatment Form 130"]'::jsonb,0,'Correct. Under PSR Rule 020208(a), all applicants for senior posts shall complete Federal Civil Service Commission Application Form FC. 2.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-529')::uuid,'PSR','Chapter 2: Appointments & Career Progression','To whom is the FCSC Application Form FC. 2 submitted under Rule 020208?','["The Federal Civil Service Commission","The Staff Union","The applicant’s landlord","The Officer’s private school"]'::jsonb,0,'Correct. Under PSR Rule 020208(a), the Federal Civil Service Commission Application Form FC. 2 is submitted to the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-530')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does the FCSC do after receiving FC. 2 forms under Rule 020208?','["It processes the forms and publishes short-listed names for the prescribed examination","It destroys the forms immediately","It sends them only to the Staff Union","It converts them to leave forms"]'::jsonb,0,'Correct. Under PSR Rule 020208(a), the Commission processes the forms and publishes short-listed names for the examination prescribed in Rule 020102.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-531')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For appointment to pensionable establishment, which form accompanies the copy of Form Gen. 69 C?','["Form Gen. 60","Form L.10","Form FC. 7","Form 020211"]'::jsonb,0,'Correct. Under PSR Rule 020208(b), for appointment to pensionable establishment, Form Gen. 60 accompanies the copy of Form Gen. 69 C.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-532')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which office is among those to receive Form Gen. 60 and Form Gen. 69 C under Rule 020208?','["Office of the Head of the Civil Service of the Federation","The Staff Union Secretariat","The applicant’s former school only","A private business office"]'::jsonb,0,'Correct. Under PSR Rule 020208(b), the relevant forms are sent to the Office of the Head of the Civil Service of the Federation, among other listed offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-533')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following bodies is listed to receive the forms under Rule 020208?','["National Pension Commission","A political party office","Only the Officer’s bank","A private training centre"]'::jsonb,0,'Correct. Under PSR Rule 020208(b), the forms are sent to the National Pension Commission, among other listed offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-534')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When must a newly appointed Officer enter his personal particulars on Form Gen. 60?','["Immediately after assuming duty","After ten years of service","Only after retirement","Only after disciplinary proceedings"]'::jsonb,0,'Correct. Under PSR Rule 020209, immediately a newly appointed Officer assumes duty, he shall enter his personal particulars on Form Gen. 60.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-535')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is Form Gen. 60 called under Rule 020209?','["Staff Records Form","Annual Leave Form","Medical Board Form","Promotion Examination Form"]'::jsonb,0,'Correct. Under PSR Rule 020209, Form Gen. 60 is the Staff Records Form on which a newly appointed Officer enters his personal particulars.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-536')::uuid,'PSR','Chapter 2: Appointments & Career Progression','A copy of Form Gen. 60 is attached to documents forwarded to which body under Rule 020209?','["Pension Fund Administrator or National Pension Commission","Staff Union only","Private hospital only","Local newspaper only"]'::jsonb,0,'Correct. Under PSR Rule 020209, a copy of Form Gen. 60 is attached to appropriate documents forwarded to the Pension Fund Administrator, National Pension Commission and other relevant Offices or Departments.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-537')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who must ensure that all newly employed Officers and Staff sign the Oath of Secrecy on Security?','["Permanent Secretary or Head of Extra-Ministerial Office","The Staff Union Chairman","The Officer’s colleague","A private security guard"]'::jsonb,0,'Correct. Under PSR Rule 020210, every Permanent Secretary or Head of Extra-Ministerial Office must ensure that all newly employed Officers and Staff sign an Oath of Secrecy on Security.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-538')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form is used for the Oath of Secrecy on Security under Rule 020210?','["Form 1","Form L.10","Form Gen. 74","Form FC. 5"]'::jsonb,0,'Correct. Under PSR Rule 020210, newly employed Officers and Staff sign an Oath of Secrecy on Security using Form 1.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-539')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must be done with signed Oaths of Secrecy under Rule 020210?','["They must be carefully preserved","They must be destroyed immediately","They must be published online","They must be given to private contractors"]'::jsonb,0,'Correct. Under PSR Rule 020210, signed Oaths of Secrecy must be carefully preserved.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-540')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020210 is without prejudice to which Act?','["Freedom of Information Act","Public Procurement Act only","Employees Compensation Act only","Pension Reform Act only"]'::jsonb,0,'Correct. Under PSR Rule 020210, the requirement to sign and preserve the Oath of Secrecy is without prejudice to the provisions of the Freedom of Information Act.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-541')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020211 prohibit?','["Membership of any secret society by a public Officer","Annual leave by public Officers","Medical examination by public Officers","Participation in training by public Officers"]'::jsonb,0,'Correct. Under PSR Rule 020211, no public Officer shall be a member of any secret society.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-542')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If a person was a member of a secret society before appointment, what must he do under Rule 020211?','["Renounce his membership forthwith by making a statutory declaration","Continue membership secretly","Wait until retirement before leaving","Seek promotion through the society"]'::jsonb,0,'Correct. Under PSR Rule 020211, any public Officer who before appointment was a member of a secret society must renounce membership forthwith by making a statutory declaration.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-543')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How must prior membership of a secret society be renounced under Rule 020211?','["By making a statutory declaration","By verbal statement to a friend only","By refusing medical examination","By taking annual leave"]'::jsonb,0,'Correct. Under PSR Rule 020211, renunciation of membership of a secret society must be by statutory declaration.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-544')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Contravention of Rule 020211 is regarded as what?','["An act of serious misconduct","A minor clerical error","Annual leave entitlement","Medical exemption"]'::jsonb,0,'Correct. Under PSR Rule 020212, contravention of Rule 020211 on secret society membership is regarded as an act of serious misconduct.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-545')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What disciplinary consequence may follow contravention of Rule 020211 under Rule 020212?','["Appropriate disciplinary action which may include dismissal from the Service","Automatic promotion","Immediate annual leave","Payment of leave allowance"]'::jsonb,0,'Correct. Under PSR Rule 020212, contravention of Rule 020211 attracts appropriate disciplinary action which may include dismissal from the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-546')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 2 of the PSR?','["It covers recruitment, types of appointment, advertising hard-to-fill posts, trainee or pupil appointments, probation, eligibility, prior approval, appointment forms, personal records, oath of secrecy and prohibition of secret society membership","It deals only with medical treatment abroad","It deals only with annual leave computation","It deals only with burial expenses"]'::jsonb,0,'Correct. PSR Chapter 2, Section 2, Rules 020201 to 020212 cover recruitment, types of appointment, difficult-to-fill posts, trainee or pupil appointment, probation, eligibility, prior approval, appointment procedure, personal particulars, oath of secrecy, secret society prohibition and contravention.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-547')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020301, how long are Officers on probation required to serve before confirmation in the Service?','["Six months only","Two years","Five years","One month"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 3, Rule 020301, Officers on probation are required to serve for two years before being confirmed in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-548')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020301, the probationary period may be reduced to not less than what period?','["One year","Three months","Six months","Two weeks"]'::jsonb,2,'Correct. Under PSR Rule 020301, the probationary period may be reduced, but not to less than six months, by deducting previous satisfactory Public Service in cognate posts involving similar duties.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-549')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What previous service may be deducted from the probationary period under Rule 020301?','["Any private business experience","Previous Public Service rendered satisfactorily in posts of cognate status involving similar duties","Any period of annual leave","Unapproved absence from duty"]'::jsonb,1,'Correct. Under PSR Rule 020301, previous satisfactory Public Service in posts of cognate status involving similar duties may be deducted when reducing the probationary period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-550')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The probationary period shall not exceed two years unless an extension is approved by whom?','["The Staff Union","The Officer’s colleague","The Federal Civil Service Commission","The Accountant-General"]'::jsonb,2,'Correct. Under PSR Rule 020301, the probationary period shall not exceed two years unless an extension is approved by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-551')::uuid,'PSR','Chapter 2: Appointments & Career Progression','An extension of probation under Rule 020301 may result in what penalty if the Commission so decides?','["Incremental penalty referred to in Rule 040206","Automatic promotion","Maternity leave reduction","Burial allowance stoppage"]'::jsonb,0,'Correct. Under PSR Rule 020301, an extension of probation may result in the incremental penalty referred to in Rule 040206, if the Federal Civil Service Commission so decides.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-552')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best describes the general rule on probation under Rule 020301?','["Probation is always one month and cannot be extended","Probation is two years, may be reduced to not less than six months, and may exceed two years only with FCSC approval","Probation applies only to retired Officers","Probation automatically ends without examination"]'::jsonb,1,'Correct. PSR Rule 020301 provides that probation is normally two years, may be reduced to not less than six months for relevant previous Public Service, and may exceed two years only where the Federal Civil Service Commission approves extension.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-553')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Within his probationary period, what is an Officer required to do under Rule 020302?','["Pass the prescribed examination appropriate to his appointment","Proceed on leave of absence","Apply for burial expenses","Refuse confirmation examination"]'::jsonb,0,'Correct. Under PSR Chapter 2, Section 3, Rule 020302, an Officer is required within his probationary period to pass the prescribed examination appropriate to his appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-554')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For Officers holding senior posts, the prescribed examinations are those described where?','["Chapter 12 and the Leave Circular","Chapter 3 and such other examinations as may be specified in the offer of appointment","Chapter 16 only","Financial Regulations only"]'::jsonb,1,'Correct. Under PSR Rule 020302(a), Officers holding senior posts must pass the examinations described in Chapter 3 and any other examination specified in the individual offer of appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-555')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For clerical grade Officers, what is the prescribed examination under Rule 020302?','["Promotion/Confirmation Examination","Medical Board Examination","Procurement Certification Examination","Driving Test"]'::jsonb,0,'Correct. Under PSR Rule 020302(b), the prescribed examination for clerical grade Officers is the Promotion/Confirmation Examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-556')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The examinations for technical grades are those prescribed where?','["In the Schemes of Service applicable to the particular post","In the Officer’s leave roster","Only in newspaper advertisements","Only by the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020302(c), examinations for technical grades are those prescribed in the Schemes of Service applicable to the particular post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-557')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020302?','["Every probationary Officer must pass the prescribed examination appropriate to his appointment","Only Officers on suspension take confirmation examinations","Confirmation examination is optional for all probationary Officers","Technical Officers use casual leave rules for confirmation"]'::jsonb,0,'Correct. PSR Rule 020302 requires an Officer, within his probationary period, to pass the prescribed examination appropriate to his appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-558')::uuid,'PSR','Chapter 2: Appointments & Career Progression','To be eligible for confirmation in Permanent Establishment, what must an Officer appointed on probation do?','["Pass the prescribed examination, if any, and complete probation to the satisfaction of the appointing authority","Serve for one week only","Refuse to take the prescribed examination","Obtain approval from a Staff Union only"]'::jsonb,0,'Correct. Under PSR Rule 020303, an Officer on probation must pass the prescribed examination, if any, and complete the probationary period to the satisfaction of the authority empowered to appoint him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-559')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who must be satisfied before a probationary Officer is confirmed under Rule 020303?','["The authority empowered to appoint him","The Officer’s neighbour","The Staff Union Treasurer","A private consultant"]'::jsonb,0,'Correct. Under PSR Rule 020303, the Officer must complete the probationary period to the satisfaction of the authority empowered to appoint him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-560')::uuid,'PSR','Chapter 2: Appointments & Career Progression','At the end of the probationary period, what happens to the Officer unless his appointment is terminated or extended?','["He is confirmed in his appointment","He is automatically dismissed","He proceeds on unpaid leave","He becomes a contract Officer"]'::jsonb,0,'Correct. Under PSR Rule 020303, at the end of the probationary period, the Officer will be confirmed in his appointment unless his probationary appointment is terminated or extended.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-561')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following may happen at the end of probation under Rule 020303?','["Confirmation, termination or extension of probation","Automatic political appointment","Automatic overseas posting","Compulsory resignation without assessment"]'::jsonb,0,'Correct. Under PSR Rule 020303, at the end of probation, the Officer is confirmed unless his probationary appointment is terminated or extended.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-562')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020304, how are recommendations on confirmation of Officers holding senior posts made?','["In the progress report prescribed in Chapter 5 of the Rules","By newspaper publication","By verbal message from colleagues","Through casual leave application"]'::jsonb,0,'Correct. Under PSR Rule 020304, recommendations of Permanent Secretaries/Heads of Extra-Ministerial Offices regarding confirmation of Officers holding senior posts shall be made in the progress report prescribed in Chapter 5 of the Rules.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-563')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who makes recommendations regarding confirmation of Officers holding senior posts under Rule 020304?','["Permanent Secretaries or Heads of Extra-Ministerial Offices","The Officer’s family","The Staff Union only","The private sector employer"]'::jsonb,0,'Correct. Under PSR Rule 020304, Permanent Secretaries and Heads of Extra-Ministerial Offices make recommendations regarding confirmation of Officers holding senior posts.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-564')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020304 links senior post confirmation recommendation to which chapter?','["Chapter 5","Chapter 12","Chapter 16","Chapter 18"]'::jsonb,0,'Correct. Under PSR Rule 020304, recommendations for confirmation of Officers holding senior posts are made in the progress report prescribed in Chapter 5.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-565')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020305, membership of the Junior Staff Committee and Senior Staff Committee in Parastatals shall include whose representative?','["Representative of the Department of Human Resource Management of the supervising Ministry","Representative of the Officer’s landlord","Representative of a private travel agency","Representative of the applicant’s family"]'::jsonb,0,'Correct. Under PSR Rule 020305, membership of JSC and SSC in Parastatals shall include the representative of the Department of Human Resource Management of the supervising Ministry.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-566')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which office must have an observer in the JSC and SSC in Parastatals under Rule 020305?','["Office of the Head of the Civil Service of the Federation","Office of the Auditor-General only","Office of the Accountant-General only","Staff Union Secretariat"]'::jsonb,0,'Correct. Under PSR Rule 020305, membership of the Junior Staff Committee and Senior Staff Committee in Parastatals shall include an observer from the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-567')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020305 concerns membership of which committees in Parastatals?','["Junior Staff Committee and Senior Staff Committee","Medical Board and Procurement Committee","Leave Committee and Burial Committee","Housing Committee and Transport Committee"]'::jsonb,0,'Correct. PSR Rule 020305 provides for membership of the Junior Staff Committee and Senior Staff Committee in Parastatals.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-568')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises Rule 020305?','["JSC and SSC in Parastatals must include HRM representative of the supervising Ministry and an OHCSF observer","JSC and SSC in Parastatals consist only of private consultants","JSC and SSC in Parastatals are abolished","JSC and SSC in Parastatals are controlled only by Staff Union officials"]'::jsonb,0,'Correct. Under PSR Rule 020305, the Junior Staff Committee and Senior Staff Committee in Parastatals include the supervising Ministry’s HRM representative and an observer from the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-569')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020306, a newly recruited Officer may sit for compulsory examinations for confirmation after spending what minimum period?','["Six months and above","One week","Three years only","Ten years"]'::jsonb,0,'Correct. Under PSR Rule 020306, a newly recruited Officer who has spent six months and above shall be allowed to sit for compulsory examinations for confirmation in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-570')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020306 is without prejudice to which rule?','["Rule 020301","Rule 120101","Rule 130401","Rule 060101"]'::jsonb,0,'Correct. Under PSR Rule 020306, the provision allowing newly recruited Officers who have spent six months and above to sit for compulsory examinations is without prejudice to Rule 020301.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-571')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What type of examinations may a newly recruited Officer sit for after six months and above under Rule 020306?','["Compulsory examinations for confirmation in the Service","Medical Board examination only","Driving examination only","Procurement examination only"]'::jsonb,0,'Correct. Under PSR Rule 020306, a newly recruited Officer who has spent six months and above shall be allowed to sit for compulsory examinations for confirmation in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-572')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020307, transfer from one senior post to another within the Federal Public Service requires whose prior approval?','["Federal Civil Service Commission or appropriate board of relevant agency","The Officer’s colleague only","The Staff Union Chairman","The Officer’s family"]'::jsonb,0,'Correct. Under PSR Rule 020307, transfer from one senior post to another or from one class to another within the Federal Public Service requires prior approval of the Federal Civil Service Commission or the appropriate board of the relevant agency.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-573')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Before seeking transfer to another post under Rule 020307, an Officer must have served how long in his original post?','["Minimum period of six months","Minimum period of ten years","One week only","One month only"]'::jsonb,0,'Correct. Under PSR Rule 020307, an Officer must have served for a minimum period of six months in his original post before seeking transfer to another post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-574')::uuid,'PSR','Chapter 2: Appointments & Career Progression','To whom must an application for transfer under Rule 020307 be submitted?','["Permanent Secretary/Head of Extra-Ministerial Office or Agency of the applicant","The Officer’s neighbour","The Staff Union only","A private consultant"]'::jsonb,0,'Correct. Under PSR Rule 020307, an application for transfer must be submitted to the Permanent Secretary/Head of Extra-Ministerial Office or Agency of the applicant.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-575')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must an Officer’s transfer application state under Rule 020307?','["The applicant’s reasons for desiring transfer and his qualifications for the work to be undertaken","Only the Officer’s leave address","Only the Officer’s salary account","Only the Officer’s family details"]'::jsonb,0,'Correct. Under PSR Rule 020307, the transfer application must state the applicant’s reasons for desiring a transfer and his qualifications for the work to be undertaken.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-576')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who forwards the transfer application to the Federal Civil Service Commission under Rule 020307?','["The Permanent Secretary/Head of Extra-Ministerial Office","The Officer’s colleague","The Staff Union Treasurer","The private employer"]'::jsonb,0,'Correct. Under PSR Rule 020307, the Permanent Secretary or Head of Extra-Ministerial Office forwards the transfer application to the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-577')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement must accompany the transfer application under Rule 020307?','["A statement on how the applicant has performed his duties","A statement on the Officer’s family ceremonies only","A statement on the Officer’s private business only","A statement from the Officer’s neighbour"]'::jsonb,0,'Correct. Under PSR Rule 020307, the application should be forwarded with a statement showing how the applicant has performed his duties.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-578')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The statement forwarded with a transfer application must also indicate what under Rule 020307?','["Whether the applicant is considered well qualified for the post desired","Whether the applicant owns a private vehicle","Whether the applicant prefers annual leave abroad","Whether the applicant belongs to a social club"]'::jsonb,0,'Correct. Under PSR Rule 020307, the forwarded statement must indicate whether the applicant is considered well qualified for the post desired.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-579')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The Permanent Secretary/Head of Extra-Ministerial Office must include what recommendation on the transfer application?','["Recommendation as to the grant or refusal of the application","Recommendation for automatic dismissal","Recommendation for burial expenses","Recommendation for maternity leave"]'::jsonb,0,'Correct. Under PSR Rule 020307, the forwarded statement must include recommendations as to the grant or refusal of the transfer application.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-580')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 3 of the PSR?','["It covers probation period, compulsory examination, confirmation or termination, progress reports for senior posts, JSC/SSC membership, COMPRO examination eligibility and transfer within the Federal Public Service","It deals only with medical treatment abroad","It deals only with burial expenses","It deals only with annual leave"]'::jsonb,0,'Correct. PSR Chapter 2, Section 3, Rules 020301 to 020307 cover rules for appointment on probation, including probation period, compulsory examination, confirmation or termination, senior post confirmation reports, JSC/SSC membership in Parastatals, COMPRO examination eligibility and transfer within the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-581')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020401, why may short-term appointments be made in the Public Service?','["To punish Officers for poor performance","To fill observed skills gaps or shore up the capacities of existing Officers","To replace all pensionable appointments permanently","To avoid using the Schemes of Service"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 4, Rule 020401, short-term appointments may be made where specialized or new/emerging skills are required to fill observed gaps or strengthen the capacities of existing Officers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-582')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following is one category of short-term appointment listed under Rule 020401?','["Contract Appointment","Compulsory Retirement","Disciplinary Suspension","Annual Leave"]'::jsonb,0,'Correct. Under PSR Rule 020401, Contract Appointment is one of the categories of short-term appointments in the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-583')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which option correctly lists categories of short-term appointment under Rule 020401?','["Contract Appointment, Sabbatical Appointment, Career Exchange Programme, Talent Sourcing Strategy, Internship and Volunteerism","Probation, Promotion, Retirement and Dismissal","Annual Leave, Casual Leave, Sick Leave and Maternity Leave","Posting, Transfer, Discipline and Appeal"]'::jsonb,0,'Correct. PSR Rule 020401 lists Contract Appointment, Sabbatical Appointment, Career Exchange Programme, Talent Sourcing Strategy, Internship and Volunteerism as categories of short-term appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-584')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Short-term appointments under Rule 020401 may involve specialized skills that are what?','["Only political skills","Only skills prescribed in disciplinary rules","Prescribed or not prescribed in the Schemes of Service","Only skills used by retired Officers"]'::jsonb,2,'Correct. Under PSR Rule 020401, specialized or new/emerging skills may or may not have been prescribed in the Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-585')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is a Contract Appointment under Rule 020402?','["A permanent pensionable appointment","A temporary appointment that does not provide for payment of pension","An automatic promotion into a senior post","A leave arrangement for study abroad"]'::jsonb,1,'Correct. Under PSR Rule 020402, a Contract Appointment is a temporary appointment that does not provide for payment of pension and is made for a specific period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-586')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who makes contract appointment to posts under Rule 020402 in the core Federal Civil Service?','["The Staff Union","The Federal Civil Service Commission","The Officer’s family","The Pension Fund Administrator"]'::jsonb,1,'Correct. Under PSR Rule 020402, contract appointment to the relevant level is made by the Federal Civil Service Commission in the core Federal Civil Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-587')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who makes contract appointment in Parastatals and Agencies under Rule 020402?','["The Governing Board","The Officer’s colleague","The Federal Road Safety Corps only","The Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020402, in the case of Parastatals and Agencies, contract appointment is made by the Governing Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-588')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How must a contract appointment be recorded under Rule 020402?','["By verbal promise only","In a formal document of agreement","By social media announcement","By informal office note"]'::jsonb,1,'Correct. Under PSR Rule 020402, a contract appointment must be recorded in a formal document of agreement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-589')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Contract Appointment may be offered where the Service no longer has what?','["Officers with specific skills needed to perform related functions","Annual leave rosters","Enough official vehicles","Staff quarters"]'::jsonb,0,'Correct. Under PSR Rule 020403(i), Contract Appointment may be offered if it is established that the Service no longer has Officers with specific skills provided in the approved Schemes of Service to perform the related functions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-590')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020403, contract appointment may arise from which situation?','["Emerging cadres, courses, skills and the creation of new ones","An Officer’s refusal to resume from leave","Disciplinary punishment","Failure to sign attendance register"]'::jsonb,0,'Correct. Under PSR Rule 020403(ii), Contract Appointment may be based on circumstances arising from emerging cadres, courses, skills and the creation of new ones as well as prevailing realities.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-591')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Contract Appointment may be tied to what under Rule 020403?','["Funded projects or programmes with specified life span","Unapproved private business","Permanent tenure without end","Annual leave computation"]'::jsonb,0,'Correct. Under PSR Rule 020403(iii), Contract Appointment may be tied to funded projects or programmes with specified life span.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-592')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When may Contract Appointment be offered to expatriates under Rule 020403?','["Only when suitable Nigerians are not available","Whenever expatriates apply first","Only when a post is below GL. 06","Only after all Nigerians are retired"]'::jsonb,0,'Correct. Under PSR Rule 020403(iv), Contract Appointment may be offered to expatriates only when suitable Nigerians are not available.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-593')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which Nigerian may be considered for Contract Appointment under Rule 020403?','["A pensioner","A newly recruited Officer on probation only","An Officer under dismissal","Any person without specialized skill"]'::jsonb,0,'Correct. Under PSR Rule 020403(v)(a), Contract Appointment may be offered to Nigerians if they are pensioners.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-594')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020403, a Nigerian may be considered for Contract Appointment if he is at least what age at the time of appointment?','["35 years","40 years","45 years","50 years"]'::jsonb,3,'Correct. Under PSR Rule 020403(v)(b), Contract Appointment may be offered to Nigerians if they are 50 years of age or over at the time they are being appointed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-595')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where a Nigerian specifically requests employment on contract terms, what further condition applies under Rule 020403?','["It must be deemed in the best interest of the Service","It must be approved by the Staff Union only","It must be for annual leave purposes","It must avoid advertisement always"]'::jsonb,0,'Correct. Under PSR Rule 020403(v)(c), a Nigerian who specifically requests contract terms may be employed if it is deemed in the best interest of the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-596')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where specialized competencies or skills are required for Contract Appointment, how must the post be advertised under Rule 020403?','["In at least three national newspapers","Only on a notice board","Only by word of mouth","Only through a private WhatsApp group"]'::jsonb,0,'Correct. Under PSR Rule 020403(v)(d), where the candidate possesses specialized competencies or skills, such posts must be duly advertised in at least three national newspapers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-597')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020404, the conditions of service of an Officer on short-term appointment are those provided where?','["In his contract","In the Officer’s personal diary","In the Staff Union constitution only","In a newspaper report"]'::jsonb,0,'Correct. Under PSR Rule 020404(i), the conditions of service of an Officer on short-term appointment are those provided in his contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-598')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Do PSR privileges, emoluments or allowances automatically apply to an Officer on short-term appointment?','["Yes, they apply automatically in every case","No, unless they are stated in the contract itself","Yes, if the Officer is above 50 years","Yes, if the Officer requests them"]'::jsonb,1,'Correct. Under PSR Rule 020404(i), the privileges, emoluments or allowances in the PSR do not apply to a short-term appointee unless stated in the contract itself.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-599')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Questions on interpretation of a short-term appointment contract affecting conditions of service should be referred to whom?','["The Office of the Head of the Civil Service of the Federation","The Officer’s family","The Staff Union only","The host department clerk"]'::jsonb,0,'Correct. Under PSR Rule 020404(i), questions on interpretation of a contract affecting conditions of service should be referred to the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-600')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020404, what is the position of spouses married to Nigerians before Nigerian citizenship is granted?','["They should remain on contract until granted Nigerian citizenship before being considered for permanent appointment","They must immediately become permanent Officers","They are automatically placed on pensionable appointment","They must be exempted from contract rules"]'::jsonb,0,'Correct. Under PSR Rule 020404(iii), spouses married to Nigerians should remain on contract until granted Nigerian citizenship before being considered for permanent appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-601')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020405, which body in an MDA identifies required skills for Contract Appointment?','["The Senior Staff Committee","The Staff Union","The Pension Fund Administrator","The Officer’s family"]'::jsonb,0,'Correct. Under PSR Rule 020405(i), MDAs through their Senior Staff Committee identify required skills and defend the skills at the OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-602')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the role of the OHCSF in the skill-identification process under Rule 020405?','["To work out and approve waiver for the desired skills","To conduct burial arrangements","To approve annual leave rosters","To replace the Federal Civil Service Commission"]'::jsonb,0,'Correct. Under PSR Rule 020405(i), the OHCSF works out and approves waiver for the desired skills after the MDA defends the identified skills.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-603')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form must a prospective applicant submit for Contract Appointment under Rule 020405?','["FCSC Form 2","Form L.10","Form Gen. 60 only","Medical Board Form"]'::jsonb,0,'Correct. Under PSR Rule 020405(ii), the prospective applicant must apply by submitting a duly filled FCSC Form 2 as required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-604')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020405, Contract Appointment must not be made below which salary grade level?','["SGL. 06","SGL. 10","SGL. 12","SGL. 15"]'::jsonb,2,'Correct. Under PSR Rule 020405(iii), the post to which contract appointment is made must not be below SGL. 12.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-605')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Contract Appointment must be based on what process under Rule 020405?','["Fair, open and competitive selection process","Secret nomination only","Automatic appointment by relatives","Unadvertised verbal agreement"]'::jsonb,0,'Correct. Under PSR Rule 020405(iv), Contract Appointment must be based on merit through a fair, open and competitive selection process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-606')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Contract Appointment under Rule 020405 must not jeopardize what?','["The career prospects of serving Officers","The applicant’s private business","The Staff Union election timetable","The Officer’s leave address"]'::jsonb,0,'Correct. Under PSR Rule 020405(iv), Contract Appointment must not jeopardize the career prospects of serving Officers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-607')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For Contract Appointment of non-Nigerians, who undertakes immigration responsibilities under Rule 020405?','["Government","The Officer’s family","The Staff Union","The prospective applicant alone"]'::jsonb,0,'Correct. Under PSR Rule 020405(v), Government undertakes immigration responsibilities, including relevant working or residence permit, for non-Nigerians.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-608')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the normal duration of Contract Appointment under Rule 020405?','["One or two years, renewable but not more than four years in all","Seven years without renewal","Ten years automatically","Six months only"]'::jsonb,0,'Correct. Under PSR Rule 020405(vii), the duration of Contract Appointment should be one or two years and renewable, but not more than four years in all.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-609')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020406, a Contract Officer must be responsible for what as part of his duties?','["Mentoring serving Officers","Approving his own promotion","Conducting political campaigns","Avoiding performance appraisal"]'::jsonb,0,'Correct. Under PSR Rule 020406(i), a Contract Officer must, as part of his duties, be responsible for mentoring serving Officers as a condition for the contract appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-610')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What undertaking must a Contract Officer sign under Rule 020406?','["To accept posting or transfer to any part of the country","To refuse posting outside headquarters","To avoid confidential reports","To demand automatic pension"]'::jsonb,0,'Correct. Under PSR Rule 020406(ii), a Contract Officer must sign an undertaking to accept posting or transfer to any part of the country.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-611')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How are Officers appointed on contract appraised under Rule 020406?','["Through confidential report as applicable in the Service","Through public voting","Through family recommendation only","They are not appraised"]'::jsonb,0,'Correct. Under PSR Rule 020406(iii), Officers appointed on contract are subject to performance appraisal through confidential report as applicable in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-612')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020406, Contract staff must sign the oath of secrecy in line with which rule?','["Rule 020210","Rule 120101","Rule 130401","Rule 100601"]'::jsonb,0,'Correct. Under PSR Rule 020406(iv), Contract staff must sign the oath of secrecy in line with PSR Rule 020210.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-613')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who may terminate a Contract Appointment in accordance with the terms of the contract?','["Government","The Officer’s landlord","The Staff Union","The Officer’s colleague"]'::jsonb,0,'Correct. Under PSR Rule 020407(a), an appointment on contract may be terminated by Government at any time in accordance with the terms specified in the contract itself.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-614')::uuid,'PSR','Chapter 2: Appointments & Career Progression','A recommendation to terminate the appointment of a Contract Officer must be accompanied by what?','["A full statement of the consideration which prompted it","A leave roster only","A Staff Union attendance list","A newspaper advert"]'::jsonb,0,'Correct. Under PSR Rule 020407(a), a recommendation to the Federal Civil Service Commission for termination must be accompanied by a full statement of the consideration which prompted it.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-615')::uuid,'PSR','Chapter 2: Appointments & Career Progression','On receiving a termination recommendation, what may the Federal Civil Service Commission decide?','["Whether to terminate forthwith or allow the Officer to submit formal representation","Whether to grant annual leave only","Whether to pay burial expenses","Whether to appoint the Officer permanently without review"]'::jsonb,0,'Correct. Under PSR Rule 020407(a), the FCSC decides whether the appointment should be terminated forthwith or whether the Officer should be offered opportunity to submit formal representation before final decision.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-616')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Termination of Contract Appointment by the holder is subject to what?','["The terms of the contract","The Officer’s private preference only","The Staff Union constitution","The leave roster"]'::jsonb,0,'Correct. Under PSR Rule 020407(b), termination of a contract appointment by the holder is subject to the terms of the contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-617')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Questions about waiving penalty under a contract agreement should be referred to whom?','["The Office of the Head of the Civil Service of the Federation","The Officer’s family","The Staff Union Treasurer","The nearest newspaper office"]'::jsonb,0,'Correct. Under PSR Rule 020407(b), any question concerning waiver of penalty under a contract agreement shall be referred to the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-618')::uuid,'PSR','Chapter 2: Appointments & Career Progression','An Officer on contract who desires re-engagement must notify Government how?','["In writing through the Permanent Secretary or Head of Extra-Ministerial Office","By verbal message to a colleague","Through social media only","By refusing to proceed on leave"]'::jsonb,0,'Correct. Under PSR Rule 020408, an Officer serving on contract who desires re-engagement must inform Government in writing through the Permanent Secretary or Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-619')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How long before leave is due must a Contract Officer request re-engagement?','["Not less than four months","One week","One year","Two days"]'::jsonb,0,'Correct. Under PSR Rule 020408, the Officer must give written notification not less than four months before his leave is due.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-620')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If a Contract Officer gives no notification of desire for re-engagement, what may be assumed?','["That he does not desire re-engagement","That he is automatically re-engaged","That he must be promoted","That he is on study leave"]'::jsonb,0,'Correct. Under PSR Rule 020408, in the absence of notification, it may be assumed that the Contract Officer does not desire re-engagement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-621')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After receiving a Contract Officer’s request for re-engagement, whose consent must the Permanent Secretary or Head obtain before forwarding recommendation to the FCSC?','["The Office of the Head of the Civil Service of the Federation","The Staff Union","The Officer’s family","The Pension Fund Administrator"]'::jsonb,0,'Correct. Under PSR Rule 020409, the Permanent Secretary or Head of Extra-Ministerial Office must obtain the consent of the OHCSF before forwarding recommendation for re-engagement to the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-622')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What report must accompany the re-engagement recommendation unless recently forwarded?','["An up-to-date confidential report on the Officer","A leave address form","A medical bill","A newspaper advert"]'::jsonb,0,'Correct. Under PSR Rule 020409, an up-to-date confidential report on the Officer must be enclosed unless such report has been forwarded within the previous two months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-623')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What may the Permanent Secretary receive in reply under Rule 020409?','["Authority to inform the Officer that arrangements will be made to offer re-engagement","Authority to dismiss all contract staff automatically","A leave roster for the next year","A pension clearance certificate"]'::jsonb,0,'Correct. Under PSR Rule 020409(a), the Permanent Secretary or Head may receive authority to inform the Officer that arrangements will be made to offer re-engagement during leave and the proposed terms.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-624')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where the original and duplicate re-engagement contract are received, what should the Permanent Secretary or Head do?','["Obtain the Officer’s witnessed signature on both copies, deliver the duplicate to the Officer and return the original to OHCSF","Destroy both copies","Keep both copies without signature","Send both copies to the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020409(b), the Permanent Secretary or Head obtains the Officer’s witnessed signature on both copies, delivers the duplicate to the Officer and returns the original to the OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-625')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If a Permanent Secretary cannot recommend re-engagement of a Contract Officer, whose approval must be sought before informing the Officer?','["The Federal Civil Service Commission","The Staff Union","The Officer’s family","The Accountant-General"]'::jsonb,0,'Correct. Under PSR Rule 020410, where the Permanent Secretary or Head cannot recommend re-engagement, approval of the Federal Civil Service Commission must be sought before informing the Officer.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-626')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After approval is received not to re-engage a Contract Officer, what must the Permanent Secretary do?','["Inform the Officer without delay","Wait until after retirement","Publish the matter in newspapers first","Ignore the Officer’s request"]'::jsonb,0,'Correct. Under PSR Rule 020410, after receiving approval, the Permanent Secretary or Head of Extra-Ministerial Office must inform the Officer without delay that he will not be re-engaged.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-627')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When will service under a new contract be treated as continuous?','["Where re-engagement is completed by signing a new contract before the end of vacation leave under the expiring contract","Where the Officer signs after five years","Where the Officer gives no notice","Where the Officer refuses to sign"]'::jsonb,0,'Correct. Under PSR Rule 020411, service under a new contract is treated as continuous if re-engagement is completed by signing a new contract before the end of vacation leave granted under the expiring contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-628')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where retired Officers are re-engaged into career posts, on what grade level are they appointed?','["The grade level immediately below that on which they retired","The same grade level plus two levels","Any grade level chosen by the Officer","SGL. 01 only"]'::jsonb,0,'Correct. Under PSR Rule 020412, retired Officers re-engaged into career posts are appointed on the grade level immediately below that on which they retired.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-629')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Retired Officers re-engaged into career posts may maintain what under Rule 020412?','["Their last step at retirement","Automatic pensionable appointment","Promotion without interview","Unlimited contract duration"]'::jsonb,0,'Correct. Under PSR Rule 020412, retired Officers re-engaged into career posts are eligible to maintain their last step at retirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-630')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How is the remuneration of non-Public or non-Civil Servants determined under Rule 020412?','["Based on negotiable terms by the parties concerned","Fixed automatically at Director level","Based only on pension rules","By the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020412, the remuneration of non-Public or non-Civil Servants is based on negotiable terms by the parties concerned.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-631')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is Sabbatical Appointment under Rule 020413?','["Appointment of an Officer on GL. 15 or equivalent and above for research and professional development","Appointment of junior staff on GL. 03 only","A disciplinary suspension","A permanent pensionable promotion"]'::jsonb,0,'Correct. Under PSR Rule 020413, Sabbatical Appointment applies to an Officer on GL. 15 or equivalent and above for research and professional development.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-632')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the duration of Sabbatical Appointment under Rule 020413?','["12 calendar months","Two weeks","Six years","Three working days"]'::jsonb,0,'Correct. Under PSR Rule 020413, Sabbatical Appointment shall be for a period of 12 calendar months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-633')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020414, who pays travel expenses, lodging and sundries during Sabbatical Appointment?','["The host MDA or Organization","The Staff Union","The Officer’s family","The parent MDA only"]'::jsonb,0,'Correct. Under PSR Rule 020414, the host MDA or Organization is responsible for payment of travel expenses, lodging and sundries.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-634')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020414, who continues to pay the Officer’s salary during Sabbatical Appointment?','["The parent MDA or Organization","The Officer personally","The Staff Union","The host MDA only"]'::jsonb,0,'Correct. Under PSR Rule 020414, the parent MDA or Organization continues to pay the Officer’s salary for the duration of the leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-635')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Internship connote under Rule 020415?','["A structured experience related to a student’s or graduate’s discipline or career goal","A disciplinary trial period","A permanent appointment on pensionable terms","A compulsory retirement process"]'::jsonb,0,'Correct. Under PSR Rule 020415, Internship connotes a structured experience related to a student’s or graduate’s discipline or career goal.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-636')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is one purpose of Internship under Rule 020415?','["To facilitate acquisition of practical skills, workplace experience and greater professional knowledge","To replace all regular employment","To provide automatic promotion","To avoid formal training"]'::jsonb,0,'Correct. Under PSR Rule 020415, Internship facilitates acquisition of practical skills, workplace experience and greater knowledge of the profession.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-637')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Volunteerism mean under Rule 020416?','["Offering one’s time or talents for charitable, educational or other worthwhile activities","Receiving automatic pension without service","Refusing public service duties","Compulsory paid employment"]'::jsonb,0,'Correct. Under PSR Rule 020416, Volunteerism denotes offering one’s time or talents for charitable, educational or other worthwhile activities, especially in one’s community.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-638')::uuid,'PSR','Chapter 2: Appointments & Career Progression','According to Rule 020416, volunteers are driven by what?','["Passion to leave a noble legacy of service to humanity","Desire to avoid service","Automatic promotion rights","Compulsory appointment rules"]'::jsonb,0,'Correct. Under PSR Rule 020416, volunteers are driven by passion to leave a noble legacy of service to humanity.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-639')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where is the Focal Office for volunteer programme established under Rule 020417?','["In the OHCSF","In the Staff Union office","In the Officer’s MDA only","In the Pension Fund Administrator office"]'::jsonb,0,'Correct. Under PSR Rule 020417(i), a Focal Office shall be established in the OHCSF to identify fields or tasks available for volunteer programmes and disseminate information.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-640')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What are MDAs required to establish in supportive role for internship and volunteerism under Rule 020417?','["Desks for the two programmes","Disciplinary panels only","Private recruitment agencies","Pension boards"]'::jsonb,0,'Correct. Under PSR Rule 020417(i), MDAs in supportive role are required to establish Desks for the two programmes.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-641')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must the Focal Office upload on the OHCSF website under Rule 020417?','["Skills, benefits, conditions of engagement and requisite qualifications","Personal bank details of applicants","Disciplinary records of Officers","All pension records"]'::jsonb,0,'Correct. Under PSR Rule 020417(ii), the Focal Office uploads skills highlighting benefits and conditions of engagement with requisite qualifications on the OHCSF website.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-642')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How do prospective volunteers apply under Rule 020417?','["In response to advertisement on the OHCSF website","By refusing medical fitness certification","By anonymous letter only","By oral request to colleagues"]'::jsonb,0,'Correct. Under PSR Rule 020417(iii), prospective volunteers with specialty in preferred fields apply for engagement in response to advertisement on the OHCSF website.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-643')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Before engagement, prospective volunteers must obtain which two clearances or certifications?','["Medical fitness by recognized HCP and security clearance from the Police","Approval from a private school and family consent","Annual leave approval and pension clearance","Promotion result and transfer letter"]'::jsonb,0,'Correct. Under PSR Rule 020417(iv), prospective volunteers must be certified medically fit by a recognized Healthcare Provider and obtain security clearance from the Police before engagement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-644')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must interns engaged directly by MDAs submit under Rule 020417?','["Reference letter from their respective institutions","Pension clearance certificate","Retirement notice","Disciplinary query"]'::jsonb,0,'Correct. Under PSR Rule 020417(v), interns to be engaged directly by MDAs shall submit reference letters from their respective institutions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-645')::uuid,'PSR','Chapter 2: Appointments & Career Progression','At the end of internship or volunteer programmes, what should successful candidates receive?','["Letters of commendation","Automatic pensionable appointment","Dismissal letters","Promotion to GL. 17"]'::jsonb,0,'Correct. Under PSR Rule 020417(vii), successful candidates shall be given letters of commendation at the end of the programmes.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-646')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For how long may interns be engaged part-time during an academic session?','["3 to 6 months","12 to 24 months","One week","Two years"]'::jsonb,0,'Correct. Under PSR Rule 020418, interns shall be engaged for 3 to 6 months on part-time during an academic session.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-647')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the maximum full-time internship period under Rule 020418?','["Not more than 12 months","Not more than 4 years","Not more than 6 years","Not more than 3 days"]'::jsonb,0,'Correct. Under PSR Rule 020418, interns may be engaged full-time for a period of not more than 12 months.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-648')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For how long may volunteers be engaged at a time under Rule 020418?','["Maximum of 12 months","Maximum of 5 years","Maximum of 2 weeks","Maximum of 6 years"]'::jsonb,0,'Correct. Under PSR Rule 020418, volunteers shall be engaged for a maximum of 12 months at a time.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-649')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Stipends for Volunteers shall be in accordance with what under Rule 020419?','["The rate contained in the National Volunteering Policy by the Office of the Secretary to the Government of the Federation","The Officer’s private negotiation only","The pension scale for Directors","The Staff Union constitution"]'::jsonb,0,'Correct. Under PSR Rule 020419, stipends for Volunteers shall be in accordance with the rate contained in the National Volunteering Policy by the Office of the Secretary to the Government of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-650')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who is responsible for payment of stipends to Volunteers during their service?','["Host MDAs","The volunteers’ families","The Staff Union","Private employers only"]'::jsonb,0,'Correct. Under PSR Rule 020419, Host MDAs are responsible for payment of stipends to Volunteers during the period of their service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-651')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Stipends paid to interns are at what rate under Rule 020417?','["Rates prescribed by relevant circulars issued from time to time","Rates fixed by the intern personally","Rates used for pensioners only","Rates determined by the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020417(vi), stipends paid to interns shall be at the rates prescribed by relevant circulars issued from time to time.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-652')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who may qualify as interns under Rule 020420?','["Postgraduates, undergraduates or students in other tertiary institutions","Only retired Directors","Only Officers on GL. 17","Only pensioners"]'::jsonb,0,'Correct. Under PSR Rule 020420, interns must be postgraduates, undergraduates or students in other tertiary institutions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-653')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which qualification is listed for volunteers under Rule 020420?','["University Degree, HND, NCE, ND, SSCE or its equivalent","Only PhD in all cases","Only GL. 17 status","Only retirement certificate"]'::jsonb,0,'Correct. Under PSR Rule 020420, volunteers must possess a University Degree, HND, NCE, ND, SSCE or its equivalent.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-654')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020421, which departments or units must be represented in discussions on short-term engagement contracts?','["Human Resources, Finance and Accounts, User Department or Unit, and Legal Unit","Only the Staff Union","Only the Officer’s family","Only the host department clerk"]'::jsonb,0,'Correct. Under PSR Rule 020421(a), Human Resources Management, Finance and Accounts Department, User Department or Unit and Legal Unit must be represented in discussions on short-term engagement contracts.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-655')::uuid,'PSR','Chapter 2: Appointments & Career Progression','At what level must representation be made in the contract-discussion process under Rule 020421?','["Director level","Clerical level only","Intern level only","Volunteer level only"]'::jsonb,0,'Correct. Under PSR Rule 020421(a)(v), representation in the negotiation, drafting and execution of short-term engagement contracts shall be at the level of Director.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-656')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After negotiations for short-term engagement, what document must be issued to the employee?','["A letter of appointment","A query letter","A leave roster","A pension clearance form"]'::jsonb,0,'Correct. Under PSR Rule 020421(b), after negotiations, a letter of appointment shall be issued to the employee.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-657')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The letter of appointment after short-term engagement negotiations must be endorsed by whom?','["The Permanent Secretary or Chief Executive","The Staff Union Chairman","The applicant’s family","The Officer’s colleague"]'::jsonb,0,'Correct. Under PSR Rule 020421(b), the letter of appointment shall be duly endorsed by the Permanent Secretary or Chief Executive.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-658')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must the letter of appointment indicate under Rule 020421?','["The terms of the contract of engagement by the parties","The Officer’s private family history","Only the leave address","Only the medical fitness result"]'::jsonb,0,'Correct. Under PSR Rule 020421(b), the letter of appointment must indicate the terms of the contract of engagement by the parties.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-659')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where is the template of short-term engagement stated to be found?','["Appendix C","Chapter 12 only","Form L.10","Appendix A only"]'::jsonb,0,'Correct. Under PSR Rule 020421, the template of short-term engagement is stated to be in Appendix C.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-660')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 4 of the PSR?','["It regulates short-term engagements including contract appointment, sabbatical appointment, internship, volunteerism, re-engagement, remuneration, tenure, qualifications and legal framework","It deals only with annual leave","It deals only with disciplinary dismissal","It deals only with burial expenses"]'::jsonb,0,'Correct. PSR Chapter 2, Section 4, Rules 020401 to 020421 cover short-term engagements, including Contract Appointment, Sabbatical Appointment, Internship, Volunteerism, re-engagement, remuneration, tenure, qualifications and the legal framework for processing short-term engagements.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-661')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020501, what is transfer?','["The temporary release of an Officer for training only","The permanent release of an Officer from one scheduled Service to another or from one class to another within the same Service","The posting of an Officer within the same unit for one week","The suspension of an Officer from duty"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 5, Rule 020501(a), transfer is the permanent release of an Officer from one scheduled Service to another or from one class to another within the same Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-662')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020501, what is secondment?','["A permanent release from one Service to another","The temporary release of an Officer to another Government approved body or recognized International Organization or body for a specified period","An automatic promotion to a higher grade","A disciplinary removal from office"]'::jsonb,1,'Correct. Under PSR Rule 020501(b), secondment means the temporary release of an Officer to the service of another Government approved body or any recognized International Organization or body for a specified period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-663')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly distinguishes transfer from secondment?','["Transfer is permanent, while secondment is temporary","Transfer is always disciplinary, while secondment is always promotion","Transfer applies only to retired Officers, while secondment applies only to trainees","Transfer and secondment mean exactly the same thing"]'::jsonb,0,'Correct. PSR Rule 020501 defines transfer as permanent release, while secondment is temporary release for a specified period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-664')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Secondment may be to which of the following?','["Another Government approved body or recognized International Organization","Only the Officer’s family business","Only a private club without recognition","Only the Officer’s former school"]'::jsonb,0,'Correct. Under PSR Rule 020501(b), secondment may be to another Government approved body or any recognized International Organization or body.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-665')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who considers applications for transfer or secondment to posts graded GL. 06 and below?','["The appropriate Committee of the benefiting Ministry or Extra-Ministerial Office","The Federal Ministry of Health only","The Staff Union","The Officer’s family"]'::jsonb,0,'Correct. Under PSR Rule 020502(i), applications for transfer or secondment to posts graded GL. 06 and below are considered by the appropriate Committee of the benefiting Ministry or Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-666')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who approves transfer or secondment to posts graded GL. 06 and below?','["The Permanent Secretary or Head of Extra-Ministerial Office","The Officer’s colleague","The Staff Union Chairman","The applicant personally"]'::jsonb,0,'Correct. Under PSR Rule 020502(i), transfer or secondment to posts graded GL. 06 and below is approved by the Permanent Secretary or Head of Extra-Ministerial Office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-667')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who determines applications for transfer or secondment to posts graded GL. 07–10 in any Ministry or Extra-Ministerial Office?','["The Federal Civil Service Commission","The Junior Staff Committee only","The Staff Union","The Officer’s immediate family"]'::jsonb,0,'Correct. Under PSR Rule 020502(ii), applications for transfer or secondment to posts graded GL. 07–10 in any Ministry or Extra-Ministerial Office are determined by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-668')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Officers seeking transfer from scheduled establishments on Salary GL. 07–10 are required to do what?','["Sit for the Annual Competitive Civil Service Entry Examination","Proceed on annual leave first","Resign before applying","Apply only through the Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020502(ii), Officers seeking transfer from scheduled establishments on Salary GL. 07–10 are required to sit for the Annual Competitive Civil Service Entry Examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-669')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best reflects the authority to process transfer or secondment under Rule 020502?','["GL. 06 and below are handled by the benefiting Ministry’s appropriate Committee and approved by the Permanent Secretary or Head; GL. 07–10 are determined by the FCSC","All transfers are approved by the Officer’s supervisor alone","All secondments are approved by the Staff Union","Only the receiving Officer decides the matter"]'::jsonb,0,'Correct. PSR Rule 020502 provides separate processing authorities: GL. 06 and below by the appropriate Committee and Permanent Secretary or Head, while GL. 07–10 are determined by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-670')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What confidential reports must be furnished when processing transfer or secondment?','["Reports covering the last three years, or the whole service if less than three years","Only one month’s attendance sheet","Only the Officer’s leave address","Only the Officer’s medical bill"]'::jsonb,0,'Correct. Under PSR Rule 020503(a), confidential reports covering the last three years, or the whole service if less than three years, must be furnished.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-671')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How is an Officer on transfer from State to Federal Service placed?','["On a grade level lower than his current grade level","On the same grade level automatically","On a grade level higher than his current grade level","On any level chosen by the Officer"]'::jsonb,0,'Correct. Under PSR Rule 020503(b), an Officer on transfer from State to Federal Service shall be placed on a grade level lower than his current grade level.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-672')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Transfer to the Federal Service is limited to which posts?','["Posts graded GL. 07 to 14 or equivalent","Only GL. 01 to 03","Only GL. 17","Only non-pensionable posts"]'::jsonb,0,'Correct. Under PSR Rule 020503(c), transfer to the Federal Service is limited to posts graded GL. 07 to 14 or its equivalent.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-673')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020503, an Officer on transfer or secondment must have what employment status?','["He must have been confirmed","He must still be on probation","He must be dismissed first","He must be retired permanently"]'::jsonb,0,'Correct. Under PSR Rule 020503(d), an Officer on transfer or secondment must have been confirmed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-674')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Besides confirmation, what must align with the Schemes of Service for an Officer on transfer or secondment?','["His qualifications, experience and career progression","His leave address only","His private business interest","His family background"]'::jsonb,0,'Correct. Under PSR Rule 020503(d), the Officer’s qualifications, experience and career progression must be in accordance with the Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-675')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What evidence is required from both releasing and accepting agencies for transfer or secondment?','["Evidence of concurrence","Evidence of annual leave","Evidence of pension payment only","Evidence of political approval"]'::jsonb,0,'Correct. Under PSR Rule 020503(e), there must be evidence of concurrence to the transfer or secondment by the releasing and accepting agencies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-676')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the maximum first-instance period of secondment to another Government, approved body or recognized International Organization?','["Two years","Four years","Six years","Ten years"]'::jsonb,0,'Correct. Under PSR Rule 020503(f), secondment shall be for a maximum period of two years in the first instance.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-677')::uuid,'PSR','Chapter 2: Appointments & Career Progression','After the first-instance period of secondment, what may the Officer do?','["Apply for extension or return to his former post","Automatically remain forever","Become dismissed without review","Convert the secondment to annual leave"]'::jsonb,0,'Correct. Under PSR Rule 020503(f), after the first-instance secondment period, the Officer may apply for extension or return to his former post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-678')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who must approve extensions of secondment under Rule 020503?','["The appropriate Committees and the Federal Civil Service Commission or Board","The Officer’s colleague only","The Staff Union only","The receiving Officer personally"]'::jsonb,0,'Correct. Under PSR Rule 020503(f), all extensions of secondment must be approved by the appropriate Committees and the Federal Civil Service Commission or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-679')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the total maximum period of ordinary secondment under Rule 020503(f)?','["Four years","Two years","Six years","Eight years"]'::jsonb,0,'Correct. Under PSR Rule 020503(f), the total period of such secondment must not exceed four years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-680')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If secondment is in the public interest, what is the maximum period allowed?','["Six years","Four years","Two years","One year"]'::jsonb,0,'Correct. Under PSR Rule 020503(g), where it is in the public interest to second an Officer, the period of secondment shall not exceed six years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-681')::uuid,'PSR','Chapter 2: Appointments & Career Progression','During secondment, what happens to the Officer’s substantive post?','["He continues to hold his substantive post","He automatically loses his substantive post","He is treated as dismissed from his post","His post is converted to casual appointment"]'::jsonb,0,'Correct. Under PSR Rule 020503(h), during the period of secondment the Officer continues to hold his substantive post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-682')::uuid,'PSR','Chapter 2: Appointments & Career Progression','During secondment, the Officer is entitled to what career benefits?','["Increment and promotion","Only burial expenses","Only casual leave","No career benefit at all"]'::jsonb,0,'Correct. Under PSR Rule 020503(h), during the period of secondment the Officer is entitled to increment and promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-683')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How is an Officer on secondment treated under Rule 020503?','["As having been posted on special duty","As dismissed from Service","As absent without leave","As retired from Service"]'::jsonb,0,'Correct. Under PSR Rule 020503(h), an Officer on secondment is treated as having been posted on special duty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-684')::uuid,'PSR','Chapter 2: Appointments & Career Progression','During ordinary secondment, who is responsible for the Officer’s emoluments?','["The benefiting organization","The Officer’s family","The Staff Union","The Officer personally"]'::jsonb,0,'Correct. Under PSR Rule 020504, during secondment the benefiting organization is responsible for the Officer’s emoluments.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-685')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where an Officer is released on secondment in public interest and there is a differential in pay between releasing and receiving MDAs, who pays the salary?','["The MDA with the higher pay","The Officer personally","The Staff Union","The lower-paying MDA automatically"]'::jsonb,0,'Correct. Under PSR Rule 020504, where secondment is in the public interest and there is a differential in payments, the MDA with the higher pay is responsible for payment of salary.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-686')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020504, who pays non-salary allowances during secondment?','["The receiving MDA","The releasing MDA in every case","The Officer’s family","The Staff Union"]'::jsonb,0,'Correct. Under PSR Rule 020504, notwithstanding the salary arrangement, all non-salary allowances shall be paid by the receiving MDA.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-687')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The emoluments and incremental date of an Officer on transfer are governed by which rule?','["Rule 040103","Rule 130401","Rule 120214","Rule 100301"]'::jsonb,0,'Correct. Under PSR Rule 020505, the emoluments and incremental date of an Officer on transfer are governed by Rule 040103.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-688')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020505 deals mainly with what subject?','["Salary on transfer","Medical examination","Disciplinary appeal","Burial expenses"]'::jsonb,0,'Correct. PSR Rule 020505 is titled salary on transfer and provides that the emoluments and incremental date of an Officer on transfer are governed by Rule 040103.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-689')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When may an applicant be considered for transfer-on-promotion to any MDA?','["Only in response to an advertised post","Whenever the applicant requests privately","Without any vacancy or advertisement","Only after retirement"]'::jsonb,0,'Correct. Under PSR Rule 020506, no applicant shall be considered for transfer-on-promotion to any MDA except in response to an advertised post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-690')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement is correct about transfer-on-promotion under Rule 020506?','["It must be in response to an advertised post","It is automatic for all Officers","It requires no vacancy","It is handled only through verbal instruction"]'::jsonb,0,'Correct. PSR Rule 020506 provides that transfer-on-promotion to any MDA is considered only in response to an advertised post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-691')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020507, an applicant may be considered for transfer if the MDA is satisfied that vacancies exist where?','["In the relevant grade and in the applicant’s discipline or area of specialty","Only in the Officer’s preferred office","Only in the Staff Union office","Only in the Officer’s home town"]'::jsonb,0,'Correct. Under PSR Rule 020507(i)(a), the MDA must be satisfied that there are vacancies not only in the relevant grade but also in the applicant’s discipline or area of specialty.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-692')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The contemplated transfer must not jeopardize what under Rule 020507?','["The promotion prospects of serving Officers","The Officer’s private business","The Staff Union election timetable","The Officer’s personal leave address"]'::jsonb,0,'Correct. Under PSR Rule 020507(i)(b), the contemplated transfer must in no way jeopardize the promotion prospects of serving Officers.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-693')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which prior service condition must an applicant satisfy for transfer under Rule 020507?','["He must have been confirmed in his previous service","He must still be on probation","He must have been dismissed previously","He must have no career progression"]'::jsonb,0,'Correct. Under PSR Rule 020507(i)(c), an applicant may be considered for transfer if he has been confirmed in his previous service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-694')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020507, the applicant’s qualifications, experience and career progression must correspond with what?','["The Schemes of Service of the grade or post","The Officer’s private business plan","The Staff Union constitution","The applicant’s family preference"]'::jsonb,0,'Correct. Under PSR Rule 020507(i)(c), the applicant’s qualifications, experience and career progression must be in accordance with the Schemes of Service of the grade or post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-695')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which length-of-service condition applies before an applicant may be considered for transfer under Rule 020507?','["He must have served in his current grade for the stipulated minimum number of years prescribed for promotion to an advertised post","He must have served only one week","He must have served until retirement","He must have no service record"]'::jsonb,0,'Correct. Under PSR Rule 020507(i)(d), an applicant must have served in his current grade for the stipulated minimum number of years prescribed for promotion to an advertised post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-696')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Can a Ministry transfer or second a senior Officer to a Parastatal under its supervision without approval?','["No, approval of the Federal Civil Service Commission or Board is required","Yes, it may do so without approval","Yes, if the Officer verbally agrees","Yes, if the Staff Union requests it"]'::jsonb,0,'Correct. Under PSR Rule 020507(ii), no Ministry shall transfer or second any senior Officer to any Parastatal under its supervision without approval of the Federal Civil Service Commission or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-697')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Can a Ministry accept staff seconded to it without endorsement of the Federal Civil Service Commission or Board?','["No, it cannot accept such staff without endorsement","Yes, endorsement is unnecessary","Yes, if the staff is on annual leave","Yes, if the staff is junior only"]'::jsonb,0,'Correct. Under PSR Rule 020507(iii), no Ministry shall accept any staff seconded to it without the endorsement of the Federal Civil Service Commission or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-698')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who appraises an Officer on secondment?','["The MDA to which he is seconded","The Officer’s former school","The Staff Union only","The Officer’s family"]'::jsonb,0,'Correct. Under PSR Rule 020507, an Officer on secondment shall be appraised by the MDA to which he is seconded.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-699')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises the conditions for transfer under Rule 020507?','["There must be relevant vacancies, no harm to serving Officers’ promotion prospects, confirmation in previous service, appropriate qualifications and required years in current grade","The applicant must be unconfirmed and under discipline","The transfer must always bypass advertisement","The receiving MDA must ignore the Schemes of Service"]'::jsonb,0,'Correct. PSR Rule 020507 requires relevant vacancies, protection of promotion prospects of serving Officers, confirmation in previous service, qualifications and career progression in line with the Schemes of Service, and required years in the current grade.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-700')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How may transfer from one junior post to another within the Federal Public Service be arranged?','["With the consent of the Officers and at the mutual discretion of their Permanent Secretaries or Heads of Extra-Ministerial Offices","By the Officer alone without approval","Only through a newspaper advertisement","By the Staff Union without management approval"]'::jsonb,0,'Correct. Under PSR Rule 020508, transfer from one junior post to another within the Federal Public Service may be arranged with the consent of the Officers concerned and at the mutual discretion of their Permanent Secretaries or Heads of Extra-Ministerial Offices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-701')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020508 applies to which category of transfer?','["Transfer from one junior post to another within the Federal Public Service","Transfer of Permanent Secretaries only","Secondment to international organizations only","Transfer-on-promotion to advertised senior posts only"]'::jsonb,0,'Correct. PSR Rule 020508 specifically deals with transfer from one junior post to another within the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-702')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Whose consent is required for transfer from one junior post to another?','["The Officers being considered for transfer","The Officer’s landlord","The Staff Union Treasurer","The receiving Ministry only"]'::jsonb,0,'Correct. Under PSR Rule 020508, the consent of the Officers being considered for transfer is required.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-703')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What returns must MDAs make under Rule 020509?','["Quarterly returns to the Federal Civil Service Commission and/or OHCSF on staff on transfer or secondment to other Services","Annual burial returns only","Weekly medical treatment returns","Monthly leave allowance returns"]'::jsonb,0,'Correct. Under PSR Rule 020509, MDAs shall make quarterly returns to the Federal Civil Service Commission and/or the Office of the Head of the Civil Service of the Federation on the number of staff on transfer or secondment to other Services.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-704')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How often must MDAs make returns on staff on transfer or secondment to other Services?','["Quarterly","Every ten years","Daily","Only at retirement"]'::jsonb,0,'Correct. Under PSR Rule 020509, MDAs are required to make quarterly returns on staff on transfer or secondment to other Services.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-705')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What must the Federal Civil Service Commission furnish MDAs with on a quarterly basis?','["The approved list of staff seconded or transferred to other Services","The list of Officers on annual leave only","The medical records of all Officers","The list of dismissed Officers only"]'::jsonb,0,'Correct. Under PSR Rule 020509, the Federal Civil Service Commission shall furnish MDAs quarterly with the approved list of staff seconded or transferred to other Services.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-706')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 5 of the PSR?','["It regulates transfer and secondment, including definitions, processing authority, procedures, salary responsibility, transfer-on-promotion, conditions for transfer, junior post transfer and quarterly returns","It deals only with medical treatment abroad","It deals only with annual leave computation","It deals only with disciplinary dismissal"]'::jsonb,0,'Correct. PSR Chapter 2, Section 5, Rules 020501 to 020509 cover transfer and secondment, including definitions, authority to process, procedure, salary responsibility, salary on transfer, transfer-on-promotion, conditions for transfer, transfer on junior posts and quarterly returns.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-707')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020601, what is posting?','["A disciplinary removal from office","The initial assignment of an Officer to a position/job schedule in an MDA or reassignment within or outside his current MDA/Department","A permanent transfer from one scheduled Service to another","A temporary release to an international organization"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 6, Rule 020601, posting is the initial assignment of an Officer to a position/job schedule in an MDA or reassignment to another position/job schedule within or outside his current MDA/Department.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-708')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is one purpose of posting under Rule 020601?','["To help employees gain wide experience on the intricacies of government business","To automatically terminate employment","To replace annual leave entitlement","To avoid performance management"]'::jsonb,0,'Correct. Under PSR Rule 020601, posting helps employees acquaint themselves with activities of various offices and gain wide experience on the intricacies of government business.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-709')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Posting may involve reassignment to another job schedule in which location?','["Only within the Officer’s current Department","Only outside the Federal Public Service","Within or outside the Officer’s current MDA/Department","Only in the Officer’s home town"]'::jsonb,2,'Correct. PSR Rule 020601 provides that posting may be an initial assignment or reassignment within or outside the Officer’s current MDA/Department.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-710')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020602, senior staff may be posted or redeployed in accordance with what?','["The approved Employee Mobility Policy","The Officer’s private preference only","The Staff Union election timetable","The leave roster"]'::jsonb,0,'Correct. Under PSR Rule 020602(i), all senior staff can be posted and/or redeployed to a new post in accordance with the approved Employee Mobility Policy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-711')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020602 say about posting Officers outside their Professional Cadres?','["It is encouraged for all Officers","It is allowed without approval","It is prohibited","It is compulsory every year"]'::jsonb,2,'Correct. Under PSR Rule 020602(ii), posting of Officers to posts outside their Professional Cadres is prohibited.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-712')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How often is posting of pool Officers in the Service mandatory under Rule 020602?','["Every four years","Every month","Every ten years","Only at retirement"]'::jsonb,0,'Correct. Under PSR Rule 020602(iii), posting of pool Officers in the Service shall be mandatory after every four years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-713')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Failure of an Officer to proceed on posting is regarded as what under Rule 020602?','["Annual leave","Misconduct","Promotion","Retirement"]'::jsonb,1,'Correct. Under PSR Rule 020602(iv), failure of an Officer to proceed on posting shall be regarded as misconduct.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-714')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What may happen to Ministries, Extra-Ministerial Departments or Agencies that reject pool Officers deployed to them?','["They may face appropriate sanctions","They are automatically promoted","They receive additional leave allowance","They are exempted from posting policy"]'::jsonb,0,'Correct. Under PSR Rule 020602(iv), Ministries, Extra-Ministerial Departments or Agencies that reject pool Officers deployed to them shall face appropriate sanctions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-715')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises the conditions for posting under Rule 020602?','["Senior staff may be posted under the Employee Mobility Policy, posting outside professional cadres is prohibited, pool Officers are posted every four years, and failure to proceed is misconduct","Only junior Officers may be posted, and posting outside professional cadres is compulsory","Posting is voluntary and cannot attract misconduct","Pool Officers may reject posting without consequence"]'::jsonb,0,'Correct. PSR Rule 020602 sets the conditions for posting: senior staff may be redeployed under the Employee Mobility Policy, posting outside professional cadres is prohibited, pool Officers are posted every four years, and failure to proceed is misconduct.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-716')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What principle must guide implementation of posting decisions under Rule 020603?','["Fairness to all Officers","Favouritism to selected Officers","Use of posting as punishment","Political influence"]'::jsonb,0,'Correct. Under PSR Rule 020603, fairness to all Officers shall be an underlying principle in implementing posting decisions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-717')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Posting decisions must not be used as a tool for what under Rule 020603?','["Coercion, punishment or cronyism","Training and experience","Mobility and exposure","Service improvement"]'::jsonb,0,'Correct. Under PSR Rule 020603, the posting system must not be used as a tool for coercion, punishment or cronyism.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-718')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020603, posting should not result in loss of what in any Department, Division or Unit?','["Institutional memory","Office furniture only","Annual leave forms","Staff Union registers"]'::jsonb,0,'Correct. Under PSR Rule 020603(i), posting should not result in the loss of institutional memory in any Department, Division or Unit.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-719')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Posting should not impair a Department, Division or Unit’s ability to do what?','["Continue to provide quality service to internal and external stakeholders","Stop all Government work","Reject pool Officers","Ignore approved policies"]'::jsonb,0,'Correct. Under PSR Rule 020603(i), posting should not impair the ability of any Department, Division or Unit to continue providing quality service to internal and external stakeholders.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-720')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020603, posting should not result in loss of an employee involved in what kind of project?','["A service-wide project designated as high priority during the lifespan of the project","A private business project","A Staff Union campaign only","A family project"]'::jsonb,0,'Correct. Under PSR Rule 020603(ii), posting should not result in the loss of an employee involved in any service-wide project designated as high priority during the lifespan of the project.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-721')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects the procedure for posting under Rule 020603?','["Posting must be fair and must not be used for coercion, punishment or cronyism","Posting must always punish difficult Officers","Posting must ignore institutional memory","Posting must remove Officers from high-priority projects at all times"]'::jsonb,0,'Correct. PSR Rule 020603 requires fairness in posting decisions and prohibits using posting as a tool for coercion, punishment or cronyism.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-722')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Posting under Rule 020604 is intended to give every employee what opportunity?','["Opportunity to acquire as much whole-service work experience as possible","Opportunity to avoid official responsibility","Opportunity to remain permanently in one schedule","Opportunity to reject all pool postings"]'::jsonb,0,'Correct. Under PSR Rule 020604, posting is to ensure every employee is given the opportunity to acquire as much of the whole-service work experience as possible.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-723')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Posting of pool staff must be done in line with what under Rule 020604?','["The approved Employee Mobility Policy","The Officer’s private preference only","The Staff Union constitution only","The leave computation circular"]'::jsonb,0,'Correct. Under PSR Rule 020604, posting of pool staff shall be done in line with the approved Employee Mobility Policy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-724')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020604 mainly guides posting of which category of staff?','["Pool staff","Retired Officers only","Political appointees only","Contractors only"]'::jsonb,0,'Correct. Under PSR Rule 020604, posting is to guide the posting of pool staff in line with the approved Employee Mobility Policy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-725')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who is expected to submit a report on compliance with posting instructions?','["The Director HR","The Staff Union Chairman","The Officer being posted","The Accountant-General"]'::jsonb,0,'Correct. Under PSR Rule 020605, the Director HR is expected to submit a report on compliance with posting instructions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-726')::uuid,'PSR','Chapter 2: Appointments & Career Progression','To whom should the Director HR submit the report on compliance with posting instructions?','["The relevant pool office","The Officer’s family","The Staff Union Secretariat","The nearest police station"]'::jsonb,0,'Correct. Under PSR Rule 020605, the Director HR submits the report on compliance with posting instructions to the relevant pool office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-727')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Within what period must the Director HR submit the compliance report after release of posting instructions?','["Within three weeks","Within six months","Within one year","Within two days"]'::jsonb,0,'Correct. Under PSR Rule 020605, the Director HR shall submit the report on compliance within three weeks of the release of the posting instruction.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-728')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020606, when may an Officer seek redress over posting?','["Where he believes his movement to another job or location was not done in line with extant rules","Whenever he dislikes any official instruction","Only after retirement","Only when the posting is within the same office"]'::jsonb,0,'Correct. Under PSR Rule 020606, an Officer may seek redress where he is of the opinion that his movement to another job or location was not done in line with extant rules.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-729')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Complaints or grievances on posting instructions must be submitted through what channel?','["Appropriate channel","Social media only","Family elders only","Private newspaper publication"]'::jsonb,0,'Correct. Under PSR Rule 020606, complaints or grievances with respect to posting instructions should be submitted through the appropriate channel.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-730')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Within what period should complaints or grievances on posting instructions be submitted after the posting is released?','["Within three working days","Within three months","Within one year","Within thirty calendar days"]'::jsonb,0,'Correct. Under PSR Rule 020606, complaints or grievances on posting instructions should be submitted through the appropriate channel within three working days of the release of the posting.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-731')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020606?','["An Officer may seek redress, but must complain through appropriate channel within three working days of release of the posting","An Officer may refuse posting indefinitely without complaint","An Officer must complain only through the press","An Officer may wait six months before complaining"]'::jsonb,0,'Correct. Under PSR Rule 020606, an Officer may seek redress on posting where extant rules were not followed, but complaints must be routed through appropriate channel within three working days.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-732')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who bears the cost of entitlements due to an employee whose posting requires a change of duty station?','["The posting MDA","The Officer personally in all cases","The Staff Union","The employee’s previous landlord"]'::jsonb,0,'Correct. Under PSR Rule 020607, the cost of entitlements due to the employee whose posting requires a change of duty station shall be borne by the posting MDA.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-733')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020607 applies where posting requires what?','["A change of duty station","Only a change of office chair","Only a change of salary account","Only a change of leave address"]'::jsonb,0,'Correct. Under PSR Rule 020607, posting entitlements apply where the posting requires a change of duty station.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-734')::uuid,'PSR','Chapter 2: Appointments & Career Progression','An Officer who desires to live and work where his spouse lives may be allowed to do so if what condition is met?','["The Branch of his MDA exists in the spouse’s location and there is a relevant established post at the Branch","The Officer simply refuses all other postings","The spouse requests it from a private employer","The Staff Union automatically approves it"]'::jsonb,0,'Correct. Under PSR Rule 020608, an Officer may be allowed to live and work where his spouse lives if the Branch of his MDA is found in the spouse’s location and there is a relevant established post at that Branch.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-735')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is Government’s responsibility for relocation cost when the posting is at the Officer’s request to spouse’s location?','["Government is not responsible for the cost","Government pays unlimited relocation cost","Government pays only hotel allowance forever","Government pays the spouse’s salary"]'::jsonb,0,'Correct. Under PSR Rule 020608, Government shall not be responsible for the cost of relocating an Officer whose posting is at his request.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-736')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects posting to spouse’s location under Rule 020608?','["It may be allowed if the Officer’s MDA has a Branch and relevant established post in the spouse’s location, but Government does not bear relocation cost if the posting is at the Officer’s request","It is automatic even where no MDA Branch exists","Government must pay all relocation costs in every case","It applies only to retired Officers"]'::jsonb,0,'Correct. PSR Rule 020608 allows spouse-location posting only where the MDA has a Branch and relevant established post in the spouse’s location, and Government does not bear relocation cost where the posting is at the Officer’s request.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-737')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020609, what is the primary responsibility of Federal Government employees?','["To discharge duties assigned by their employer to the Nigerian public in a timely and efficient manner","To engage only in union activities","To refuse legitimate directives","To avoid assigned duties"]'::jsonb,0,'Correct. Under PSR Rule 020609, the primary responsibility of all Federal Government employees is to discharge assigned duties to the Nigerian public in a timely and efficient manner.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-738')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Does involvement in staff union activities remove an Officer’s obligation to obey legitimate directives?','["No, Officers must still comply with extant circulars, the PSR and legitimate directives","Yes, union activities override all official directives","Yes, union executives are exempt from the PSR","Yes, if the Officer is a union member"]'::jsonb,0,'Correct. Under PSR Rule 020609, notwithstanding involvement in staff union activities, Officers remain obligated to comply with extant circulars, the PSR and legitimate directives issued by appropriate authorities.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-739')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following must union executives still obey under Rule 020609?','["Extant circulars, the PSR and legitimate directives issued by appropriate authorities","Only Staff Union rules","Only private instructions","Only family decisions"]'::jsonb,0,'Correct. Under PSR Rule 020609, Officers involved in staff union activities must still comply with extant circulars, the PSR and obey legitimate directives from appropriate authorities.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-740')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020610, Labour Union Executives shall not be posted out of their MDAs until when?','["Until the expiration of their tenure in office","Until after one month of appointment","Until annual leave begins","Until they request promotion"]'::jsonb,0,'Correct. Under PSR Rule 020610, Labour Union Executives shall not be posted out of their MDAs until the expiration of their tenure in office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-741')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which category of Officers is specifically protected from being posted out of their MDAs until tenure expiration?','["Labour Union Executives","All probationary Officers","All retired Officers","All contract staff"]'::jsonb,0,'Correct. Under PSR Rule 020610, Labour Union Executives shall not be posted out of their MDAs until their tenure in office expires.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-742')::uuid,'PSR','Chapter 2: Appointments & Career Progression','At the expiration of tenure, what must a Union Executive member not decline?','["Redeployment, posting or reassignment of schedule of duties","Annual leave allowance","Medical check-up only","Retirement benefits"]'::jsonb,0,'Correct. Under PSR Rule 020611, no Union Executive member at the expiration of tenure shall decline redeployment, posting or reassignment of schedule of duties.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-743')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020611 applies at what point in the Union Executive member’s service as union executive?','["At the expiration of tenure in office","Before taking the oath of secrecy","Before joining the Service","Only after retirement"]'::jsonb,0,'Correct. Under PSR Rule 020611, the rule applies at the expiration of the Union Executive member’s tenure in office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-744')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What tenure limit must Trade Unions and Staff Associations introduce in their Constitutions?','["Two terms","Five terms","Unlimited terms","One term of ten years"]'::jsonb,0,'Correct. Under PSR Rule 020612, Trade Unions and Staff Associations are mandated to introduce a tenure limit of two terms in their Constitutions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-745')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020612, the duration of each union executive tenure shall not be more than what?','["Two years","Four years","Five years","One month"]'::jsonb,0,'Correct. Under PSR Rule 020612, the duration for each tenure shall not be more than two years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-746')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the maximum total period an Officer may serve in an executive position during his Service life?','["Four years","Eight years","Ten years","One year"]'::jsonb,0,'Correct. Under PSR Rule 020612, no Officer shall serve more than a total of four years in executive position during his Service life.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-747')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises Rule 020612?','["Trade Unions and Staff Associations must limit executive tenure to two terms, each not more than two years, and no Officer may serve more than four years in executive position during Service life","Union executives may serve unlimited terms","Each union tenure must be five years","Only retired Officers may serve in union executive positions"]'::jsonb,0,'Correct. PSR Rule 020612 mandates Trade Unions and Staff Associations to introduce a two-term limit, with each tenure not exceeding two years, and no Officer serving more than four years total in executive position during Service life.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-748')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 6 of the PSR?','["It regulates posting of Officers, including definition, conditions, fairness, Employee Mobility Policy, compliance reports, complaints, posting entitlements, spouse-location posting and union executive posting rules","It deals only with recruitment into GL. 07–10","It deals only with confirmation examinations","It regulates only annual leave and maternity leave"]'::jsonb,0,'Correct. PSR Chapter 2, Section 6, Rules 020601 to 020612 cover posting of Officers, including definition, conditions, procedure, guide to posting, Director HR reporting duty, posting complaints, entitlements, spouse-location posting, responsibilities of union executives, posting of union executives, redeployment of past union executives and tenure limits.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-749')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020701, when may an acting appointment be made?','["When an Officer requests promotion","When a Staff Union recommends it","Where it is necessary for a duty post to continue to be filled and no Officer of corresponding substantive rank is available","Whenever a substantive holder takes casual leave"]'::jsonb,2,'Correct. Under PSR Chapter 2, Section 7, Rule 020701, acting appointment may be made where it is necessary for a duty post to continue to be filled and no Officer of corresponding substantive rank is available for posting thereto.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-750')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the minimum status of the duty post contemplated under Rule 020701?','["Not lower than GL. 07","Not lower than SGL. 14","Only GL. 03 and below","Only a trainee post"]'::jsonb,1,'Correct. Under PSR Rule 020701, the duty post must be of a status not lower than SGL. 14 before acting appointment may be considered.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-751')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who must approve an acting appointment under Rule 020701?','["The Officer’s colleague","The Staff Union","The Officer’s family","The Federal Civil Service Commission or Board"]'::jsonb,3,'Correct. Under PSR Rule 020701, acting appointment requires the approval of the Federal Civil Service Commission or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-752')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How is an Officer formally appointed to act under Rule 020701?','["By notice in the gazette","By private verbal instruction only","By social media announcement","By casual leave form"]'::jsonb,0,'Correct. Under PSR Rule 020701, an Officer may be formally appointed by notice in the gazette to act in the duty post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-753')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What duties may an acting Officer assume under Rule 020701?','["Only ceremonial duties","No responsibility at all","Either fully or in part, the duties and responsibilities of the post","Only union duties"]'::jsonb,2,'Correct. Under PSR Rule 020701, the acting Officer may assume either fully or in part the duties and responsibilities of the duty post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-754')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020702, does short absence of a substantive holder automatically justify acting appointment?','["Yes, it always justifies acting appointment","No, short absence alone does not justify acting appointment","Yes, if the Officer is on casual leave","Yes, if the Officer is on sick leave"]'::jsonb,1,'Correct. Under PSR Rule 020702, the mere fact that the substantive holder of a duty post will be absent for a short period, such as casual leave or sick leave, does not in itself justify an acting appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-755')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which example of short absence is mentioned under Rule 020702?','["Retirement after thirty-five years","Court conviction","Promotion examination","Casual leave or sick leave"]'::jsonb,3,'Correct. Under PSR Rule 020702, examples of short absence include casual leave or sick leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-756')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What circumstance may still necessitate acting appointment for a relatively brief period under Rule 020702?','["Compliance with statutory provisions","Personal preference of the acting Officer","Family request of the substantive holder","Staff Union election"]'::jsonb,0,'Correct. Under PSR Rule 020702, circumstances such as compliance with statutory provisions may necessitate an acting appointment for a relatively brief period.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-757')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who decides whether an acting appointment is necessary or desirable in a particular case?','["The substantive holder alone","The Officer’s immediate colleague","The Federal Civil Service Commission or Board","The Staff Union only"]'::jsonb,2,'Correct. Under PSR Rule 020702, the decision whether an acting appointment is necessary or desirable rests with the Federal Civil Service Commission or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-758')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020703, acting appointment is not intended for what purpose?','["To fill a temporarily vacant post","To test the suitability of Officers for promotion","To ensure continuity of official duties","To cover a vacant duty post temporarily"]'::jsonb,1,'Correct. Under PSR Rule 020703, acting appointment is not intended as a means of testing the suitability of Officers for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-759')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Acting appointments will normally be made for what purpose under Rule 020703?','["To reward staff union membership","To replace confirmation examinations","To punish Officers","To fill posts that are temporarily vacant"]'::jsonb,3,'Correct. Under PSR Rule 020703, acting appointments will normally be made only to fill posts that are temporarily vacant.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-760')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020703 say about the duration of acting appointments?','["Their duration should be limited accordingly","They must be permanent","They must last until retirement","They must be unlimited"]'::jsonb,0,'Correct. Under PSR Rule 020703, acting appointments are normally for temporarily vacant posts and their duration should be limited accordingly.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-761')::uuid,'PSR','Chapter 2: Appointments & Career Progression','On which form must recommendations for acting appointment be forwarded to the Federal Civil Service Commission?','["Form L.10","Form Gen. 60","General Form 66","Form FC. 2"]'::jsonb,2,'Correct. Under PSR Rule 020704(a), recommendations for acting appointment must be forwarded to the Federal Civil Service Commission on General Form 66.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-762')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What certificate must accompany a recommendation for acting appointment under Rule 020704?','["A certificate that the acting Officer will assume the full duties and responsibilities of the post","A certificate of annual leave only","A certificate of union membership","A certificate of pension payment"]'::jsonb,0,'Correct. Under PSR Rule 020704(a), the recommendation must include a certificate that the acting Officer will assume the full duties and responsibilities of the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-763')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who gazettes an approved acting appointment under Rule 020704?','["The Staff Union","The Officer’s MDA without approval","The Officer personally","The Federal Civil Service Commission"]'::jsonb,3,'Correct. Under PSR Rule 020704(a), an approved acting appointment shall be gazetted by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-764')::uuid,'PSR','Chapter 2: Appointments & Career Progression','An approved acting appointment shall on no account be backdated beyond what period from the date the Commission receives the recommendation?','["One year","Six months","Two years","Three weeks"]'::jsonb,1,'Correct. Under PSR Rule 020704(a), an approved acting appointment shall not be backdated to a period in excess of six months from the date the Federal Civil Service Commission receives the recommendation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-765')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the normal maximum period of acting appointment under Rule 020704?','["Three months","Six months","One year","Four years"]'::jsonb,2,'Correct. Under PSR Rule 020704(b), the period of acting appointment shall not exceed one year in the normal case.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-766')::uuid,'PSR','Chapter 2: Appointments & Career Progression','In exceptional circumstances, an acting appointment may be extended for what additional period under Rule 020704?','["Another one year","Another five years","Another six months","Indefinitely"]'::jsonb,0,'Correct. Under PSR Rule 020704(b), in exceptional circumstances, acting appointment may be extended for another one year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-767')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises the procedure under Rule 020704?','["Acting appointment is made by verbal instruction only","Acting appointment is unlimited once approved","Acting appointment needs no certificate or gazette","Recommendation is made on General Form 66, must include the required certificate, and approved appointment is gazetted"]'::jsonb,3,'Correct. Under PSR Rule 020704, recommendations are forwarded on General Form 66 with the required certificate, and approved acting appointment is gazetted by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-768')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where is the commencement date of an acting appointment indicated?','["In the gazette notice authorizing the appointment","In the Officer’s private diary","In the annual leave roster","In a Staff Union register"]'::jsonb,1,'Correct. Under PSR Rule 020705, the date on which an acting appointment commences is indicated in the gazette notice authorizing the appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-769')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Normally, what is the gazette date of commencement of an acting appointment?','["The date the Officer applies for promotion","The date the Officer receives salary","The date the acting Officer takes over the duties and responsibilities of the post","The date the Staff Union approves it"]'::jsonb,2,'Correct. Under PSR Rule 020705, the gazette date of commencement will normally be the date on which the acting Officer takes over the duties and responsibilities of the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-770')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where the acting Officer takes over from the substantive holder, the gazette date of commencement will not be earlier than when?','["The date the substantive holder, after handing over, leaves the station or post","The date the acting Officer first joined the Service","The date the Officer’s annual leave starts in another MDA","The date of union nomination"]'::jsonb,0,'Correct. Under PSR Rule 020705(a), where the acting Officer takes over from the substantive holder, the commencement date will not be earlier than the date the substantive holder, after handing over, leaves the station or post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-771')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which situation is listed under Rule 020705 as relevant to commencement where the substantive holder has handed over?','["The substantive holder refuses to hand over","The substantive holder applies for casual leave only","The substantive holder is transferred to a private company","The substantive holder takes over substantively or acts in another post in the same station"]'::jsonb,3,'Correct. Under PSR Rule 020705(b), the gazette date may relate to when the substantive holder takes over substantively or acts in another post in the same station after handing over.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-772')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020705, commencement may also relate to the date the substantive holder does what in the same station?','["Commences vacation leave","Joins a secret society","Applies for retirement benefits","Receives a query"]'::jsonb,1,'Correct. Under PSR Rule 020705(c), the commencement date may relate to when the substantive holder commences vacation leave in the same station, where applicable.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-773')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best reflects Rule 020705?','["The commencement date is always the date of interview","The commencement date is fixed by the Officer alone","The commencement date is indicated in the gazette notice and normally relates to when the acting Officer takes over duties","The commencement date is never gazetted"]'::jsonb,2,'Correct. Under PSR Rule 020705, the commencement date is indicated in the gazette notice and normally corresponds to the date the acting Officer takes over the duties and responsibilities of the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-774')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where is the cessation date of an acting appointment indicated under Rule 020706?','["In the gazette notice reverting the Officer’s appointment","In a Staff Union register only","In the Officer’s private diary","In the annual leave roster"]'::jsonb,0,'Correct. Under PSR Rule 020706, the date on which an acting appointment ceases is indicated in the gazette notice reverting the Officer’s appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-775')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Normally, what is the gazette date of cessation of an acting appointment?','["The date the Officer applied for acting appointment","The date the Officer first joined the Service","The date of confirmation examination","The date the acting Officer relinquishes the duties and responsibilities of the post"]'::jsonb,3,'Correct. Under PSR Rule 020706, the gazette date of cessation will normally be the date on which the acting Officer relinquishes the duties and responsibilities of the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-776')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where the acting Officer hands over to the substantive holder, the cessation date will not normally be later than when?','["The date the substantive holder, before taking over, arrives at the station","The date of the next promotion exercise","The date of the acting Officer’s birthday","The date of casual leave approval"]'::jsonb,1,'Correct. Under PSR Rule 020706(a), where the acting Officer hands over to the substantive holder, the cessation date will not normally be later than the date the substantive holder, before taking over, arrives at the station.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-777')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which event is listed under Rule 020706 as relevant before the substantive holder takes over?','["The substantive holder receives annual allowance only","The substantive holder joins the Staff Union","The substantive holder ceases to hold substantively or acts in another post in the same station","The substantive holder starts a private business"]'::jsonb,2,'Correct. Under PSR Rule 020706(b), the cessation date may relate to when the substantive holder ceases to hold substantively or acts in another post in the same station before taking over.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-778')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020706, cessation may also relate to when the substantive holder does what in the same station?','["Ceases vacation leave","Applies for promotion","Writes a petition","Receives salary"]'::jsonb,0,'Correct. Under PSR Rule 020706(c), the cessation date may relate to when the substantive holder ceases vacation leave in the same station, where applicable.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-779')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Rule 020706?','["Acting appointment ceases only when the Staff Union decides","Acting appointment ceases without gazette notice","Acting appointment ceases only at retirement","Cessation is indicated in the gazette notice reverting the Officer and normally relates to relinquishing the duties of the post"]'::jsonb,3,'Correct. Under PSR Rule 020706, the cessation date is indicated in the gazette notice reverting the Officer and normally corresponds to the date the acting Officer relinquishes the duties and responsibilities of the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-780')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020707, Ministries must notify whom when Officers revert from acting appointment?','["The Officer’s family","The Federal Civil Service Commission","The Staff Union","A private contractor"]'::jsonb,1,'Correct. Under PSR Rule 020707, Ministries are required to notify the Federal Civil Service Commission when Officers revert from acting appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-781')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which form is used to notify the Federal Civil Service Commission when Officers revert from acting appointment?','["Form Gen. 15A","Form L.10","Form Gen. 60","Form FC. 2"]'::jsonb,2,'Correct. Under PSR Rule 020707, notification of reversion from acting appointment is done by completing Form No. Gen. 15A.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-782')::uuid,'PSR','Chapter 2: Appointments & Career Progression','When must Form Gen. 15A be forwarded before cessation of acting appointment?','["Not less than two weeks before cessation","After six months of cessation","Immediately after retirement","Only after promotion"]'::jsonb,0,'Correct. Under PSR Rule 020707, Form No. Gen. 15A must be forwarded not less than two weeks before cessation of the acting appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-783')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020707?','["Ministries notify the Staff Union by casual leave form","Ministries need not notify anyone when acting appointment ends","Ministries notify the FCSC after five years only","Ministries notify the FCSC by Form Gen. 15A not less than two weeks before cessation"]'::jsonb,3,'Correct. Under PSR Rule 020707, Ministries must notify the Federal Civil Service Commission by completing Form Gen. 15A and forwarding it not less than two weeks before cessation of the acting appointment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-784')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020708, does an acting Officer relinquish acting duties merely by proceeding on casual or special leave within Nigeria?','["Yes, always","Only if the leave is one day","No, provided the stated conditions are satisfied","Only if the Officer is a union executive"]'::jsonb,2,'Correct. Under PSR Rule 020708(a), an acting Officer is not regarded as relinquishing acting duties by proceeding on casual or special leave within the country, provided the stated conditions are met.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-785')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For casual or special leave not to amount to relinquishment under Rule 020708, where must the acting Officer spend the leave?','["In Nigeria or on a sea voyage between Nigerian ports","In any foreign country without approval","Only in the substantive holder’s house","Only outside the country"]'::jsonb,0,'Correct. Under PSR Rule 020708(a), the acting Officer must spend such leave in Nigeria or on a sea voyage between Nigerian ports.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-786')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which additional condition applies under Rule 020708(a) for casual or special leave not to amount to relinquishment?','["It must be necessary to appoint another Officer to act","The acting Officer must refuse to resume duty","The acting Officer must apply for promotion","It must not be necessary during such leave to appoint another Officer to act in the duty post"]'::jsonb,3,'Correct. Under PSR Rule 020708(a), casual or special leave will not amount to relinquishment provided it is not necessary during such leave to appoint another Officer to act in the duty post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-787')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where the Head of a Department, Division, Unit or Branch is unavailable for a period spanning one month, who oversees the office?','["The most junior Officer","The Staff Union Chairman","The most senior Officer in the Department or Organization","The Officer’s personal assistant"]'::jsonb,1,'Correct. Under PSR Rule 020708(b), where the Head of a Department, Division, Unit or Branch is unavailable for a period spanning one month, the most senior Officer in the Department or Organization shall oversee the office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-788')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020708(b) applies where the Head of Department, Division, Unit or Branch is unavailable due to what?','["Annual leave or any other approved assignment","Dismissal only","Secret society membership only","Private business only"]'::jsonb,2,'Correct. Under PSR Rule 020708(b), the provision applies where the Head is unavailable for a period spanning one month as a result of annual leave or any other approved assignment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-789')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What period of unavailability triggers the arrangement under Rule 020708(b)?','["A period spanning one month","A period of one hour","A period of one day","A period of one week"]'::jsonb,0,'Correct. Under PSR Rule 020708(b), where the Head of Department, Division, Unit or Branch is unavailable for a period spanning one month, the most senior Officer shall oversee the office.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-790')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 7 of the PSR?','["It deals only with annual leave","It deals only with transfer and secondment","It deals only with recruitment of junior staff","It regulates acting appointment, including when it is made, approval, gazetting, procedure, commencement, cessation, FCSC notification and the effect of casual or special leave"]'::jsonb,3,'Correct. PSR Chapter 2, Section 7, Rules 020701 to 020708 regulate acting appointment, including when it may be made, when it is not justified, procedure, commencement, cessation, notification to the Federal Civil Service Commission and the effect of casual or special leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-791')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020801, promotion to all posts in the Federal Civil Service, except Permanent Secretaries, is vested in which authority?','["The Office of the Accountant-General of the Federation","The Federal Civil Service Commission","The Staff Union","The Ministry of Finance"]'::jsonb,1,'Correct. Under PSR Chapter 2, Section 8, Rule 020801, promotion to all posts in the Federal Civil Service, other than those of Permanent Secretaries, is vested in the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-792')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which post is expressly excluded from the general promotion authority stated in Rule 020801(a)?','["Permanent Secretaries","Clerical Officers","Executive Officers","Technical Officers"]'::jsonb,0,'Correct. PSR Rule 020801(a) states that promotion to all posts other than those of Permanent Secretaries is vested in the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-793')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020801(b), Permanent Secretaries and Heads of Extra-Ministerial Offices may promote eligible candidates to which delegated posts?','["All posts up to GL. 17","Only political posts","Posts on SGL 06 or its equivalent and below","Only Permanent Secretary posts"]'::jsonb,2,'Correct. Under PSR Rule 020801(b), Permanent Secretaries and Heads of Extra-Ministerial Offices may promote eligible candidates to delegated posts on SGL 06 or its equivalent and below.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-794')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Promotion by Permanent Secretaries or Heads of Extra-Ministerial Offices under Rule 020801(b) must be based on what?','["Private recommendation of the Officer","Recommendation of the appropriate committee","Verbal approval of colleagues","Personal request by the candidate"]'::jsonb,1,'Correct. Under PSR Rule 020801(b), promotion to delegated posts on SGL 06 or equivalent and below is based on the recommendation of the appropriate committee.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-795')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Except where powers have been delegated, when does a promotion become effective under Rule 020802(a)?','["When the Officer applies for it","When the Staff Union supports it","When the Officer resumes work","When approved by the Federal Civil Service Commission"]'::jsonb,3,'Correct. Under PSR Rule 020802(a), except where powers of appointment or promotion have been delegated, no promotion becomes effective until approved by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-796')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020802(b), which Officers within the field of selection shall not be considered for promotion?','["Officers under disciplinary action","Officers with good performance records","Officers who meet eligibility requirements","Officers who are due for promotion"]'::jsonb,0,'Correct. Under PSR Rule 020802(b), all Officers within the field of selection shall be considered except those who are under disciplinary action.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-797')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the minimum number of years in post for Officers on GL. 06 and below before promotion consideration under Rule 020802(c)?','["Minimum of 4 years","Minimum of 3 years","Minimum of 2 years","Minimum of 5 years"]'::jsonb,2,'Correct. Under PSR Rule 020802(c), Officers on GL. 06 and below must spend a minimum of 2 years in post before being considered eligible for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-798')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the minimum number of years in post for Officers on GL. 07–14 before promotion consideration under Rule 020802(c)?','["Minimum of 2 years","Minimum of 3 years","Minimum of 5 years","Minimum of 1 year"]'::jsonb,1,'Correct. Under PSR Rule 020802(c), Officers on GL. 07–14 must spend a minimum of 3 years in post before being considered eligible for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-799')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the minimum number of years in post for Officers on GL. 15–17 before promotion consideration under Rule 020802(c)?','["Minimum of 2 years","Minimum of 3 years","Minimum of 1 year","Minimum of 4 years"]'::jsonb,3,'Correct. Under PSR Rule 020802(c), Officers on GL. 15–17 must spend a minimum of 4 years in post before being considered eligible for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-800')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Promotion under Rule 020802(d) must be made strictly on what basis?','["Competitive merit","Personal friendship","Length of annual leave","Political influence"]'::jsonb,0,'Correct. Under PSR Rule 020802(d), promotion shall be made strictly on the basis of competitive merit from among all eligible candidates.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-801')::uuid,'PSR','Chapter 2: Appointments & Career Progression','In assessing merit under Rule 020802(d), what distinction must be made?','["Between salary and pension only","Between lower-grade performance or efficiency and potential for the higher post","Between married and unmarried Officers","Between Officers who live near and far from office"]'::jsonb,1,'Correct. Under PSR Rule 020802(d)(i), a clear distinction must be made between records of performance or efficiency in lower grades and potential to perform higher duties efficiently.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-802')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020802(d), seniority and previous performance records are used especially when candidates have what?','["No qualification at all","No vacancy available","Equal potential for promotion","No appraisal record"]'::jsonb,2,'Correct. Under PSR Rule 020802(d)(ii), seniority and previous records of performance are taken into account in choosing between candidates with equal potential for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-803')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which conduct requirement is considered in all promotion cases under Rule 020802(d)?','["Ability to travel abroad","Political endorsement","Length of casual leave","A generally satisfactory record of conduct"]'::jsonb,3,'Correct. Under PSR Rule 020802(d)(iii), a generally satisfactory record of conduct shall be considered in all promotion cases.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-804')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who is responsible for promotion of Officers into GL. 06 or its equivalent and below under Rule 020802(e)?','["The National Assembly","The Ministry, Department and Agency","The Officer personally","The Pension Fund Administrator"]'::jsonb,1,'Correct. Under PSR Rule 020802(e)(i), promotion into GL. 06 or its equivalent and below is by the Ministry, Department and Agency.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-805')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Promotion into GL. 07 to SGL 14 is handled by the Ministry or relevant staff pool with whose approval, subject to confirmation by the FCSC or Board?','["The Staff Union Chairman","The Accountant-General","The Head of the Civil Service of the Federation","The Officer’s immediate supervisor"]'::jsonb,2,'Correct. Under PSR Rule 020802(e)(ii), promotion into GL. 07 to SGL 14 is by the Ministry or relevant staff pool with approval of the Head of the Civil Service of the Federation, subject to confirmation by the FCSC or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-806')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Promotion into GL. 15–17 is by the Federal Civil Service Commission on recommendation routed through which office or authority?','["The Office of the Head of the Civil Service of the Federation or Board","The Staff Union Secretariat","The Officer’s Department only","The Pension Fund Administrator"]'::jsonb,0,'Correct. Under PSR Rule 020802(e)(iii), promotion into GL. 15–17 is by the Federal Civil Service Commission on recommendation routed through the OHCSF or Board.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-807')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020802(f), all promotion is subject to minimum requirements and what else?','["The Officer’s private request","The Staff Union’s endorsement","Automatic appointment","Availability of vacancies"]'::jsonb,3,'Correct. Under PSR Rule 020802(f), all promotion is subject to satisfying minimum requirements declared by the FCSC or Board and to availability of vacancies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-808')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Before enlisting Officers for promotion examination, Heads of MDAs must submit their approved establishment for the year to whom?','["The Officer’s union branch","The Office of the Head of the Civil Service of the Federation","The nearest training school","The Federal Ministry of Health"]'::jsonb,1,'Correct. Under PSR Rule 020802(g), Heads of MDAs must submit their approved establishment for the year to the OHCSF before enlisting Officers for promotion examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-809')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Why must Heads of MDAs submit their approved establishment before promotion examination under Rule 020802(g)?','["To determine annual leave balances","To replace performance appraisal","To ensure promotion falls in line with existing vacancies","To avoid using the Schemes of Service"]'::jsonb,2,'Correct. Under PSR Rule 020802(g), approved establishment is submitted before promotion examination to ensure that promotion falls in line with existing vacancies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-810')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects eligibility under Rule 020802(b)?','["All Officers in the field of selection are considered except those under disciplinary action","Only Officers under disciplinary action are considered","Only Officers on leave are considered","Only contract Officers are considered"]'::jsonb,0,'Correct. PSR Rule 020802(b) provides that all Officers in the field of selection shall be considered except those under disciplinary action.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-811')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Before each promotion exercise, what must the appropriate Office compile under Rule 020803?','["A list of all eligible candidates to be considered","A list of all retired Officers only","A list of disciplinary cases only","A list of private contractors"]'::jsonb,0,'Correct. Under PSR Rule 020803, before each promotion exercise, the appropriate Office shall compile a list of all eligible candidates to be considered.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-812')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The list of eligible candidates under Rule 020803 is prepared on what basis?','["The Officer’s family background","The Staff Union register","Job requirements or criteria established for the post","The Officer’s place of residence"]'::jsonb,2,'Correct. Under PSR Rule 020803, the list is prepared on the basis of job requirements or set criteria established for the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-813')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who establishes the job requirements or criteria for the post under Rule 020803?','["The Officer’s colleague","The Staff Union","The Pension Fund Administrator","The Office of the Head of the Civil Service of the Federation"]'::jsonb,3,'Correct. Under PSR Rule 020803, the job requirements or criteria for the post are established by the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-814')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following is listed as an example of criteria under Rule 020803?','["Qualification, experience, age, training and performance","Marital status only","Personal friendship only","Private business interest"]'::jsonb,0,'Correct. Under PSR Rule 020803, examples of criteria include qualification, experience, age, training and performance as contained in the Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-815')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The promotion criteria under Rule 020803 must be as contained in what document?','["The Officer’s private diary","The Schemes of Service","A newspaper publication","A Staff Union register"]'::jsonb,1,'Correct. Under PSR Rule 020803, the criteria for promotion are those contained in the Schemes of Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-816')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What type of training is required for career progression under Rule 020803(a)?','["Unstructured private coaching only","No training is required","Structured and sustained training","Only political orientation"]'::jsonb,2,'Correct. Under PSR Rule 020803(a), there shall be structured and sustained training for career progression in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-817')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Structured and sustained training under Rule 020803 includes what?','["Compulsory annual leave only","Private social activities only","Disciplinary suspension","Continuous professional training and development"]'::jsonb,3,'Correct. Under PSR Rule 020803(a), structured and sustained training includes continuous professional training and development.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-818')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Officers qualify for promotion to a higher grade after acquiring what under Rule 020803(b)?','["Political endorsement only","Skill and competence provided in the Schemes of Service for the cadre","Only seniority without competence","Only a request letter"]'::jsonb,1,'Correct. Under PSR Rule 020803(b), Officers qualify for promotion after acquiring the skill and competence provided in the Schemes of Service for the particular cadre.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-819')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020803, who compiles the list of eligible candidates before promotion exercise?','["The appropriate Office","The Officer’s family","The Staff Union Chairman","A private consultant"]'::jsonb,0,'Correct. Under PSR Rule 020803, the appropriate Office compiles the list of all eligible candidates before each promotion exercise.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-820')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020804, who interviews and considers Officers holding junior appointments for promotion from junior to senior post?','["The Officer’s family","The Staff Union","The Pension Fund Administrator","The appropriate committee"]'::jsonb,3,'Correct. Under PSR Rule 020804, the appropriate committee meets to interview and consider Officers holding junior appointments who may be recommended for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-821')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Officers holding junior appointments may be recommended to which body under Rule 020804?','["The Federal Civil Service Commission","The Staff Union Secretariat","The Officer’s private employer","The National Pension Commission"]'::jsonb,0,'Correct. Under PSR Rule 020804, Officers holding junior appointments may be recommended to the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-822')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does the Federal Civil Service Commission do after receiving recommendations under Rule 020804?','["It automatically rejects all junior Officers","It sends them for annual leave only","It examines suitability and offers promotion to existing vacancies","It refers them to private employers"]'::jsonb,2,'Correct. Under PSR Rule 020804, the Federal Civil Service Commission examines the suitability of recommended Officers and offers them promotion to existing vacancies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-823')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020805, vacancies on GL. 06 and below are filled by Permanent Secretaries or Heads of Extra-Ministerial Offices on whose recommendation?','["The Minister’s driver","The Junior Staff Committee","The Officer’s family","The Staff Union only"]'::jsonb,1,'Correct. Under PSR Rule 020805, Permanent Secretaries and Heads of Extra-Ministerial Offices fill vacancies on GL. 06 and below on the recommendation of the Junior Staff Committee.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-824')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020805 applies to vacancies on which grade level range?','["GL. 15–17 only","GL. 07–14 only","Permanent Secretary posts only","GL. 06 and below"]'::jsonb,3,'Correct. Under PSR Rule 020805, vacancies on posts on GL. 06 and below are filled on the recommendation of the Junior Staff Committee.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-825')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which committee recommends the filling of vacancies from one junior post to another under Rule 020805?','["Junior Staff Committee","Senior Staff Committee","Medical Board","Procurement Planning Committee"]'::jsonb,0,'Correct. Under PSR Rule 020805, vacancies on GL. 06 and below are filled on the recommendation of the Junior Staff Committee.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-826')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020806, what is the effective date of all promotions?','["The date the Officer submits an application","The date of the interview only","1st January of the year for which the promotion exercise was conducted or as determined by the FCSC","The Officer’s birthday"]'::jsonb,2,'Correct. Under PSR Rule 020806, the effective date of all promotions is 1st January of the year for which the promotion exercise was conducted or as may be determined by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-827')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who may determine an effective date different from 1st January under Rule 020806?','["The Federal Civil Service Commission","The Officer’s supervisor","The Staff Union","The Pension Fund Administrator"]'::jsonb,0,'Correct. Under PSR Rule 020806, the effective date is 1st January of the promotion exercise year or as may be determined by the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-828')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020806?','["Promotion takes effect only on the Officer’s birthday","Promotion takes effect on 1st January of the relevant promotion exercise year or as determined by the FCSC","Promotion takes effect only after retirement","Promotion takes effect whenever the Officer chooses"]'::jsonb,1,'Correct. PSR Rule 020806 provides that the effective date of all promotions shall be 1st January of the year for which the promotion exercise was conducted or as determined by the FCSC.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-829')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020807, Officers on approved leave of absence, secondment, approved study leave or special assignment shall sit for promotion interviews or examinations where?','["Only at their original headquarters","Only abroad","Only after returning from the assignment","At designated centres nearest to them"]'::jsonb,3,'Correct. Under PSR Rule 020807, such Officers shall sit for promotion interviews or examinations at designated centres nearest to them.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-830')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which category of Officers is covered by Rule 020807?','["Officers on approved leave of absence, secondment, approved study leave or special assignment","Only Officers under disciplinary action","Only dismissed Officers","Only contract Officers"]'::jsonb,1,'Correct. PSR Rule 020807 covers Officers on approved leave of absence, secondment, approved study leave or special assignment.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-831')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020807 require of eligible Officers on approved absence or assignment?','["They are automatically exempted from promotion examination","They must resign before promotion","They shall sit for promotion interviews or examinations at designated centres nearest to them","They may be promoted without any process"]'::jsonb,2,'Correct. Under PSR Rule 020807, Officers on approved leave of absence, secondment, approved study leave or special assignment shall sit for promotion interviews or examinations at designated centres nearest to them.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-832')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020808, a newly recruited Officer who has spent how long may sit for compulsory confirmation examination?','["Six months and above","One week only","Three years only","Ten years"]'::jsonb,0,'Correct. Under PSR Rule 020808, a newly recruited Officer who has spent six months and above shall be allowed to sit for compulsory examination for confirmation in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-833')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The compulsory confirmation examination under Rule 020808 is allowed pending completion of what period?','["Three months of casual leave","One year of acting appointment","Four years of secondment","Probationary period of two years"]'::jsonb,3,'Correct. Under PSR Rule 020808, the Officer may sit for the examination pending completion of the probationary period of two years in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-834')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What examination may a newly recruited Officer sit for after six months and above under Rule 020808?','["Promotion interview only","Compulsory examination for confirmation","Medical Board examination only","Procurement examination only"]'::jsonb,1,'Correct. Under PSR Rule 020808, a newly recruited Officer who has spent six months and above may sit for compulsory examination for confirmation in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-835')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020809, may a contract Officer be considered for promotion?','["Yes, automatically every year","Yes, after six months only","No, a contract Officer shall not be considered for promotion","Yes, if the Staff Union recommends him"]'::jsonb,2,'Correct. Under PSR Rule 020809, no contract Officer shall be considered for promotion.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-836')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Although a contract Officer is not considered for promotion, what may he be considered for under Rule 020809?','["Automatic pensionable appointment","Compulsory retirement","Annual leave only","Enhanced appointment during re-negotiation of his contract"]'::jsonb,3,'Correct. Under PSR Rule 020809, a contract Officer may be considered for enhanced appointment during the re-negotiation of his contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-837')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020809?','["A contract Officer may be considered for enhanced appointment during contract re-negotiation, but not promotion","A contract Officer must be promoted annually","A contract Officer is automatically converted to Permanent Secretary","A contract Officer cannot have contract terms reviewed"]'::jsonb,0,'Correct. PSR Rule 020809 provides that no contract Officer shall be considered for promotion, but he may be considered for enhanced appointment during re-negotiation of his contract.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-838')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020810, promotion of junior and senior Officers in Federal Government Parastatals or Agencies is invalid without whose representatives?','["The Staff Union and Pension Fund Administrator","Human Resource Management of the supervising Ministry and OHCSF","The Officer’s family and private employer","The Accountant-General and Auditor-General"]'::jsonb,1,'Correct. Under PSR Rule 020810, promotion of junior and senior Officers in Federal Government Parastatals or Agencies is invalid without representatives of the Human Resource Management of the supervising Ministry and OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-839')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020810 applies to promotion of which Officers in Federal Government Parastatals or Agencies?','["Only retired Officers","Only contract staff","Only Permanent Secretaries","Junior and senior Officers"]'::jsonb,3,'Correct. Under PSR Rule 020810, the rule applies to promotion of both junior and senior Officers in Federal Government Parastatals or Agencies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-840')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Promotion under Rule 020810 concerns which type of organization?','["Federal Government Parastatals or Agencies","Private family businesses","Foreign embassies only","Staff Union branches"]'::jsonb,2,'Correct. Under PSR Rule 020810, the validity requirement applies to promotion in Federal Government Parastatals or Agencies.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-841')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020810?','["Promotion in Federal Government Parastatals or Agencies is deemed invalid without HRM representatives of the supervising Ministry and OHCSF","Promotion in Parastatals is valid without any representative","Only the Officer’s family validates promotion","Promotion in Parastatals is not covered by the PSR"]'::jsonb,0,'Correct. PSR Rule 020810 states that promotion of junior and senior Officers in Federal Government Parastatals or Agencies is invalid without representatives of the HRM of the supervising Ministry and OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-842')::uuid,'PSR','Chapter 2: Appointments & Career Progression','To be eligible for the Permanent Secretary appointment process, a candidate must be what grade and stream under Rule 020811(a)?','["GL. 06 Officer in a junior cadre","GL. 12 Officer in any agency","Director on GL. 17 in the mainstream of the Federal Civil Service","Contract Officer on special appointment"]'::jsonb,2,'Correct. Under PSR Rule 020811(a), the candidate must be a Director on GL. 17 and in the mainstream of the Federal Civil Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-843')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020811(b), the candidate must be verified on IPPIS as having what status?','["Unconfirmed trainee status","Confirmed staff of the Federal Government of Nigeria","Retired consultant status","Private-sector employee status"]'::jsonb,1,'Correct. Under PSR Rule 020811(b), the candidate must have been verified on the IPPIS portal or platform as confirmed staff of the Federal Government of Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-844')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How long must a candidate have been on the post of Director to qualify under Rule 020811(c)?','["At least two years","At least six months","At least ten years","At least one month"]'::jsonb,0,'Correct. Under PSR Rule 020811(c), a candidate must be at least two years on the post of Director.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-845')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020811(d), which retirement condition affects eligibility for the Permanent Secretary appointment process?','["The candidate must be retiring immediately","The candidate must have already retired","The candidate must be on terminal leave","The candidate must not be retiring on or before 31st December of the following year"]'::jsonb,3,'Correct. Under PSR Rule 020811(d), the candidate must not be retiring on or before 31st December of the following year.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-846')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What proof must a candidate provide under Rule 020811(e)?','["Proof of annual leave","Proof of indigeneship of the State where vacancy exists","Proof of private employment","Proof of membership of a Staff Union"]'::jsonb,1,'Correct. Under PSR Rule 020811(e), the candidate must provide proof of indigeneship of the State where the vacancy exists.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-847')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For a female Civil Servant, indigeneship of a State under Rule 020811(f) must not be by what?','["Birth","Residence","Marriage","Posting"]'::jsonb,2,'Correct. Under PSR Rule 020811(f), indigeneship of a State must not be by marriage in the case of a female Civil Servant.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-848')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which disciplinary condition applies under Rule 020811(g)?','["The candidate must not have a pending disciplinary action","The candidate must be under disciplinary action","The candidate must have been dismissed before","The candidate must have refused promotion examination"]'::jsonb,0,'Correct. Under PSR Rule 020811(g), the candidate must not have a pending disciplinary action against him.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-849')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which option best lists key eligibility criteria for Permanent Secretary appointment under Rule 020811?','["Contract status, private employment and annual leave","Union office, overseas posting and medical leave","Junior post, unpaid appointment and acting allowance","GL. 17 Director in mainstream Federal Civil Service, confirmed on IPPIS, two years as Director, required indigeneship, and no pending disciplinary action"]'::jsonb,3,'Correct. Under PSR Rule 020811, eligibility includes being a GL. 17 Director in the mainstream Federal Civil Service, IPPIS-confirmed, at least two years as Director, proof of indigeneship where vacancy exists, and no pending disciplinary action.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-850')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020811 sets eligibility criteria for participation in what process?','["Appointment process of Permanent Secretaries","Annual leave approval process","Medical treatment abroad process","Contract termination process"]'::jsonb,0,'Correct. PSR Rule 020811 sets the eligibility criteria for participating in the appointment process of Permanent Secretaries in the Federal Civil Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-851')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020811, the candidate for Permanent Secretary must be a Director in which Service?','["The mainstream of the Federal Civil Service","The private sector only","A State-owned enterprise only","A foreign mission only"]'::jsonb,0,'Correct. Under PSR Rule 020811(a), the candidate must be a Director on GL. 17 in the mainstream of the Federal Civil Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-852')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020812, selection for Permanent Secretary shall be through what type of process?','["Private nomination only","Automatic seniority only","Competitive examination process","Staff Union voting"]'::jsonb,2,'Correct. Under PSR Rule 020812, selection shall be through a competitive examination process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-853')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which assessment is specifically included in the selection process under Rule 020812?','["Written examination","Medical Board hearing only","Annual leave interview only","Retirement clearance only"]'::jsonb,0,'Correct. Under PSR Rule 020812, the competitive examination process includes written examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-854')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020812 includes a test of what proficiency?','["Driving proficiency","ICT proficiency","Sports proficiency","Accounting payment proficiency"]'::jsonb,1,'Correct. Under PSR Rule 020812, the competitive examination process includes a test of ICT proficiency.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-855')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following is included in the selection process under Rule 020812?','["Private family interview only","Staff Union endorsement only","Automatic appointment without assessment","Oral interview"]'::jsonb,3,'Correct. Under PSR Rule 020812, the competitive examination process includes oral interview.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-856')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best reflects the phrase “including but not limited to” in Rule 020812?','["The process may include written examination, ICT proficiency test, oral interview and other relevant assessments","The process is limited to Staff Union approval","The process excludes written examination","The process is only a medical check"]'::jsonb,0,'Correct. Under PSR Rule 020812, selection is through a competitive examination process including but not limited to written examination, test of ICT proficiency and oral interview.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-857')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020813, resource persons may come from which sources?','["Only the Officer’s family","Only foreign missions","Civil or Public Service and private institutions","Only the Staff Union"]'::jsonb,2,'Correct. Under PSR Rule 020813, resource persons from the Civil or Public Service and private institutions may be involved in the selection process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-858')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Resource persons under Rule 020813 may be involved in what?','["The selection process","The Officer’s annual leave only","Burial expense approval","Medical insurance claims"]'::jsonb,0,'Correct. Under PSR Rule 020813, resource persons from the Civil or Public Service and private institutions may be involved in the selection process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-859')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 8 of the PSR?','["It deals only with annual leave and maternity leave","It regulates medical treatment and burial expenses only","It applies only to disciplinary dismissal","It regulates promotion authority, eligibility, merit criteria, promotion procedures, effective date, approved-absence examination arrangements, contract Officers, parastatal promotion validity and Permanent Secretary selection criteria"]'::jsonb,3,'Correct. PSR Chapter 2, Section 8, Rules 020801 to 020813 cover promotion authority, eligibility, merit criteria, procedure, promotion from junior to senior posts, effective date, Officers on approved absence, contract Officers, parastatal promotion validity and Permanent Secretary selection criteria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-860')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020901, when may the appointment of an Officer on probation be terminated?','["Only after thirty-five years of service","When the appointing authority is satisfied that the Officer is not qualified for efficient service","Only when the Officer applies for annual leave","Only after promotion examination"]'::jsonb,1,'Correct. Under PSR Rule 020901, if within the probationary period the appointing authority is satisfied that an Officer is not qualified for efficient service, the appointment may be terminated.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-861')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who may terminate the appointment of an Officer on probation under Rule 020901?','["The Officer’s colleague","The Staff Union Chairman","The authority empowered to appoint the Officer","The Officer’s family"]'::jsonb,2,'Correct. Under PSR Rule 020901, the authority empowered to appoint the Officer may terminate the appointment during probation where the stated condition is met.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-862')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What compensation is generally available to a probationary Officer whose appointment is terminated under Rule 020901?','["Free transport to the place from which he was engaged, subject to good conduct","Automatic pension","Promotion arrears","Two years’ salary"]'::jsonb,0,'Correct. Under PSR Rule 020901, the Officer receives no further compensation than free transport to the place from which he was engaged, and this is granted only if his conduct has been good.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-863')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Free transport under Rule 020901 is granted only if what condition is satisfied?','["The Officer has served for 35 years","The Officer has been promoted","The Officer’s conduct has been good","The Officer requests transfer"]'::jsonb,2,'Correct. Under PSR Rule 020901, free transport is granted only where the Officer’s conduct has been good.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-864')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If termination of a probationary appointment is not due to misconduct, how is it effected under Rule 020901?','["By immediate dismissal without notice","By one month’s notice","By compulsory retirement at age 60","By transfer to another MDA"]'::jsonb,1,'Correct. Under PSR Rule 020901, where termination is not due to misconduct, it is effected by one month’s notice.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-865')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020901, what may be granted to an eligible probationary Officer in respect of service to date?','["Vacation leave","Automatic sabbatical leave","Permanent Secretary appointment","Promotion arrears"]'::jsonb,0,'Correct. Under PSR Rule 020901, if the Officer is eligible for vacation leave in respect of service to date, such leave may be granted.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-866')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How should leave granted under Rule 020901 be arranged where possible?','["To begin after retirement only","To be forfeited immediately","To take place within the period of notice and, if possible, expire on the same day as the notice","To be accumulated for the next year"]'::jsonb,2,'Correct. Under PSR Rule 020901, leave granted in this situation should be arranged within the notice period and, if possible, expire on the same day as the notice.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-867')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020901, what governs the refund of the cost of training given to the Officer?','["The bond relating to the training","The Staff Union constitution","The Officer’s leave roster","The pension certificate"]'::jsonb,0,'Correct. PSR Rule 020901 states that refund of the cost of any training given to the Officer is governed by the bond relating to such training.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-868')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best reflects termination during probation under Rule 020901?','["It is always treated as promotion","It may occur where the appointing authority is satisfied that the Officer is not qualified for efficient service","It can only be approved by the Officer himself","It always attracts full pension"]'::jsonb,1,'Correct. PSR Rule 020901 allows termination during probation where the appointing authority is satisfied that the Officer is not qualified for efficient service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-869')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020902, what may an Officer who relinquishes appointment during probation be required to refund?','["Annual leave allowance only","Government expenditure on transporting his family, servant and baggage to and from the place of employment","Promotion examination fees only","Medical check-up allowance"]'::jsonb,1,'Correct. Under PSR Rule 020902, an Officer who relinquishes appointment during probation may be required to refund Government expenditure on transporting his family, servant and baggage to and from the place where he was employed.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-870')::uuid,'PSR','Chapter 2: Appointments & Career Progression','An Officer who relinquishes appointment during probation is not eligible for what under Rule 020902?','["Government transport facilities from the station where he was serving","Salary already earned","Staff identity card before assumption of duty","Promotion to Permanent Secretary"]'::jsonb,0,'Correct. Under PSR Rule 020902, the Officer will not be eligible for any facilities from Government towards transport from the station where he was serving.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-871')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020902 applies to relinquishment of appointment during which period?','["After compulsory retirement","During probationary service","After serving as Director for eight years","After dismissal"]'::jsonb,1,'Correct. PSR Rule 020902 applies where an Officer relinquishes his appointment within the period of probationary service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-872')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020902, refund of training cost is governed by what?','["The bond relating to such training","The Officer’s annual leave address","The Staff Union decision","The pension desk officer’s attestation"]'::jsonb,0,'Correct. Under PSR Rule 020902, refund of the cost of any training given to the Officer is governed by the bond relating to such training.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-873')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly describes the transport consequence under Rule 020902?','["The Officer is automatically entitled to free transport after relinquishment","The Officer may be required to refund Government transport expenditure and is not eligible for further Government transport facilities from the station","The Officer receives international passage for his family","The Officer receives transport grant for four years"]'::jsonb,1,'Correct. PSR Rule 020902 provides that an Officer who relinquishes appointment during probation may refund Government transport expenditure and is not eligible for Government transport facilities from the station of service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-874')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020903, what may happen to a probationary Officer who fails to secure confirmation in the pensionable establishment?','["His appointment may be terminated","He is automatically promoted","He is appointed Permanent Secretary","He is placed on sabbatical leave"]'::jsonb,0,'Correct. Under PSR Rule 020903, the appointment of an Officer on probation who fails to secure confirmation in the pensionable establishment may be terminated.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-875')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Failure to secure confirmation under Rule 020903 is assessed at what point?','["At the expiration of the probationary period, including any prescribed extension","Before assumption of duty only","Only after retirement","Only after annual leave"]'::jsonb,0,'Correct. Under PSR Rule 020903, termination may occur where confirmation is not secured at the expiration of the probationary period, including such extension as prescribed under Rule 020301.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-876')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020903 refers to extension of probation as prescribed under which rule?','["Rule 020301","Rule 120212","Rule 020909","Rule 021101"]'::jsonb,0,'Correct. Under PSR Rule 020903, the probationary period includes any extension prescribed under Rule 020301.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-877')::uuid,'PSR','Chapter 2: Appointments & Career Progression','The termination of an Officer under Rule 020903 is to be done in the manner specified in which rule?','["Rule 020801","Rule 020901","Rule 020501","Rule 021004"]'::jsonb,1,'Correct. PSR Rule 020903 states that termination for failure to secure confirmation is done in the manner specified in Rule 020901.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-878')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020904, what happens to an Officer who resigns in relation to vacation leave claims?','["He forfeits all claims to vacation leave","He receives double vacation leave","He automatically accumulates leave indefinitely","He converts leave into promotion"]'::jsonb,0,'Correct. Under PSR Rule 020904, an Officer who resigns is liable to forfeit all claims to vacation leave.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-879')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Where vacation leave or passage privileges are granted to an Officer who resigns, how are they treated under Rule 020904?','["As statutory entitlement in all cases","As ex-gratia","As pensionable service","As automatic promotion"]'::jsonb,1,'Correct. Under PSR Rule 020904, any vacation leave or passage privileges granted to an Officer who resigns are ex-gratia.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-880')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020904, what must a resigning Officer refund to Government?','["Any sum owed to Government or refundable under rules or agreements","Only the cost of staff identity card","Only annual leave roster charges","Only union dues"]'::jsonb,0,'Correct. Under PSR Rule 020904, a resigning Officer must refund in full any sum owed to Government or refundable under rules or agreements entered into with Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-881')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Why may a resigning Officer be required to refund money under Rule 020904?','["For not discharging obligations set out in an agreement with Government","For taking annual leave in December","For being a senior Officer","For having a leave address"]'::jsonb,0,'Correct. Under PSR Rule 020904, refund may be required where money is refundable for not discharging obligations set out in an agreement with Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-882')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who may waive any or all refunds due from a resigning Officer under Rule 020904?','["Government","The Officer’s colleague","The Staff Union only","The Officer’s family"]'::jsonb,0,'Correct. PSR Rule 020904 provides that any or all such refunds may be waived at the discretion of the Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-883')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises resignation under Rule 020904?','["Resignation always gives automatic pension and leave accumulation","Resignation makes the Officer liable to forfeit vacation leave claims and refund sums owed or refundable to Government","Resignation has no financial consequence","Resignation automatically converts the Officer to contract staff"]'::jsonb,1,'Correct. Under PSR Rule 020904, a resigning Officer forfeits vacation leave claims and must refund sums owed or refundable to Government, subject to possible waiver by Government.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-884')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020905, an Officer who leaves the Service other than by resignation or dismissal is eligible for what?','["Proportionate leave in accordance with Rule 120212","Automatic promotion","Unlimited accumulated leave","Sabbatical leave without approval"]'::jsonb,0,'Correct. Under PSR Rule 020905, an Officer who leaves the Service other than by resignation or dismissal is eligible for proportionate leave in accordance with Rule 120212.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-885')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020905 excludes which two modes of leaving Service from its proportionate leave provision?','["Transfer and secondment","Resignation and dismissal","Posting and redeployment","Promotion and confirmation"]'::jsonb,1,'Correct. PSR Rule 020905 applies to an Officer who leaves the Service other than by resignation or dismissal.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-886')::uuid,'PSR','Chapter 2: Appointments & Career Progression','If an Officer has enjoyed more leave during the leave year than he is eligible to receive, what is required under Rule 020905?','["He must refund salary for the excess working days’ leave enjoyed","He must receive additional leave allowance","He must be promoted automatically","He must repeat the leave year"]'::jsonb,0,'Correct. Under PSR Rule 020905, an Officer who has enjoyed excess leave must refund salary for the number of working days’ leave enjoyed in excess of eligibility.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-887')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For pension purposes, days for which salary is refunded under Rule 020905 are treated as what?','["Sick leave with pay","Leave without pay","Promotion service","Training period"]'::jsonb,1,'Correct. Under PSR Rule 020905, days for which salary is refunded are treated as leave without pay for pension purposes.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-888')::uuid,'PSR','Chapter 2: Appointments & Career Progression','In which case is the refund provision under Rule 020905 waived?','["Where the Officer dies in the Service","Where the Officer resigns voluntarily","Where the Officer is dismissed","Where the Officer refuses examination"]'::jsonb,0,'Correct. Under PSR Rule 020905, the refund provision is waived in the case of an Officer who dies in the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-889')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which rule is specifically referenced for proportionate leave under Rule 020905?','["Rule 120212","Rule 020701","Rule 100301","Rule 021101"]'::jsonb,0,'Correct. PSR Rule 020905 provides that proportionate leave is determined in accordance with Rule 120212.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-890')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020906, an Officer who fails promotion examinations after how many consecutive attempts is deemed to have exited the Service?','["One consecutive attempt","Two consecutive attempts","Three consecutive attempts","Five consecutive attempts"]'::jsonb,2,'Correct. Under PSR Rule 020906, Officers who fail promotion examinations after three consecutive attempts are deemed to have exited the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-891')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020906, an Officer who refuses or fails to write promotion examination for the third time on unacceptable grounds is deemed to have done what?','["Exited from the Service","Qualified for promotion","Completed confirmation","Received automatic study leave"]'::jsonb,0,'Correct. Under PSR Rule 020906, an Officer who absents himself from an examination on unacceptable grounds is deemed to have exited the Service when he refuses to write the examination the third time.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-892')::uuid,'PSR','Chapter 2: Appointments & Career Progression','For absence from promotion examination on grounds of ill-health to be acceptable under Rule 020906, what is required?','["A medical report from a recognized Healthcare Provider","A verbal message from a colleague","A Staff Union note","A private social media post"]'::jsonb,0,'Correct. Under PSR Rule 020906, absence on grounds of ill-health must be supported by a medical report from a recognized Healthcare Provider.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-893')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020906, reasons for absence other than ill-health are evaluated by whom?','["The Officer’s family","The Federal Civil Service Commission","The Staff Union Treasurer","The Officer’s landlord"]'::jsonb,1,'Correct. Under PSR Rule 020906, other reasons for absence from the examination are based on the evaluation of the Federal Civil Service Commission.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-894')::uuid,'PSR','Chapter 2: Appointments & Career Progression','How should Officers who score below the pass mark in a promotion examination be notified under Rule 020906?','["Either in writing or by messages sent to their given e-mail address","Only by public announcement in a market","Only through family members","Only after retirement"]'::jsonb,0,'Correct. Under PSR Rule 020906, Officers who score below the pass mark are notified either in writing or by messages sent to their given e-mail address.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-895')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Who gives the notification to Officers that scored below the pass mark under Rule 020906?','["The authority that conducted the examination","The Officer’s colleague","The Staff Union Chairman","The Officer’s family"]'::jsonb,0,'Correct. Under PSR Rule 020906, notification to Officers who scored below the pass mark is given by the authority that conducted the examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-896')::uuid,'PSR','Chapter 2: Appointments & Career Progression','At what point is an Officer deemed to have exited after failing promotion examinations under Rule 020906?','["After the failed third consecutive attempt","After the first failure","After retirement only","After one month’s leave"]'::jsonb,0,'Correct. Under PSR Rule 020906, the Officer is deemed to have exited the Service after the failed third consecutive attempt.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-897')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects Rule 020906?','["Failure of promotion examinations has no consequence","Three consecutive failures or unacceptable absence from the examination on the third occasion leads to deemed exit from the Service","Only annual leave refusal leads to exit","Only retirement age matters in all cases"]'::jsonb,1,'Correct. PSR Rule 020906 provides that three consecutive failures or unacceptable absence from promotion examination on the third occasion leads to deemed exit from the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-898')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020907, an Officer whose service is no longer required because of abolition of office shall do what?','["Remain in Service indefinitely","Be required to leave the Service","Receive automatic promotion","Proceed on paternity leave"]'::jsonb,1,'Correct. Under PSR Rule 020907, an Officer whose service is no longer required due to abolition of office is required to leave the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-899')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which of the following circumstances is covered by Rule 020907?','["Re-organization of office","Annual leave abroad","Promotion interview only","Appointment on probation"]'::jsonb,0,'Correct. PSR Rule 020907 covers leaving the Service where service is no longer required due to abolition of office, re-organization of office or redundancy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-900')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020907, redundancy may lead to what consequence?','["The Officer may be required to leave the Service","The Officer must be appointed Permanent Secretary","The Officer receives automatic acting appointment","The Officer becomes exempt from PSR"]'::jsonb,0,'Correct. Under PSR Rule 020907, where service is no longer required due to redundancy, the Officer is required to leave the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-901')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which option correctly lists the grounds in Rule 020907?','["Abolition of office, re-organization of office or redundancy","Annual leave, sick leave and maternity leave","Posting, secondment and transfer","Confirmation, promotion and acting appointment"]'::jsonb,0,'Correct. PSR Rule 020907 provides that an Officer whose service is no longer required because of abolition of office, re-organization of office or redundancy shall leave the Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-902')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020908, what is the mandatory retirement age for all grades in the Service?','["50 years","55 years","60 years","65 years"]'::jsonb,2,'Correct. Under PSR Rule 020908, the mandatory retirement age for all grades in the Service is 60 years or 35 years of pensionable service, whichever is earlier.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-903')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020908, what is the maximum pensionable service period before mandatory retirement?','["25 years","30 years","35 years","40 years"]'::jsonb,2,'Correct. Under PSR Rule 020908, mandatory retirement occurs at 60 years of age or 35 years of pensionable service, whichever is earlier.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-904')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which comes first for mandatory retirement under Rule 020908?','["Transfer or secondment","Promotion or confirmation","60 years of age or 35 years of pensionable service","Annual leave or casual leave"]'::jsonb,2,'Correct. Under PSR Rule 020908, retirement is mandatory at 60 years of age or 35 years of pensionable service, whichever is earlier.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-905')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What does Rule 020908 say about remaining in Service after retirement age?','["No Officer shall be allowed to remain in Service after attaining 60 years of age or 35 years of pensionable service, whichever is earlier","An Officer may remain indefinitely after 60 years","Only Directors may ignore the retirement age","Officers may remain if they have unused annual leave"]'::jsonb,0,'Correct. Under PSR Rule 020908, no Officer may remain in Service after attaining 60 years of age or 35 years of pensionable service, whichever is earlier.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-906')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020908 is without prejudice to prevailing conditions of service for which categories?','["Judicial Officers, Academic Staff of Universities and other Officers whose retirement age differs","Junior Officers only","Contract staff only","Officers on leave only"]'::jsonb,0,'Correct. Under PSR Rule 020908, the general retirement rule is without prejudice to prevailing conditions of service for Judicial Officers, Academic Staff of Universities and other Officers whose retirement age is different.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-907')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly summarises mandatory retirement under Rule 020908?','["The Service has no retirement age","All Officers retire only after 70 years","The general rule is 60 years of age or 35 years of pensionable service, whichever is earlier","The rule applies only to Officers on probation"]'::jsonb,2,'Correct. PSR Rule 020908 provides that mandatory retirement is 60 years of age or 35 years of pensionable service, whichever is earlier, subject to stated exceptions.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-908')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020909, when must a Director or equivalent in an MDA compulsorily retire?','["After serving eight years on the post","After one year on the post","Only at age 70","After four months"]'::jsonb,0,'Correct. Under PSR Rule 020909, a Director or its equivalent by whatever nomenclature in MDAs shall compulsorily retire upon serving eight years on the post.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-909')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Rule 020909 applies to a Director or equivalent by whatever nomenclature in which organizations?','["MDAs","Private companies only","Foreign universities only","Staff unions"]'::jsonb,0,'Correct. Under PSR Rule 020909, the eight-year tenure policy applies to a Director or equivalent by whatever nomenclature in MDAs.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-910')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020909, what is the initial term of office of a Permanent Secretary?','["Four years","Two years","Eight years","Ten years"]'::jsonb,0,'Correct. Under PSR Rule 020909, a Permanent Secretary shall hold office for a term of four years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-911')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Under Rule 020909, a Permanent Secretary’s term may be renewed for what further period?','["A further term of four years","A further term of ten years","An unlimited period","A further term of one year"]'::jsonb,0,'Correct. Under PSR Rule 020909, a Permanent Secretary’s four-year term is renewable for a further term of four years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-912')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Renewal of a Permanent Secretary’s term under Rule 020909 is subject to what condition?','["Satisfactory performance","Automatic seniority only","Staff Union endorsement","Annual leave balance"]'::jsonb,0,'Correct. Under PSR Rule 020909, renewal for a further term of four years is subject to satisfactory performance.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-913')::uuid,'PSR','Chapter 2: Appointments & Career Progression','What is the maximum tenure stated for a Permanent Secretary under Rule 020909?','["Four years only","Four years, renewable for a further four years, and no more","Twelve years automatically","Unlimited tenure"]'::jsonb,1,'Correct. Under PSR Rule 020909, a Permanent Secretary holds office for four years, renewable for a further four years subject to satisfactory performance, and no more.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-914')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement correctly reflects the tenure policy under Rule 020909?','["Directors retire after eight years on the post, while Permanent Secretaries serve four years renewable once for another four years subject to satisfactory performance","Directors serve indefinitely, while Permanent Secretaries serve one year only","Directors must retire after two years, while Permanent Secretaries have unlimited tenure","Directors and Permanent Secretaries have no tenure limits"]'::jsonb,0,'Correct. PSR Rule 020909 provides that Directors or equivalent retire after eight years on the post, and Permanent Secretaries serve a four-year term renewable once for four years subject to satisfactory performance.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-915')::uuid,'PSR','Chapter 2: Appointments & Career Progression','Which statement best summarises Chapter 2, Section 9 of the PSR?','["It regulates leaving the Service, including probationary termination, relinquishment, failure to secure confirmation, resignation, proportionate leave, exit after failing promotion examinations, abolition or redundancy, mandatory retirement and tenure policy","It deals only with annual leave abroad","It deals only with acting appointment","It regulates only medical treatment abroad"]'::jsonb,0,'Correct. PSR Chapter 2, Section 9, Rules 020901 to 020909 cover leaving the Service, including probationary termination, relinquishment during probation, failure to secure confirmation, resignation, proportionate leave, exit after failing promotion examinations, abolition of office or redundancy, mandatory retirement and tenure policy.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-916')::uuid,'PSR','Chapter 3: Discipline & Due Process','Under Rule 030501, which Officers are generally required to pass the compulsory confirmation examinations unless exempted by Government?','["Only Officers on retirement leave","Senior Executive Officers, Administrative Officers and Professionals","Only Officers on GL. 03 and below","Only political appointees"]'::jsonb,1,'Correct. Under PSR Chapter 3, Section 5, Rule 030501, unless exempted by Government, Senior Executive Officers, Administrative Officers and Professionals are required to pass the compulsory confirmation examinations.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-917')::uuid,'PSR','Chapter 3: Discipline & Due Process','Within what period must the Officers listed in Rule 030501 pass the compulsory confirmation examinations?','["Within five years of retirement","Within two years of taking up their appointments in the Federal Public Service","Within one month of promotion","Only after thirty-five years of service"]'::jsonb,1,'Correct. Under PSR Rule 030501, the listed Officers are required to pass the examinations within two years of taking up their appointments in the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-918')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which authority may exempt Officers from the requirement to pass the examinations under Rule 030501?','["The Staff Union","The Government","The Officer’s colleague","A private training centre"]'::jsonb,1,'Correct. PSR Rule 030501 begins with the phrase “Unless exempted by the Government,” meaning Government may exempt Officers from the requirement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-919')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which of the following direct appointees is required to pass the examination under Rule 030501?','["A Senior Executive Officer appointed direct to the Federal Public Service on first appointment","A retired contractor","A dismissed Officer","A private-sector employee with no Federal appointment"]'::jsonb,0,'Correct. Under PSR Rule 030501(a), Senior Executive Officers, Administrative Officers and Professionals appointed direct to the Federal Public Service on first appointment are required to pass the examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-920')::uuid,'PSR','Chapter 3: Discipline & Due Process','For direct appointees to be eligible for the examination under Rule 030501(a), how long must they have served after taking up appointment?','["Six months","One week","Five years","Ten years"]'::jsonb,0,'Correct. Under PSR Rule 030501(a), Officers eligible for the examinations must have served for six months after taking up their appointments.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-921')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which statement correctly describes eligibility under Rule 030501(a)?','["Direct appointees must have served for six months after taking up appointment before being eligible for the examination","Direct appointees are eligible only after retirement","Direct appointees must wait ten years before the examination","Direct appointees are never required to pass confirmation examinations"]'::jsonb,0,'Correct. PSR Rule 030501(a) provides that Officers appointed directly must have served for six months after taking up appointment before they are eligible for the examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-922')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which Officers promoted from junior posts are required to pass the examination under Rule 030501(b)?','["Officers promoted from confirmed junior posts only","Senior Executive Officers, Administrative Officers and Professionals promoted from unconfirmed junior posts","Officers promoted after retirement only","Private-sector employees promoted outside the Service"]'::jsonb,1,'Correct. Under PSR Rule 030501(b), Senior Executive Officers, Administrative Officers and Professionals promoted from unconfirmed junior posts are required to pass the examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-923')::uuid,'PSR','Chapter 3: Discipline & Due Process','Rule 030501(b) specifically applies to Officers promoted from what type of junior posts?','["Unconfirmed junior posts","Retired junior posts","Political junior posts","Private junior posts"]'::jsonb,0,'Correct. Under PSR Rule 030501(b), the relevant category is Officers promoted from unconfirmed junior posts.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-924')::uuid,'PSR','Chapter 3: Discipline & Due Process','Under Rule 030501(c), which transferred Officers are required to pass the examination?','["Officers transferred from other Scheduled Service who are under forty years and have not satisfied conditions for confirmation","All Officers transferred after age sixty","Only Officers transferred from private companies","Only retired Officers returning as consultants"]'::jsonb,0,'Correct. Under PSR Rule 030501(c), transferred Officers from other Scheduled Service are required to pass where, at the date of transfer, they are under forty years and have not satisfied conditions for confirmation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-925')::uuid,'PSR','Chapter 3: Discipline & Due Process','For transferred Officers under Rule 030501(c), what is the relevant age condition at the date of transfer?','["Under forty years","Exactly sixty years","Above seventy years","No age condition at all"]'::jsonb,0,'Correct. PSR Rule 030501(c) applies to transferred Officers who, at the date of transfer, are under the age of forty years and have not satisfied conditions for confirmation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-926')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which additional condition applies to transferred Officers under Rule 030501(c)?','["They must not have satisfied conditions for confirmation","They must already be retired","They must be on maternity leave","They must have completed thirty-five years of service"]'::jsonb,0,'Correct. Under PSR Rule 030501(c), transferred Officers from other Scheduled Service must pass the examination if they are under forty years and have not satisfied conditions for confirmation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-927')::uuid,'PSR','Chapter 3: Discipline & Due Process','For further advancement beyond GL. 10, what must Officers do under Rule 030501(d)?','["Attend ASCON, PSIN, CMD or any other approved institution and pass the prescribed examination","Apply for burial expenses","Proceed on indefinite leave","Ignore all confirmation requirements"]'::jsonb,0,'Correct. Under PSR Rule 030501(d), for further advancement beyond GL. 10, Officers shall attend ASCON, PSIN, CMD or any other approved institution and pass the prescribed examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-928')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which institution is listed in Rule 030501(d) for further advancement beyond GL. 10?','["Administrative Staff College of Nigeria","National Youth Service Corps camp only","A private social club","The Officer’s residential association"]'::jsonb,0,'Correct. PSR Rule 030501(d) lists the Administrative Staff College of Nigeria, ASCON, as one of the institutions for Officers seeking further advancement beyond GL. 10.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-929')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which group of institutions is correctly listed under Rule 030501(d)?','["ASCON, PSIN, CMD or any other approved institutions","Only private coaching centres","Only political training schools","Only foreign embassies"]'::jsonb,0,'Correct. Under PSR Rule 030501(d), Officers seeking further advancement beyond GL. 10 shall attend ASCON, PSIN, CMD or any other approved institutions and pass the prescribed examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-930')::uuid,'PSR','Chapter 3: Discipline & Due Process','What is the grade-level threshold mentioned in Rule 030501(d) for further advancement?','["Beyond GL. 10","Below GL. 01","Only GL. 03","Only GL. 06"]'::jsonb,1,'Correct. PSR Rule 030501(d) states that for further advancement beyond GL. 10, Officers shall attend the approved institutions and pass the prescribed examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-931')::uuid,'PSR','Chapter 3: Discipline & Due Process','Under Rule 030502, what may be used where Gazette of first appointment and confirmation of appointment are not available within two years?','["COMPRO examination result","Annual leave roster","Staff Union register","Burial expenses approval"]'::jsonb,0,'Correct. Under PSR Chapter 3, Section 5, Rule 030502, where the Gazette of first appointment and confirmation of appointment are not available within two years, the COMPRO examination result should be used in their place.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-932')::uuid,'PSR','Chapter 3: Discipline & Due Process','Rule 030502 applies where which documents are not available within two years?','["Gazette of first appointment and confirmation of appointment","Medical certificate and leave roster","Pension card and staff identity card","Disciplinary query and reply"]'::jsonb,0,'Correct. Under PSR Rule 030502, the COMPRO result may be used where the Gazette of first appointment and confirmation of appointment are not available within two years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-933')::uuid,'PSR','Chapter 3: Discipline & Due Process','What is the purpose of using COMPRO examination result under Rule 030502?','["To stand in place of Gazette of first appointment and confirmation of appointment when they are not available within two years","To replace annual leave approval permanently","To replace disciplinary procedure","To approve overseas medical treatment"]'::jsonb,0,'Correct. PSR Rule 030502 provides that COMPRO examination result should be used in place of Gazette of first appointment and confirmation of appointment where those documents are not available within two years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-934')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which statement best summarises Chapter 3, Section 5 of the PSR?','["It identifies Officers required to pass compulsory confirmation examinations and provides for the use of COMPRO result where appointment and confirmation Gazettes are unavailable","It deals only with annual leave","It deals only with burial expenses","It regulates medical treatment abroad"]'::jsonb,0,'Correct. PSR Chapter 3, Section 5, Rules 030501 and 030502 cover Officers required to pass compulsory confirmation examinations and the use of COMPRO result where Gazette of first appointment and confirmation of appointment are not available within two years.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-935')::uuid,'PSR','Chapter 3: Discipline & Due Process','Under Rule 030601, who are entitled to be paid fees for confirmation examinations?','["Only candidates who pass the examination","Examiners and invigilators","Only Officers in the Accounts Department","Only members of the Staff Union"]'::jsonb,1,'Correct. Under PSR Chapter 3, Section 6, Rule 030601, fees shall be paid to examiners and invigilators.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-936')::uuid,'PSR','Chapter 3: Discipline & Due Process','Who determines the rates of fees payable to examiners and invigilators under Rule 030601?','["The Office of the Head of the Civil Service of the Federation","The Federal Ministry of Works","The candidates sitting for the examination","The Staff Union Chairman"]'::jsonb,0,'Correct. Under PSR Rule 030601, the rates of fees payable to examiners and invigilators are determined by the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-937')::uuid,'PSR','Chapter 3: Discipline & Due Process','According to Rule 030601, fees are paid to examiners and invigilators at what rates?','["Rates chosen by the candidates","Rates fixed permanently in the Constitution","Rates determined from time to time by the OHCSF","Rates negotiated by individual Officers"]'::jsonb,2,'Correct. Under PSR Rule 030601, fees shall be paid to examiners and invigilators at rates determined from time to time by the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-938')::uuid,'PSR','Chapter 3: Discipline & Due Process','What does the phrase “from time to time” in Rule 030601 imply?','["The rates may be determined or reviewed when necessary by the OHCSF","The rates must never change","The rates are fixed by each candidate","The rates are decided only by invigilators"]'::jsonb,3,'Correct. Under PSR Rule 030601, the phrase “from time to time” means the Office of the Head of the Civil Service of the Federation may determine or review the applicable rates when necessary.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-939')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which office is represented by the abbreviation OHCSF in relation to Rule 030601?','["Office of the Head of the Civil Service of the Federation","Office of Health and Civil Service Finance","Official Headquarters for Confirmation Staff Fees","Office of Human Capital Service Fund"]'::jsonb,0,'Correct. Under PSR Rule 030601, OHCSF refers to the Office of the Head of the Civil Service of the Federation, which determines the rates of fees for examiners and invigilators.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-940')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which statement correctly reflects Rule 030601?','["Fees are paid only to candidates who pass the examination","Fees are paid to examiners and invigilators at rates determined by the OHCSF","Fees are paid only to Permanent Secretaries","Fees are paid to all Officers whether involved in the examination or not"]'::jsonb,1,'Correct. PSR Chapter 3, Section 6, Rule 030601 provides that fees shall be paid to examiners and invigilators at rates determined from time to time by the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-941')::uuid,'PSR','Chapter 3: Discipline & Due Process','Rule 030601 is mainly concerned with which subject?','["Disciplinary procedure for misconduct","Annual leave computation","Burial expenses","Fees for invigilators and examiners"]'::jsonb,3,'Correct. PSR Chapter 3, Section 6 is titled “Fees for Invigilators and Examiners,” and Rule 030601 provides for payment of fees to examiners and invigilators.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-942')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which of the following is NOT provided for under Rule 030601?','["Payment of fees to examiners","Payment of fees to invigilators","Determination of rates by the OHCSF","Payment of examination fees to candidates"]'::jsonb,3,'Correct. PSR Rule 030601 provides for payment of fees to examiners and invigilators, not to candidates sitting for the examination.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-943')::uuid,'PSR','Chapter 3: Discipline & Due Process','If a question asks who fixes the applicable fees for invigilators and examiners, the correct answer is what?','["The candidates","The Office of the Head of the Civil Service of the Federation","The private training centre","The Staff Union"]'::jsonb,1,'Correct. Under PSR Rule 030601, the Office of the Head of the Civil Service of the Federation determines the applicable rates of fees for examiners and invigilators.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-944')::uuid,'PSR','Chapter 3: Discipline & Due Process','Which statement best summarises Chapter 3, Section 6 of the PSR?','["It provides that examiners and invigilators shall be paid fees at rates determined from time to time by the OHCSF","It lists the subjects for junior confirmation examinations","It sets the rules for annual leave and casual leave","It explains the disciplinary procedure for serious misconduct"]'::jsonb,0,'Correct. PSR Chapter 3, Section 6, Rule 030601 states that fees shall be paid to examiners and invigilators at rates determined from time to time by the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-945')::uuid,'PSR','Chapter 5: Performance Management','Why must Performance Management practice at all levels in the Federal Public Service be monitored regularly?','["To abolish performance appraisal completely","To ensure compliance, feedback and improvement","To replace all MDAs with the OHCSF","To stop the use of performance targets"]'::jsonb,1,'Correct. Under PSR Chapter 5, Section 7, Rule 050701, Performance Management practice at all levels in the Federal Public Service shall be monitored regularly to ensure compliance, feedback and improvement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-946')::uuid,'PSR','Chapter 5: Performance Management','What is the scope of monitoring under Rule 050701?','["Only Officers on probation","Only retired Officers","Performance Management practice at all levels in the Federal Public Service","Only Officers on foreign training"]'::jsonb,2,'Correct. Under PSR Rule 050701, monitoring applies to Performance Management practice at all levels in the Federal Public Service.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-947')::uuid,'PSR','Chapter 5: Performance Management','Who is responsible for regularly monitoring Performance Management practice for feedback and improvement?','["The Staff Union","The Central Coordinating Body","The private sector employer","The Officer being appraised"]'::jsonb,1,'Correct. Under PSR Rule 050701, regular monitoring for feedback and improvement is to be carried out by the Central Coordinating Body.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-948')::uuid,'PSR','Chapter 5: Performance Management','Which statement best reflects Rule 050701?','["Performance Management practice is monitored only when there is a disciplinary case","Performance Management practice is optional and need not be monitored","Performance Management practice shall be monitored regularly for compliance, feedback and improvement","Performance Management practice applies only to contract staff"]'::jsonb,2,'Correct. PSR Rule 050701 provides that Performance Management practice at all levels in the Federal Public Service shall be monitored regularly for compliance, feedback and improvement.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-949')::uuid,'PSR','Chapter 5: Performance Management','Regular monitoring of Performance Management practice is intended to support which of the following?','["Compliance and improvement","Unapproved absence from duty","Political appointments only","Termination without appraisal"]'::jsonb,0,'Correct. Under PSR Rule 050701, the purpose of regular monitoring is to ensure compliance, feedback and improvement in Performance Management practice.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-950')::uuid,'PSR','Chapter 5: Performance Management','Where is the Central Coordinating Body for monitoring the effectiveness of the Performance Management process domiciled?','["Federal Ministry of Finance","The Office of the Head of the Civil Service of the Federation","The Bureau of Public Procurement","The Staff Union Secretariat"]'::jsonb,1,'Correct. Under PSR Chapter 5, Section 7, Rule 050702, the Central Coordinating Body responsible for monitoring the effectiveness of the Performance Management process shall be domiciled in the OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-951')::uuid,'PSR','Chapter 5: Performance Management','What is the responsibility of the Central Coordinating Body under Rule 050702?','["To monitor the effectiveness of the Performance Management process","To conduct private business for Officers","To approve annual leave for all Officers","To replace disciplinary procedures"]'::jsonb,0,'Correct. Under PSR Rule 050702, the Central Coordinating Body is responsible for monitoring the effectiveness of the Performance Management process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-952')::uuid,'PSR','Chapter 5: Performance Management','The abbreviation OHCSF in Rule 050702 refers to which institution?','["Office of the Head of the Civil Service of the Federation","Office of Health Care Services Federation","Official House Committee on Staff Finance","Office of Human Capital Staff Forum"]'::jsonb,0,'Correct. Under PSR Rule 050702, the Central Coordinating Body is domiciled in the OHCSF, meaning the Office of the Head of the Civil Service of the Federation.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-953')::uuid,'PSR','Chapter 5: Performance Management','Which statement is correct under Rule 050702?','["The Central Coordinating Body is domiciled in the OHCSF","The Central Coordinating Body is domiciled in each Staff Union branch","The Central Coordinating Body is domiciled in a private company","The Central Coordinating Body is domiciled in every Officer’s department"]'::jsonb,0,'Correct. PSR Rule 050702 states that the Central Coordinating Body responsible for monitoring the effectiveness of the Performance Management process shall be domiciled in the OHCSF.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-954')::uuid,'PSR','Chapter 5: Performance Management','The Central Coordinating Body monitors effectiveness of what process?','["The recruitment examination only","The Performance Management process","The burial expenses process","The annual leave computation process"]'::jsonb,1,'Correct. Under PSR Rule 050702, the Central Coordinating Body monitors the effectiveness of the Performance Management process.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-955')::uuid,'PSR','Chapter 5: Performance Management','Who owns records generated during any phase of the annual Performance Management cycle?','["The individual Officer alone","The Staff Union","The Federal Government of Nigeria","The private consultant managing the system"]'::jsonb,2,'Correct. Under PSR Chapter 5, Section 7, Rule 050703, all records generated during any phase of the annual Performance Management cycle are and shall remain the property of the Federal Government of Nigeria.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-956')::uuid,'PSR','Chapter 5: Performance Management','Which records are covered by Rule 050703?','["Only records generated after retirement","Only records created during disciplinary dismissal","All records generated during any phase of the annual Performance Management cycle","Only private records kept by Officers"]'::jsonb,2,'Correct. Under PSR Rule 050703, all records generated during any of the phases of the annual Performance Management cycle are covered.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-957')::uuid,'PSR','Chapter 5: Performance Management','How should records generated during the annual Performance Management cycle be administered?','["According to personal preference of each Officer","In line with good administrative document and data management practices","By deleting them immediately after appraisal","By publishing them on public notice boards"]'::jsonb,1,'Correct. Under PSR Rule 050703, all such records shall be administered in line with good administrative document and data management practices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-958')::uuid,'PSR','Chapter 5: Performance Management','Which statement best reflects the records-management rule under Rule 050703?','["Performance Management records belong to the Federal Government and must be properly administered","Performance Management records belong only to the supervisor personally","Performance Management records must always be destroyed after appraisal","Performance Management records are not official documents"]'::jsonb,0,'Correct. PSR Rule 050703 provides that all records generated during the annual Performance Management cycle remain the property of the Federal Government of Nigeria and must be administered in line with good administrative document and data management practices.') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.questions(id,category,chapter,question_text,options,correct_option_index,explanation) VALUES (md5('psr:excel-q-959')::uuid,'PSR','Chapter 5: Performance Management','Which statement best summarises Chapter 5, Section 7 of the PSR?','["It deals with annual leave and maternity leave only","It deals with monitoring and evaluation of Performance Management, the OHCSF-based Coordinating Body, and records management","It deals only with recruitment into GL 07 and above","It deals only with disciplinary dismissal"]'::jsonb,1,'Correct. PSR Chapter 5, Section 7, Rules 050701 to 050703 cover regular monitoring and evaluation of Performance Management, the Central Coordinating Body domiciled in the OHCSF, and management of records generated during the annual Performance Management cycle.') ON CONFLICT(id) DO NOTHING;
